window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["pc6b28bdffd"]={"id":"pc6b28bdffd","name":"2026年福建省公务员录用考试《行测》题（网友回忆版）","year":2026,"region":"福建","count":120,"types":{"时事政治":5,"新思想":13,"马克思主义":2,"法律常识":3,"地理国情":4,"人文常识":6,"科技常识":2,"逻辑填空":10,"片段阅读":16,"语句表达":4,"数学运算":10,"图形推理":5,"定义判断":10,"类比推理":5,"逻辑判断":10,"综合":7,"比重":3,"平均数":2,"增长":3},"modules":["政治理论","常识判断","言语理解与表达","数量关系","判断推理","资料分析"],"moduleCounts":{"政治理论":20,"常识判断":15,"言语理解与表达":30,"数量关系":10,"判断推理":30,"资料分析":15},"coverage":{"basis":"网友回忆版","sourceCount":120,"expectedCount":null,"missingCount":null},"questions":[{"qid":"16070032","no":1,"type":"时事政治","module":"政治理论","stem":"<p>习近平总书记强调，学习好贯彻好党的二十届四中全会精神，是当前和今后一个时期全党全国的一项重大政治任务。关于党的二十届四中全会精神，下列表述正确的是（    ）。</p>","options":[{"k":"A","t":"把捍卫经济安全摆在首位，加强重点领域国家安全能力建设，突出保障事关国家长治久安、经济健康稳定、人民安居乐业的重大安全"},{"k":"B","t":"坚定不移推动高质量发展，构建以新兴产业和未来产业为骨干的现代化产业体系"},{"k":"C","t":"坚定不移扩大高水平对外开放，做强国内国际大循环，加快构建新发展格局"},{"k":"D","t":"加强普惠性、基础性、兜底性民生建设，稳步推进基本公共服务均等化"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>2025年10月23日，党的二十届四中全会审议通过了《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》（以下简称《建议》）。<br>A项错误，《建议》在：“十三、推进国家安全体系和能力现代化，建设更高水平平安中国”部分指出：“（50）加强重点领域国家安全能力建设。锻造实战实用的国家安全能力，突出保障事关国家长治久安、经济健康稳定、人民安居乐业的重大安全，把捍卫政治安全摆在首位······”故“把捍卫经济安全摆在首位”表述错误，应为“把捍卫政治安全摆在首位”。<br>B项错误，《建议》在“三、建设现代化产业体系，巩固壮大实体经济根基”部分指出：“······坚持把发展经济的着力点放在实体经济上，坚持智能化、绿色化、融合化方向，加快建设制造强国、质量强国、航天强国、交通强国、网络强国，保持制造业合理比重，构建以先进制造业为骨干的现代化产业体系。故“以新兴产业和未来产业为骨干”表述错误，应为“以先进制造业为骨干”。<br>C项错误，2026年1月1日出版的第1期《求是》杂志发表了习近平总书记的重要文章《学习好贯彻好党的二十届四中全会精神》。文章指出：“第二，加快构建新发展格局。做强国内大循环、畅通国内国际双循环，是我们把握发展主动权、塑造国际合作和竞争新优势的战略举措······坚定不移扩大高水平对外开放，维护多边贸易体制······”故“做强国内国际大循环”表述错误，应为“做强国内大循环”。<br>D项正确，《建议》在“十一、加大保障和改善民生力度，扎实推进全体人民共同富裕”部分指出：“实现人民对美好生活的向往是中国式现代化的出发点和落脚点。坚持尽力而为、量力而行，加强普惠性、基础性、兜底性民生建设······（44）稳步推进基本公共服务均等化。建立基本公共服务均等化评价标准，完善基本公共服务范围和内容，制定实现基本公共服务均等化的目标、路径、措施······”<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"pc6b28bdffd"},{"qid":"16069979","no":2,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届四中全会提出，要增强区域发展协调性。下列与之相关说法正确的是（    ）。<br>①高标准高质量推进雄安新区建设现代化城市<br>②提升成渝地区双城经济圈发展能级<br>③鼓励各地发挥比较优势、各展所长，支持经济大省挑大梁<br>④持续推进长江经济带发展、黄河流域生态保护和高质量发展<br>⑤巩固提升京津冀、长三角、中部地区高质量发展动力源作用</p>","options":[{"k":"A","t":"①②③④⑤"},{"k":"B","t":"①②④⑤"},{"k":"C","t":"②③④⑤"},{"k":"D","t":"①②③④"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>①②③④正确，⑤错误。2025年10月23日，党的二十届四中全会审议通过了《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》（以下简称《建议》）。《建议》在“九、优化区域经济布局，促进区域协调发展”中“（28）增强区域发展协调性”部分指出：“扎实推动西部大开发形成新格局、东北全面振兴取得新突破、中部地区加快崛起、东部地区加快推进现代化，促进东中西、南北方协调发展。巩固提升京津冀、长三角、粤港澳大湾区高质量发展动力源作用。持续推进长江经济带发展、黄河流域生态保护和高质量发展。高标准高质量推进雄安新区建设现代化城市，提升成渝地区双城经济圈发展能级。鼓励各地发挥比较优势、各展所长，支持经济大省挑大梁，在推进中国式现代化中走在前作示范。加大差异化政策支持力度，促进革命老区、民族地区、边疆地区等振兴发展。”故⑤中“巩固提升京津冀、长三角、中部地区高质量发展动力源作用”说法错误，应为“巩固提升京津冀、长三角、粤港澳大湾区高质量发展动力源作用”。<br>故正确的有①②③④。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"pc6b28bdffd"},{"qid":"16069981","no":3,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届四中全会提出，加快农业农村现代化，扎实推进乡村全面振兴。下列与之相关说法正确的是（    ）。<br>①坚持把解决好“三农”问题作为全党工作重中之重<br>②统筹发展科技农业、绿色农业、质量农业、品牌农业<br>③稳定土地承包关系，稳步推进三轮承包到期后再延长三十年试点<br>④因地制宜完善乡村建设实施机制，分类有序、一体化推进乡村振兴<br>⑤健全财政优先保障、金融重点倾斜、社会积极参与的多元投入格局，确保乡村振兴投入力度不断增强</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②⑤"},{"k":"C","t":"①②④⑤"},{"k":"D","t":"②③④⑤"}],"answer":"B","multi":false,"explanation":"<p>本题考查新思想。<br>2025年10月23日，《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》发布，以下简称《建议》。<br>①正确，《建议》在“八、加快农业农村现代化，扎实推进乡村全面振兴”部分指出：“坚持把解决好‘三农’问题作为全党工作重中之重，促进城乡融合发展，持续巩固拓展脱贫攻坚成果，推动农村基本具备现代生活条件，加快建设农业强国。”<br>②正确，③错误，《建议》在“八、加快农业农村现代化，扎实推进乡村全面振兴”部分指出：“（25）提升农业综合生产能力和质量效益。坚持产量产能、生产生态、增产增收一起抓，统筹发展科技农业、绿色农业、质量农业、品牌农业，把农业建成现代化大产业······稳定土地承包关系，稳步推进二轮承包到期后再延长三十年试点。”故③中“三轮承包”表述错误，应为“二轮承包”。<br>④错误，《建议》在“八、加快农业农村现代化，扎实推进乡村全面振兴”部分指出：“（26）推进宜居宜业和美乡村建设。学习运用‘千万工程’经验，因地制宜完善乡村建设实施机制，分类有序、片区化推进乡村振兴，逐步提高农村基础设施完备度、公共服务便利度、人居环境舒适度。”故“一体化”表述错误，应为“片区化”。<br>⑤正确，《建议》在“八、加快农业农村现代化，扎实推进乡村全面振兴”部分指出：“（27）提高强农惠农富农政策效能。健全财政优先保障、金融重点倾斜、社会积极参与的多元投入格局，确保乡村振兴投入力度不断增强。保护和调动农民务农种粮积极性，强化价格、补贴、保险等政策支持和协同。”<br>故①②⑤表述正确。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"pc6b28bdffd"},{"qid":"16069991","no":4,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康，关系党和国家长治久安。关于全面依法治国，下列说法正确的是（    ）。<br>①全面依法治国是中国特色社会主义的本质要求和重要保障<br>②全面依法治国要坚持依法治国、依法执政、依法行政共同推进<br>③全面依法治国要坚持法治国家、法治政府、法治社会一体建设<br>④全面依法治国要坚持依法治国和依规治党有机统一</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"②③④"},{"k":"D","t":"①②③④"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>①②③④正确，2017年10月18日，党的十九大报告在“三、新时代中国特色社会主义思想和基本方略”部分指出：“（六）坚持全面依法治国。全面依法治国是中国特色社会主义的本质要求和重要保障······坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设，坚持依法治国和以德治国相结合，依法治国和依规治党有机统一，深化司法体制改革，提高全民族法治素养和道德素质。”<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"pc6b28bdffd"},{"qid":"16069988","no":5,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，“十五五”时期，必须把因地制宜发展新质生产力摆在更加突出的战略位置。下列与之相关表述正确的是（    ）。<br>①要统筹推进教育科技人才一体发展<br>②要完善国家创新体系，激发各类创新主体活力<br>③要在加强基础研究、提高原始创新能力上持续用力<br>④要全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"②③④"},{"k":"D","t":"①②③④"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>①②③④正确，2025年4月30日，习近平总书记在上海主持召开部分省区市“十五五”时期经济社会发展座谈会并发表重要讲话强调，“十五五”时期，必须把因地制宜发展新质生产力摆在更加突出的战略位置，以科技创新为引领、以实体经济为根基，坚持全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体系。要完善国家创新体系，激发各类创新主体活力，瞄准世界科技前沿，在加强基础研究、提高原始创新能力上持续用力，在突破关键核心技术、前沿技术上抓紧攻关。要统筹推进教育科技人才一体发展，筑牢新质生产力发展的基础性、战略性支撑。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":4,"pid":"pc6b28bdffd"},{"qid":"16069993","no":6,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，要站在推进强国建设、民族复兴伟业的战略高度，推动我国未来产业发展不断取得新突破。关于推动我国未来产业发展，下列举措恰当的有几项？（    ）<br>①要综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，发挥优势、同步发展<br>②要发挥政府主体作用，推动各类创新资源向企业集聚<br>③要充分发挥新型举国体制优势，坚持“产业出题、科技答题”<br>④要统筹发展和安全，探索科学有效的监管方式，防范相关风险，确保既“放得活”又“管得好”</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"B","multi":false,"explanation":"<p>本题考查新思想。<br>2026年1月30日下午，中共中央政治局就前瞻布局和发展未来产业进行第二十四次集体学习。习近平总书记在听取讲解和讨论后发表重要讲话。<br>①错误，习近平总书记强调：“要聚焦‘十五五’时期我国未来产业发展的主攻方向，科学论证技术路线，提升前沿技术战略预判能力。要综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，因地制宜、错位发展。要强化产业协同，推动未来产业同新兴产业、传统产业相得益彰。”故“发挥优势、同步发展”表述错误，应为“因地制宜、错位发展”。<br>②错误，习近平总书记强调：“很多未来产业的兴起是靠企业一步步突破带动的。要发挥企业主体作用，推动各类创新资源向企业集聚，大力培育核心技术领先、创新能力强的科技领军企业和高新技术企业，引领带动产业向前沿和高端领域迈进。”故“要发挥政府主体作用”表述错误，应为“要发挥企业主体作用”。<br>③正确，习近平总书记指出：“科技突破的程度，很大程度上决定未来产业发展的速度、广度、深度。要充分发挥新型举国体制优势，坚持‘产业出题、科技答题’，加大重点领域关键核心技术攻关力度，加强基础研究战略性、前瞻性、体系化布局，加快科技成果转化应用。”<br>④正确，习近平总书记强调：“未来产业发展涉及面广，必须健全治理体系。要统筹发展和安全，探索科学有效的监管方式，防范相关风险，确保既‘放得活’又‘管得好’。要深化国际合作，积极推动各方标准共建、规则共商、产业共促。各级领导干部要加强科技前沿知识学习，努力做到知科技、懂产业、善决策。”<br>综上，③④表述正确，共2项。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":5,"pid":"pc6b28bdffd"},{"qid":"16069999","no":7,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，加快构建全国统一大市场，着力整治一些领域的“内卷式”竞争。关于深刻认识和综合整治“内卷式”竞争，下列说法正确的是（    ）。</p>","options":[{"k":"A","t":"“内卷式”竞争的根源是我国的人口基数过大"},{"k":"B","t":"“内卷式”竞争是市场经济发展的必然现象"},{"k":"C","t":"“内卷式”竞争会带来资源耗损、无序竞争"},{"k":"D","t":"整治“内卷式”竞争要从严从实从快"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2025年7月，《求是》杂志发表《深刻认识和综合整治“内卷式”竞争》（以下简称文章）。<br>A项错误，文章指出，作为当前经济发展中的突出现象，“内卷式”竞争的形成原因具有多维性和复杂性，涉及企业、行业、政府多个方面，既有经济发展和技术进步等规律性因素，也有深层次体制机制问题，还有经济主体的路径依赖等原因，是多种因素综合形成的。由此可见，“内卷式”竞争与人口基数无直接关联。<br>B项错误，文章指出，市场配置资源是最有效率的形式，竞争是市场经济运行的重要机制。通过竞争优化资源配置、实现优胜劣汰，倒逼企业不断创新技术、改善经营管理，进而提高经济运行效率，促进经济发展、技术进步，这是市场经济的优势所在······市场竞争有利于提高资源配置效率，可一旦竞争过了头、越了界，演变成无序“内卷”，就会扭曲市场机制、破坏市场公平，造成诸多负面影响。因此，竞争过度是市场经济演进中的阶段性问题，并非“必然现象”。<br>C项正确，文章指出，现实中，“内卷式”竞争表现不同、特征各异，主要涉及企业和地方政府两类行为主体······从地方政府行为看，“内卷式”竞争主要表现为：一是为招引企业、培育产业，人为制造政策洼地，违规实施税费、补贴、用地等不公平非普惠的优惠政策，导致无序竞争；二是不顾地方产业基础和资源禀赋情况，盲目上马新兴产业、重点产业，造成行业内大量重复建设和生产过剩；三是为保护本地市场、扶持本地企业，设置或明或暗的市场壁垒，区别对待各类企业，破坏公平竞争秩序。故“内卷式”竞争会带来资源耗损、无序竞争说法正确。<br>D项错误，文章指出，整治“内卷式”竞争是一项复杂的系统性工程，不可能一蹴而就、一招制胜，需要遵循经济规律，汇集各方力量，多管齐下，综合整治。故“从快”表述错误。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":6,"pid":"pc6b28bdffd"},{"qid":"16069982","no":8,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，在长期实践中，中国和中亚国家探索形成了“互尊、互信、互利、互助，以高质量发展推进共同现代化”的“中国—中亚精神”。下列属于其独特精神内涵的是（    ）。<br>①坚持相互尊重、平等相待，国家不分大小一视同仁，有事大家商量着办，协商一致作决策<br>②坚持互利共赢、共同发展，互为优先伙伴，互予发展机遇，兼顾各方利益，实现多赢共生<br>③坚持普惠包容、和谐共生，中国将大力支持中亚国家能源绿色低碳发展，不再新建境外煤电项目<br>④坚持深化互信、同声相应，坚定支持彼此维护国家独立、主权、领土完整和民族尊严，不做任何损害彼此核心利益的事<br>⑤坚持守望相助、同舟共济，支持彼此走符合国情的发展道路，办好自己的事情，合力应对各类风险挑战，共同维护地区安全稳定</p>","options":[{"k":"A","t":"①②④"},{"k":"B","t":"①②④⑤"},{"k":"C","t":"①③④⑤"},{"k":"D","t":"②③④⑤"}],"answer":"B","multi":false,"explanation":"<p>本题考查新思想。<br>①②④⑤正确，③错误，当地时间2025年6月17日下午，第二届中国—中亚峰会在阿斯塔纳独立宫举行。中国国家主席习近平在发表主旨发言时表示，在长期实践中，我们探索形成了“互尊、互信、互利、互助，以高质量发展推进共同现代化”的“中国—中亚精神”：坚持相互尊重、平等相待，国家不分大小一视同仁，有事大家商量着办，协商一致作决策；坚持深化互信、同声相应，坚定支持彼此维护国家独立、主权、领土完整和民族尊严，不做任何损害彼此核心利益的事；坚持互利共赢、共同发展，互为优先伙伴，互予发展机遇，兼顾各方利益，实现多赢共生；坚持守望相助、同舟共济，支持彼此走符合国情的发展道路，办好自己的事情，合力应对各类风险挑战，共同维护地区安全稳定。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":7,"pid":"pc6b28bdffd"},{"qid":"16070002","no":9,"type":"马克思主义","module":"政治理论","stem":"<p>习近平总书记指出，要提高政治判断力、政治领悟力、政治执行力，主动识变求变应变，强化全局视野和系统思维，加强改革政策统筹、进度统筹、效果统筹，发挥改革整体效应。这一论述最能体现马克思主义的哪些基本观点？<br>①实践是检验真理的唯一标准<br>②系统的存在依赖于要素之间的相关性中产生的有机统一体<br>③质变是量变的必然结果，量变达到一定程度必然引起质变<br>④尊重客观规律是正确发挥主观能动性的前提</p>","options":[{"k":"A","t":"①②"},{"k":"B","t":"②④"},{"k":"C","t":"①③"},{"k":"D","t":"③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查马克思主义。<br>①错误，“实践是检验真理的唯一标准”强调的是实践作为检验真理标准的绝对性、确定性，即认识是否是真理，只有通过实践来检验，此外再无别的检验真理的办法。题干强调的是“提高政治能力”“主动识变求变应变”“强化全局视野和系统思维”以及“加强改革政策统筹”，并未直接提及实践作为检验真理的标准。<br>②正确，“系统的存在依赖于要素之间的相关性中产生的有机统一体”强调的是整体性和各要素之间的相互关联，即系统思维。题干中“强化全局视野和系统思维”“加强改革政策统筹、进度统筹、效果统筹”“发挥改革整体效应”体现的是系统思维，即系统是由相互关联的要素组成的有机整体，统筹协调才能发挥整体效应。<br>③错误，“质变是量变的必然结果，量变达到一定程度必然引起质变”讨论的是量变与质变的关系。题干强调的是“强化全局视野和系统思维”“发挥改革整体效应”等系统思维，并未涉及量变和质变相关哲学原理。<br>④正确，“尊重客观规律是正确发挥主观能动性的前提”是指只有从客观实际出发，尊重客观规律，按客观规律办事，才能正确地发挥人的主观能动性，最终实现人们预期的目的。题干中“主动识变求变应变”中的“识变”意味着尊重和认识客观规律和变化，“求变应变”是在尊重规律基础上发挥主观能动性。同时，“提高政治能力”都需要在尊重规律的前提下发挥主观能动性。<br>综上，②④正确。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":8,"pid":"pc6b28bdffd"},{"qid":"16069985","no":10,"type":"马克思主义","module":"政治理论","stem":"<p>习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利80周年招待会上强调：“一时强弱在于力，千秋胜负在于理。正义、光明、进步必将战胜邪恶、黑暗、反动。”这一论述最能体现马克思主义的哪些基本观点？（    ）<br>①上层建筑和经济基础具有同一性<br>②事物的主要矛盾决定事物发展的方向<br>③事物的发展是前进性与曲折性的统一<br>④人的认识能够反映和改造世界</p>","options":[{"k":"A","t":"①③"},{"k":"B","t":"②③"},{"k":"C","t":"①④"},{"k":"D","t":"③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查马克思主义。<br>①错误，马克思主义认为，经济基础决定上层建筑，上层建筑反作用于经济基础，二者是辩证统一的，并非简单的“具有同一性”。且题干围绕“一时强弱”与“千秋胜负”展开，强调正义、进步力量最终必胜，核心是历史发展趋势与规律问题，并未涉及社会结构中的经济基础与上层建筑的关系。<br>②正确，马克思主义认为，主要矛盾是指在复杂事物发展过程中处于支配地位、对事物发展起决定作用的矛盾。“一时强弱在于力”中的“力”即当下凸显的矛盾，造成一时强弱之分；而“千秋胜负在于理”中的“理”即符合历史发展规律的正义力量，是决定历史长期走向的核心因素，体现了主要矛盾对事物发展方向的决定作用。<br>③正确，马克思主义认为，事物发展的总趋势是前进的、上升的，但发展的道路是曲折的、迂回的，任何新事物的成长都要经历一个由弱到强的过程。题干中“一时强弱在于力”体现了事物发展的曲折性，即反动、落后势力可能在短期内凭借力量占据优势；“千秋胜负在于理”“正义、光明、进步必将战胜邪恶、黑暗、反动”则鲜明体现了历史发展的前进性和必然性。整句话既承认暂时的力量对比，又坚信长远的正义必胜，体现了事物的发展是前进性与曲折性的统一。<br>④错误，马克思主义认为，认识是实践基础上主体对客体的能动的反映，即认识能够反映世界，同时认识可以指导实践改造世界，但认识本身无法直接改造世界，故选项本身说法存在错误。<br>故②③表述正确。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":9,"pid":"pc6b28bdffd"},{"qid":"16070020","no":11,"type":"新思想","module":"政治理论","stem":"<p>党的二十大以来，习近平总书记亲自决策部署和推动区域发展各项战略实施，擘画区域发展蓝图。下列省市与其发展方向对应不准确的是（    ）。</p>","options":[{"k":"A","t":"山东——加快建设绿色低碳高质量发展先行区，打造高水平对外开放新高地"},{"k":"B","t":"湖北——要在长江经济带高质量发展中奋勇争先，加快建成中部地区崛起的重要战略支点"},{"k":"C","t":"重庆——主动服务和融入新发展格局，奋力打造新时代西部大开发重要战略支点、内陆开放综合枢纽"},{"k":"D","t":"河南——在打造国家重要先进制造业高地、具有核心竞争力的科技创新高地、内陆地区改革开放高地上持续用力"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>A项正确，2024年5月22日至24日，习近平总书记在山东考察时强调，山东要在全国发展大局中定好位、挑大梁，完整准确全面贯彻新发展理念，以进一步全面深化改革为动力，继续在服务和融入新发展格局上走在前、在增强经济社会发展创新力上走在前、在推动黄河流域生态保护和高质量发展上走在前，加快建设绿色低碳高质量发展先行区，打造高水平对外开放新高地，奋力谱写中国式现代化山东篇章。<br>B项正确，2024年11月4日至6日，习近平总书记在湖北考察时强调，湖北要深入贯彻党的二十大和二十届三中全会精神，坚持稳中求进工作总基调，牢牢把握在构建新发展格局中的使命任务，充分发挥自身优势，鼓足干劲、奋发进取，久久为功、善作善成，在长江经济带高质量发展中奋勇争先，加快建成中部地区崛起的重要战略支点，奋力谱写中国式现代化湖北篇章。<br>C项正确，2024年4月22日至24日，习近平总书记在重庆考察时强调，重庆要对标新时代新征程党的中心任务和党中央赋予的使命，充分发挥比较优势、后发优势，进一步全面深化改革开放，主动服务和融入新发展格局，着力推动高质量发展，奋力打造新时代西部大开发重要战略支点、内陆开放综合枢纽，在发挥“三个作用”上展现更大作为，不断谱写中国式现代化重庆篇章。<br>D项错误，2024年3月18日至21日，习近平总书记在湖南考察时强调，湖南要牢牢把握自身在构建新发展格局中的战略定位，坚持稳中求进工作总基调，坚持高质量发展不动摇，坚持改革创新、求真务实，在打造国家重要先进制造业高地、具有核心竞争力的科技创新高地、内陆地区改革开放高地上持续用力，在推动中部地区崛起和长江经济带发展中奋勇争先，奋力谱写中国式现代化湖南篇章。2025年5月19日至20日，习近平总书记在河南考察时强调，河南要认真落实党中央关于中部地区加快崛起、黄河流域生态保护和高质量发展等战略部署，坚持稳中求进工作总基调，全面深化改革开放，着力建设现代化产业体系和农业强省，着力改善民生、加强社会治理，着力加强生态环境保护，着力推动文化繁荣兴盛，以高质量发展和高效能治理奋力谱写中原大地推进中国式现代化新篇章。故“在打造国家重要先进制造业高地、具有核心竞争力的科技创新高地、内陆地区改革开放高地上持续用力”对应的省份应为湖南，而非河南。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":10,"pid":"pc6b28bdffd"},{"qid":"16069872","no":12,"type":"新思想","module":"政治理论","stem":"<p>高质量发展是全面建设社会主义现代化国家的首要任务。下列对高质量发展核心要求的理解，正确的有几项？<br>①高质量发展当然要做大蛋糕，但它同时要求分好蛋糕<br>②高质量发展意味着可以暂时容忍一定程度的环境污染以换取发展空间<br>③高质量发展不仅仅是对经济领域的要求，也包括社会、文化、生态等各个领域<br>④推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>①正确，2022年1月17日，习近平总书记在2022年世界经济论坛视频会议上发表题为《坚定信心 勇毅前行 共创后疫情时代美好世界》的演讲中指出：“中国要实现共同富裕，但不是搞平均主义，而是要先把‘蛋糕’做大，然后通过合理的制度安排把‘蛋糕’分好，水涨船高、各得其所，让发展成果更多更公平惠及全体人民。”<br>②错误，2013年5月24日，中共中央政治局就大力推进生态文明建设进行第六次集体学习，习近平总书记强调：“要正确处理好经济发展同生态环境保护的关系，牢固树立保护生态环境就是保护生产力、改善生态环境就是发展生产力的理念，更加自觉地推动绿色发展、循环发展、低碳发展，决不以牺牲环境为代价去换取一时的经济增长。”故“可以暂时容忍一定程度的环境污染以换取发展空间”说法错误，应为“决不以牺牲环境为代价去换取一时的经济增长”。<br>③正确，2021年，习近平总书记参加十三届全国人大四次会议青海代表团审议时强调：“高质量发展不只是一个经济要求，而是对经济社会发展方方面面的总要求；不是只对经济发达地区的要求，而是所有地区发展都必须贯彻的要求；不是一时一事的要求，而是必须长期坚持的要求。”<br>④正确，党的二十大报告中“十、推动绿色发展，促进人与自然和谐共生”部分指出：“（一）加快发展方式绿色转型。推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节。”<br>综上，①③④表述正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":11,"pid":"pc6b28bdffd"},{"qid":"16070024","no":13,"type":"新思想","module":"政治理论","stem":"<p>发展全过程人民民主是中国式现代化的本质要求。关于发展全过程人民民主，下列说法正确的有几项？（    ）<br>①人民政协要坚持新时代中国特色社会主义思想这个统揽政协工作的总纲<br>②党外人士要牢牢把握中国共产党领导这个中国新型政党制度的根本特征<br>③把不断巩固团结奋斗的共同思想政治基础作为新时代党的民族工作主线<br>④“三重一大”决策制度作为党的领导制度，必须在领导班子议事决策中全面贯彻</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>①正确，2025年3月4日，《中国人民政治协商会议全国委员会常务委员会工作报告》中“一、2024年主要工作”部分指出：“（一）坚持用习近平新时代中国特色社会主义思想凝心铸魂，夯实团结奋斗的共同思想政治基础。我们把习近平新时代中国特色社会主义思想作为统揽政协工作的总纲······”<br>②正确，2025年1月20日，习近平总书记在人民大会堂同各民主党派中央、全国工商联负责人和无党派人士代表欢聚一堂，共迎佳节。习近平总书记指出：“一是提高政治站位，进一步画好同心圆。牢牢把握中国共产党领导这个中国新型政党制度的根本特征，深入学习新时代中国特色社会主义思想，多做强信心、聚民心、暖人心、筑同心的工作，切实把各方面积极因素转化为发展成效。”<br>③错误，2021年8月27日至28日，中央民族工作会议在北京召开，习近平总书记出席会议并发表重要讲话强调：“做好新时代党的民族工作，要把铸牢中华民族共同体意识作为党的民族工作的主线。铸牢中华民族共同体意识，就是要引导各族人民牢固树立休戚与共、荣辱与共、生死与共、命运与共的共同体理念。”故“不断巩固团结奋斗的共同思想政治基础”说法错误，应为“把铸牢中华民族共同体意识”。<br>④正确，“三重一大”最早源于1996年第十四届中央纪委第六次全会公报，对党员领导干部在政治纪律方面提出的四条要求的第二条纪律要求。具体表述如下：认真贯彻民主集中制原则，凡属重大决策、重要干部任免、重要项目安排和大额度资金的使用，必须经集体讨论作出决定。“三重一大”决策制度是民主集中制的重要体现，而民主集中制是党的根本组织原则和领导制度，故“三重一大”决策制度是党的领导制度，必须在领导班子议事决策中全面贯彻。<br>故①②④表述正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":12,"pid":"pc6b28bdffd"},{"qid":"16069804","no":14,"type":"新思想","module":"政治理论","stem":"<p>关于政治和法治的关系，下列说法错误的是（    ）。</p>","options":[{"k":"A","t":"法治相对于政治，居于主导地位"},{"k":"B","t":"法治当中有政治，没有脱离政治的法治"},{"k":"C","t":"法治工作是政治性很强的业务工作，也是业务性很强的政治工作"},{"k":"D","t":"全面推进依法治国这件大事能不能办好，最关键的是方向是不是正确、政治保证是不是坚强有力"}],"answer":"A","multi":false,"explanation":"<p>本题考查新思想。<br>A项错误，2024年7月2日，大兴普法文章《学思想·兴法治丨习近平法治思想学习问答（第45期）》指出：“政治是法治的前提和基础。经济基础最直接地作用于政治，又通过政治作用于其他上层建筑，包括法律、法治。政治相对于法治，居于主导地位，政治的发展变化一定会促使法治发生调整和变化。”故“法治相对于政治，居于主导地位”表述有误，应为“政治相对于法治，居于主导地位”。<br>B项正确，2015年10月19日，《人民日报》文章《法治与政治辩证统一》指出：“理论和现实都表明，法治当中有政治，没有脱离政治的法治，法治与政治是辩证统一的。”<br>C项正确，《习近平法治思想学习纲要》在“十、坚持建设德才兼备的高素质法治工作队伍——关于全面依法治国的基础性保障”中“1.建设一支德才兼备的高素质法治工作队伍至关重要”部分指出：“（104）当前，我国法治工作队伍总体上是好的······习近平总书记指出：‘法治工作是政治性很强的业务工作，也是业务性很强的政治工作。’”<br>D项正确，2014年10月28日，习近平总书记发表的文章《关于&lt;中共中央关于全面推进依法治国若干重大问题的决定&gt;的说明》在“三、关于需要说明的几个问题”部分指出：“第一，党的领导和依法治国的关系。党和法治的关系是法治建设的核心问题。全面推进依法治国这件大事能不能办好，最关键的是方向是不是正确、政治保证是不是坚强有力，具体讲就是要坚持党的领导，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论。”<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":13,"pid":"pc6b28bdffd"},{"qid":"16069777","no":15,"type":"新思想","module":"政治理论","stem":"<p>总体国家安全观是建设更高水平平安中国的重要遵循，必须坚定不移贯彻。关于贯彻总体国家安全观，下列举措不恰当的是：</p>","options":[{"k":"A","t":"进一步健全国家安全体系"},{"k":"B","t":"着力完善国家安全力量布局"},{"k":"C","t":"推动公共安全治理模式向着重事后整顿转型"},{"k":"D","t":"全面加强国家安全教育，筑牢国家安全人民防线"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2022年10月16日，习近平总书记在中国共产党第二十次全国代表大会上作了题为《高举中国特色社会主义伟大旗帜 为全面建设社会主义现代化国家而团结奋斗》的报告（以下简称二十大报告）。<br>A、B两项正确，二十大报告中的“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（一）健全国家安全体系······完善国家安全力量布局，构建全域联动、立体高效的国家安全防护体系。”<br>C项错误，二十大报告中的“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（三）提高公共安全治理水平。坚持安全第一、预防为主，建立大安全大应急框架，完善公共安全体系，推动公共安全治理模式向事前预防转型······”故“向着重事后整顿转型”表述错误，应为“向事前预防转型”。<br>D项正确，二十大报告中的“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（二）增强维护国家安全能力······全面加强国家安全教育，提高各级领导干部统筹发展和安全能力，增强全民国家安全意识和素养，筑牢国家安全人民防线。”<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":14,"pid":"pc6b28bdffd"},{"qid":"16069875","no":16,"type":"新思想","module":"政治理论","stem":"<p>建设美丽中国是全面建设社会主义现代化国家的重要目标。关于在推进中国式现代化过程中建设美丽中国，下列说法正确的是：</p>","options":[{"k":"A","t":"全面推进以国家公园为主体的自然保护地体系建设"},{"k":"B","t":"健全绿色低碳发展机制，推动碳排放双控向能耗双控全面转型"},{"k":"C","t":"健全横向生态保护补偿机制，突出重要流域上游生态环境的治理责任"},{"k":"D","t":"坚持生态环境管理全国一盘棋，强化全国范围内一致性的环境管理制度"}],"answer":"A","multi":false,"explanation":"<p>本题考查新思想。<br>A项正确，《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》在“十二、加快经济社会发展全面绿色转型，建设美丽中国”部分指出：“严守生态保护红线，全面推进以国家公园为主体的自然保护地体系建设，有序设立新的国家公园。”<br>B项错误，党的二十大报告在“十、推动绿色发展，促进人与自然和谐共生”部分指出：“立足我国能源资源禀赋，坚持先立后破，有计划分步骤实施碳达峰行动。完善能源消耗总量和强度调控，重点控制化石能源消费，逐步转向碳排放总量和强度‘双控’制度。”故“推动碳排放双控向能耗双控全面转型”说法错误，应为“推动能耗双控向碳排放双控全面转型”。<br>C项错误，党的二十届三中全会通过的《中共中央关于进一步全面深化改革 推进中国式现代化的决定》在“十二、深化生态文明体制改革”部分指出：“（48）健全生态环境治理体系。推进生态环境治理责任体系、监管体系、市场体系、法律法规政策体系建设······推动重要流域构建上下游贯通一体的生态环境治理体系······推进生态综合补偿，健全横向生态保护补偿机制，统筹推进生态环境损害赔偿。”故“突出重要流域上游生态环境的治理责任”说法错误，应为“推动重要流域构建上下游贯通一体的生态环境治理体系”。<br>D项错误，《中共中央办公厅 国务院办公厅关于加强生态环境分区管控的意见》指出：“生态环境分区管控是以保障生态功能和改善环境质量为目标，实施分区域差异化精准管控的环境管理制度，是提升生态环境治理现代化水平的重要举措。”故“强化全国范围内一致性的环境管理制度”表述错误，应为“实施分区域差异化精准管控的环境管理制度”。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":15,"pid":"pc6b28bdffd"},{"qid":"16069986","no":17,"type":"时事政治","module":"政治理论","stem":"<p>2025年12月，中央经济工作会议在北京举行，部署了2026年经济工作。下列与之相关说法正确的是（    ）。</p>","options":[{"k":"A","t":"增强中央转移支付力度，帮助地方政府积极有序化解债务风险"},{"k":"B","t":"加强财政科学管理，逐步降低财政赤字、债务总规模和支出总量"},{"k":"C","t":"继续实施适度宽松的货币政策，把物价合理回升作为货币政策重要考量"},{"k":"D","t":"持续深化资本市场投融资综合改革，扩大中小金融机构增量，优化存量"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2025年12月10日至11日，中央经济工作会议在北京举行。中共中央总书记、国家主席、中央军委主席习近平出席会议并发表重要讲话。<br>A项错误，会议指出：“坚持守牢底线，积极稳妥化解重点领域风险。着力稳定房地产市场，因城施策控增量、去库存、优供给，鼓励收购存量商品房重点用于保障性住房等。深化住房公积金制度改革，有序推动‘好房子’建设。加快构建房地产发展新模式。积极有序化解地方政府债务风险，督促各地主动化债，不得违规新增隐性债务。优化债务重组和置换办法，多措并举化解地方政府融资平台经营性债务风险。”故“增强中央转移支付力度”表述错误，化解地方债务风险的核心责任一般在地方政府。<br>B项错误，C项正确，会议指出：“明年经济工作在政策取向上，要坚持稳中求进、提质增效，发挥存量政策和增量政策集成效应，加大逆周期和跨周期调节力度，提升宏观经济治理效能。要继续实施更加积极的财政政策。保持必要的财政赤字、债务总规模和支出总量，加强财政科学管理，优化财政支出结构，规范税收优惠、财政补贴政策······要继续实施适度宽松的货币政策。把促进经济稳定增长、物价合理回升作为货币政策的重要考量，灵活高效运用降准降息等多种政策工具，保持流动性充裕，畅通货币政策传导机制······”故B项中“逐步降低财政赤字、债务总规模和支出总量”表述错误，应为“保持必要的财政赤字、债务总规模和支出总量”。<br>D项错误，会议指出：“坚持改革攻坚，增强高质量发展动力活力。制定全国统一大市场建设条例，深入整治‘内卷式’竞争。制定和实施进一步深化国资国企改革方案，完善民营经济促进法配套法规政策。加紧清理拖欠企业账款。推动平台企业和平台内经营者、劳动者共赢发展。拓展要素市场化改革试点。健全地方税体系。深入推进中小金融机构减量提质，持续深化资本市场投融资综合改革。”故“扩大中小金融机构增量，优化存量”表述错误，应为“深入推进中小金融机构减量提质”。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":16,"pid":"pc6b28bdffd"},{"qid":"16070045","no":18,"type":"时事政治","module":"政治理论","stem":"<p>2025年底，中共中央政治局召开民主生活会强调，锲而不舍落实中央八项规定精神，以优良作风凝心聚力真抓实干。关于作风问题，下列说法不准确的是（    ）。</p>","options":[{"k":"A","t":"作风问题核心是党同人民群众的关系问题"},{"k":"B","t":"党强大的人格力量集中体现为党的优良作风"},{"k":"C","t":"透过党性看作风，在解决党性问题的基础上解决好作风问题"},{"k":"D","t":"抓作风建设，重点突出坚定理想信念、践行根本宗旨、加强道德修养"}],"answer":"C","multi":false,"explanation":"<p>本题考查新思想。<br>2025年3月，中共中央党史和文献研究院编辑的《习近平关于加强党的作风建设论述摘编》出版发行，以下简称《论述摘编》。<br>A项正确，《论述摘编》中“三、作风问题核心是党同人民群众的关系问题”部分指出：“作风问题核心是党同人民群众的关系问题。马克思主义政党执政后特别是长期执政后的最大危险是脱离群众。”<br>B项正确，《论述摘编》中“一、党的作风关系人心向背，决定党和国家事业成败”部分指出：“我们党作为马克思主义执政党，不但要有强大的真理力量，而且要有强大的人格力量。真理力量集中体现为我们党的正确理论，人格力量集中体现为我们党的优良作风。”<br>C项错误，《论述摘编》中“二、作风问题本质上是党性问题”部分指出：“我们改进作风，不能简单就事论事，以为把眼前存在的作风问题从面上解决了就万事大吉了，而是要举一反三，透过作风看党性，在解决作风问题的基础上解决好党性问题。”故“透过党性看作风”说法错误，应为“透过作风看党性”。<br>D项正确，《论述摘编》中“二、作风问题本质上是党性问题”部分指出：“作风问题本质上是党性问题。抓作风建设，就要返璞归真、固本培元，重点突出坚定理想信念、践行根本宗旨、加强道德修养。”<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":17,"pid":"pc6b28bdffd"},{"qid":"16069987","no":19,"type":"新思想","module":"政治理论","stem":"<p>《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出，要如期实现建军一百年奋斗目标，高质量推进国防和军队现代化。下列举措不属于高质量推进国防和军队现代化的是（    ）。</p>","options":[{"k":"A","t":"壮大战略威慑力量，维护全球战略平衡和稳定"},{"k":"B","t":"全面落实勤俭建军方针，走高效益、低成本、可持续发展路子"},{"k":"C","t":"建设先进国防科技工业体系，优化国防科技工业布局，推进军民标准通用化"},{"k":"D","t":"完善涉外国家安全机制，构建海外安全保障体系，加强反制裁、反干预、反“长臂管辖”斗争"}],"answer":"D","multi":false,"explanation":"<p>本题考查新思想。<br>2025年10月23日，中国共产党第二十届中央委员会第四次全体会议通过《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》（以下简称《建议》）。<br>A项正确，《建议》在“十四、如期实现建军一百年奋斗目标，高质量推进国防和军队现代化”部分指出：“（53）加快先进战斗力建设。壮大战略威慑力量，维护全球战略平衡和稳定。推进新域新质作战力量规模化、实战化、体系化发展，加快无人智能作战力量及反制能力建设，加强传统作战力量升级改造。”<br>B项正确，《建议》在“十四、如期实现建军一百年奋斗目标，高质量推进国防和军队现代化”部分指出：“（54）推进军事治理现代化······加强重大决策咨询评估和重大项目监管，推进军费预算管理改革，改进军事采购制度，完善军队建设统计评估体系，全面落实勤俭建军方针，走高效益、低成本、可持续发展路子。持续深化政治整训，弘扬优良传统，加强重点行业和领域整肃治理。”<br>C项正确，《建议》在“十四、如期实现建军一百年奋斗目标，高质量推进国防和军队现代化”部分指出：“（55）巩固提高一体化国家战略体系和能力。深化跨军地改革，构建各司其职、紧密协作、规范有序的跨军地工作格局。加快新兴领域战略能力建设，推动新质生产力同新质战斗力高效融合、双向拉动。建设先进国防科技工业体系，优化国防科技工业布局，推进军民标准通用化。”<br>D项错误，《建议》在“十三、推进国家安全体系和能力现代化，建设更高水平平安中国”部分指出：“（49）健全国家安全体系······落实国家安全责任制，促进全链条全要素协同联动，形成体系合力。完善涉外国家安全机制，构建海外安全保障体系，加强反制裁、反干预、反‘长臂管辖’斗争，深化国际执法安全合作，推动完善全球安全治理。强化国家安全教育，筑牢人民防线。”故该项不属于“高质量推进国防和军队现代化”举措。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":18,"pid":"pc6b28bdffd"},{"qid":"16069783","no":20,"type":"新思想","module":"政治理论","stem":"<p>网络生态治理是网络强国建设的重要任务，事关国家发展和安全，事关人民群众切身利益。关于健全网络生态治理长效机制，下列说法错误的是：</p>","options":[{"k":"A","t":"坚持把普惠作为第一动力、把安全作为底线要求、把创新作为价值追求，高质量推进网络生态治理"},{"k":"B","t":"完善网上思想道德教育分众化、精准化实施机制，培育自尊自信、理性平和、积极向上的网络社会心态"},{"k":"C","t":"坚持以正面声音、主流价值、时代新风塑造网络空间，使互联网成为思想引领、道德培育、文化传承的重要阵地"},{"k":"D","t":"加强国际传播网络平台和能力建设，利用互联网传播中国声音、讲好中国故事，生动展现可信、可爱、可敬的中国形象"}],"answer":"A","multi":false,"explanation":"<p>本题考查新思想。<br>A项错误，2024年11月20日，习近平总书记向2024年世界互联网大会乌镇峰会开幕视频致贺时指出：“我们应当把握数字化、网络化、智能化发展大势，把创新作为第一动力、把安全作为底线要求、把普惠作为价值追求，加快推动网络空间创新发展、安全发展、普惠发展，携手迈进更加美好的‘数字未来’。”故“把普惠作为第一动力”“把创新作为价值追求”表述错误，应为“把创新作为第一动力”“把普惠作为价值追求”。<br>B项正确，2025年11月28日下午，中共中央政治局就加强网络生态治理进行第二十三次集体学习，习近平总书记主持学习并发表重要讲话（以下简称讲话）指出：“网络生态治理是一项系统工程，要充分调动各方力量，综合运用教育、行政、法治等多种手段。要完善网上思想道德教育分众化、精准化实施机制，培育自尊自信、理性平和、积极向上的网络社会心态。”<br>C项正确，讲话指出：“源清则流清，要坚持以正面声音、主流价值、时代新风塑造网络空间，使互联网成为思想引领、道德培育、文化传承的重要阵地。要深化党的创新理论网上宣传，大力弘扬社会主义核心价值观，推出更多有内涵、有温度、有影响的网络作品。”<br>D项正确，讲话指出：“要积极参与国际规则制定，携手各国打击网络违法犯罪，推动构建网络空间命运共同体。要加强国际传播网络平台和能力建设，利用互联网传播中国声音、讲好中国故事，生动展现可信、可爱、可敬的中国形象。”<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":19,"pid":"pc6b28bdffd"},{"qid":"16070011","no":1,"type":"法律常识","module":"常识判断","stem":"<p>根据《中华人民共和国村民委员会组织法》，下列说法错误的是（    ）。</p>","options":[{"k":"A","t":"需由村民会议或者村民代表会议决定的重要事项，应当先经村党组织研究讨论"},{"k":"B","t":"村民委员会具有基层群众性自治组织法人资格，村民委员会主任为法定代表人"},{"k":"C","t":"村民委员会成员实行近亲属回避，根据具体情况吸纳妇女成员"},{"k":"D","t":"村民委员会应当设立村务公开栏，公布的期限不得少于十五日"}],"answer":"C","multi":false,"explanation":"<p>本题考查法律常识。<br>A项正确，根据《中华人民共和国村民委员会组织法》第二十八第三款规定：“需由村民会议或者村民代表会议决定的重要事项，应当先经村党组织研究讨论。”<br>B项正确，根据《中华人民共和国村民委员会组织法》第十三条规定：“村民委员会具有基层群众性自治组织法人资格，村民委员会主任为法定代表人。村民委员会可以从事为履行职能所需要的民事活动，但是不得提供担保。”<br>C项错误，根据《中华人民共和国村民委员会组织法》第八条第二款规定：“村民委员会成员中，应当有妇女成员。村民委员会成员实行近亲属回避。”因此，村民委员会成员中应当有妇女成员，并非根据具体情况吸纳妇女成员。<br>D项正确，根据《中华人民共和国村民委员会组织法》第三十五条第四款规定：“村民委员会应当设立村务公开栏，可以采用现代信息技术进行村务公开。公布的期限不得少于十五日。村民委员会应当保证公布事项的真实性，并接受村民的查询。”<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":20,"pid":"pc6b28bdffd"},{"qid":"16069860","no":2,"type":"法律常识","module":"常识判断","stem":"<p>诉讼时效是指权利人能行使权利而不行使，经过法律规定的时间，便丧失了请求法院强制义务人履行义务的权利的时效制度。下列请求权中，适用诉讼时效的是：</p>","options":[{"k":"A","t":"公司请求未履行出资义务的股东缴纳其认缴的注册资本"},{"k":"B","t":"普通动产的所有权人要求无权占有人返还原物的请求权"},{"k":"C","t":"小区业主委员会请求业主补交欠交的住宅专项维修资金"},{"k":"D","t":"名誉权受到侵害，受害人请求行为人停止侵害、恢复名誉"}],"answer":"B","multi":false,"explanation":"<p>本题考查法律常识。<br>A项错误，根据《最高人民法院关于适用&lt;中华人民共和国公司法&gt;若干问题的规定（三）》第十九条第一款规定：“公司股东未履行或者未全面履行出资义务或者抽逃出资，公司或者其他股东请求其向公司全面履行出资义务或者返还出资，被告股东以诉讼时效为由进行抗辩的，人民法院不予支持。”因此，公司请求未履行出资义务的股东缴纳其认缴的注册资本的请求权不适用诉讼时效。<br>B项正确，根据《中华人民共和国民法典》第一百九十六条第二项规定：“下列请求权不适用诉讼时效的规定：（二）不动产物权和登记的动产物权的权利人请求返还财产；”因此，只有登记的动产物权的权利人请求返还财产不适用诉讼时效，普通动产的所有权人要求无权占有人返还原物的请求权适用诉讼时效。<br>C项错误，根据《中华人民共和国民法典》第二百八十一条第一款规定：“建筑物及其附属设施的维修资金，属于业主共有。经业主共同决定，可以用于电梯、屋顶、外墙、无障碍设施等共有部分的维修、更新和改造。建筑物及其附属设施的维修资金的筹集、使用情况应当定期公布。”因此，维修资金属于业主共有财产，交纳维修资金是业主基于业主身份必须履行的法定义务，目的是维持“建筑物区分所有权”这一共同体的存续基础，若允许以诉讼时效抗辩，将导致“未交者长期受益、已交者受损”，违背了民法典的公平原则。因此，小区业主委员会请求业主补交欠交的住宅专项维修资金的请求权，因维修资金涉及公共利益和共有义务，不适用诉讼时效。<br>D项错误，根据《中华人民共和国民法典》第九百九十五条规定：“人格权受到侵害的，受害人有权依照本法和其他法律的规定请求行为人承担民事责任。受害人的停止侵害、排除妨碍、消除危险、消除影响、恢复名誉、赔礼道歉请求权，不适用诉讼时效的规定。”<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":21,"pid":"pc6b28bdffd"},{"qid":"16069803","no":3,"type":"法律常识","module":"常识判断","stem":"<p>甲因琐事纠纷将乙打伤，经当地人民调解委员会调解，双方达成调解协议，约定甲向乙支付医疗费等共计5000元。事后甲拒绝履行该协议。对此，下列相关说法正确的是（    ）。</p>","options":[{"k":"A","t":"乙可依据该调解协议直接向人民法院申请强制执行"},{"k":"B","t":"乙只能就原人身损害事实另行提起侵权损害赔偿诉讼"},{"k":"C","t":"乙有权依据该调解协议向人民法院提起诉讼，请求判令甲履行协议"},{"k":"D","t":"甲有权主张该调解协议内容显失公平，向人民法院申请撤销该协议"}],"answer":"C","multi":false,"explanation":"<p>本题考查法律常识。<br>A项错误，根据《中华人民共和国人民调解法》第三十三条第一、二款规定：“经人民调解委员会调解达成调解协议后，双方当事人认为有必要的，可以自调解协议生效之日起三十日内共同向人民法院申请司法确认，人民法院应当及时对调解协议进行审查，依法确认调解协议的效力。人民法院依法确认调解协议有效，一方当事人拒绝履行或者未全部履行的，对方当事人可以向人民法院申请强制执行。”题中，该调解协议未经过司法确认，不具有强制执行力，乙不能直接申请强制执行。<br>B项错误，C项正确，根据《中华人民共和国人民调解法》第三十二条规定：“经人民调解委员会调解达成调解协议后，当事人之间就调解协议的履行或者调解协议的内容发生争议的，一方当事人可以向人民法院提起诉讼。”题中，乙既可以就原人身损害提起侵权损害赔偿诉讼，也可针对调解协议提起诉讼，请求判令甲履行协议。<br>D项错误，根据《中华人民共和国民法典》第一百五十一条规定：“一方利用对方处于危困状态、缺乏判断能力等情形，致使民事法律行为成立时显失公平的，受损害方有权请求人民法院或者仲裁机构予以撤销。”题中，案件涉及甲事后拒绝履行调解协议，未表明存在显失公平的情形，因此，甲无权主张撤销该协议。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":22,"pid":"pc6b28bdffd"},{"qid":"16069916","no":4,"type":"地理国情","module":"常识判断","stem":"<p>在春秋战国时期，今天的河南省分别被燕国和赵国占据，因此也被称为“燕赵之地”。由于受武侠文化影响颇深，再加上地处军事重地，这一地区自古就英雄频出，以“燕赵多慷慨悲歌之士”著称，其中就包括知名典故“将相和”的主角廉颇和蔺相如、三国蜀汉政权建立者刘备、唐朝名相魏征等。在文化领域，这一地区同样贡献了大量人才，如名列“元曲四大家”之首的关汉卿、世界上第一个将圆周率计算到小数点后七位的南北朝时期数学家祖冲之、制订出极为精确天文历法的唐代天文学家郭守敬、写有不朽地理名著的北魏地理学家郦道元，等等。<br>这段文字画横线部分表述错误的有几处？</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"B","multi":false,"explanation":"<p>本题考查人文常识。<br>①错误，燕国与赵国是春秋战国时期北方重要诸侯国，其核心统治区域主要位于今天的河北省、北京市、天津市以及山西省北部一带，因此这一地区历史上被称为“燕赵之地”。而今天的河南省在春秋战国时期主要隶属于晋国、郑国、宋国、魏国、韩国等国，与燕、赵两国并无直接的隶属关系。因此“今天的河南省分别被燕国和赵国占据”表述有误。<br>②正确，“将相和”是战国时期赵国著名的历史典故，主要人物是廉颇与蔺相如。廉颇是赵国战功卓著的武将，蔺相如凭借智慧与胆识在外交上为赵国立下大功，被封为上卿，位居廉颇之上。廉颇起初心生不满，后来得知蔺相如以国家大局为重，主动负荆请罪，二人最终成为刎颈之交，共同辅佐赵国。<br>③正确，关汉卿是元代最杰出的杂剧作家，籍贯有解州（今山西省运城）、大都（今北京市）和祁州（今河北省安国市）等说，终其一生，长期活动于大都（今北京市）一带。关汉卿与白朴、马致远、郑光祖并称为“元曲四大家”，居四大家之首。他一生创作杂剧数量众多，题材广泛，风格泼辣深刻，代表作《窦娥冤》更是中国古代戏曲史上的巅峰之作，对后世戏曲发展影响深远。因此“名列‘元曲四大家’之首的关汉卿”属于燕赵之地的文化人才，表述正确。（该选项存在争议，但有争议的三种说法里，两个都属于燕赵之地的这个范围，故我们认为该选项正确。）<br>④错误，郭守敬，邢州邢台县（今河北省邢台市信都区）人，是元代著名的天文学家、数学家、水利工程专家。他在天文观测、历法编制、仪器制造等方面都取得了极高成就，主持编制的《授时历》是中国古代最精密的历法之一，其精度在当时世界上处于领先水平。因此郭守敬属于燕赵之地的文化人才，但他是元代的天文学家而非唐代，表述有误。<br>⑤正确，郦道元，北魏范阳涿县人（今河北省涿州市），是北魏时期著名地理学家，他以《水经》为底本，广泛搜集资料并结合实地考察，撰写了《水经注》这一古代地理学名著。该书详细记载了全国一千多条河流的源流、流经区域、地理风貌、历史典故与人文传说，内容丰富、考证严谨，既是地理学巨著，也具有极高的文学价值。因此“北魏地理学家郦道元”属于燕赵之地的文化人才，表述正确。<br>综上，①④表述错误，共2处。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":23,"pid":"pc6b28bdffd"},{"qid":"16069809","no":5,"type":"人文常识","module":"常识判断","stem":"<p>下列关于鸦片战争和第二次鸦片战争说法错误的是：</p>","options":[{"k":"A","t":"鸦片战争是英、法两国联合发动的侵略战争"},{"k":"B","t":"电影《火烧圆明园》以第二次鸦片战争为背景"},{"k":"C","t":"第二次鸦片战争迫使清政府签订了《天津条约》"},{"k":"D","t":"“三元里前声若雷，千众万众同时来”与鸦片战争有关"}],"answer":"A","multi":false,"explanation":"<p>本题考查人文常识。<br>A项错误，1840年，英国为扭转对华贸易逆差，向中国走私鸦片，林则徐虎门销烟成为战争借口，英国发动鸦片战争；1856-1860年，英法等国为进一步打开中国市场、扩大侵略权益，以“修约”被拒为借口，发动第二次鸦片战争。故英、法两国联合发动鸦片战争表述错误，鸦片战争（第一次鸦片战争）是英国单独发动的。<br>B项正确，火烧圆明园发生在第二次鸦片战争期间，1860年，英法联军攻占北京，抢劫并焚毁圆明园。电影《火烧圆明园》正是以第二次鸦片战争为背景。<br>C项正确，第二次鸦片战争中，清政府被迫与英、法、俄、美四国签订《天津条约》；与英国、法国、俄国签订《北京条约》等。<br>D项正确，选项诗句出自清代爱国诗人张维屏的七言古诗《三元里》，写于1841年，歌颂三元里抗英斗争。诗句意思为：“三元里村前，民众呐喊声如雷鸣，成千上万的人从各处一同赶来，奋起反抗英国侵略者。”第一次鸦片战争期间，英军在广州三元里一带骚扰作恶，激起民众反抗，三元里人民自发组织起来围歼英军，是近代中国第一次大规模民间反侵略斗争。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":24,"pid":"pc6b28bdffd"},{"qid":"16069779","no":6,"type":"地理国情","module":"常识判断","stem":"<p>水是生命之源、生态之基、生产之要，更是文明之本，在中华民族的文明发展史上，水始终占据着特殊的地位。下列与水有关的说法错误的是：</p>","options":[{"k":"A","t":"《尚书·禹贡》是与河流密切相关的著作"},{"k":"B","t":"“兵无常势，水无常形”是孙武论兵的名言"},{"k":"C","t":"“坎坎伐檀兮，置之河之干兮”出自《诗经》"},{"k":"D","t":"最早提出“水能载舟、亦能覆舟”的是唐太宗"}],"answer":"D","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确，《尚书·禹贡》是中国古代地理学的重要文献，被认为是第一篇具有系统性地理观念的著作，《禹贡》以自然地理实体（山脉、河流等）为标志，将全国划分为9个区（即九州），并对每区（州）的疆域、山脉、河流、植被、土壤、物产、贡赋、少数民族、交通等自然和人文地理现象作了简要描述。此外，《禹贡》还分述了导山、导水、水功和以京都为中心的五服制度，其内容与河流密切相关。<br>B项正确，“兵无常势，水无常形”出自《孙子·虚实篇》，意思是用兵作战要根据敌情的变化来采取灵活机动的战略战术，不能墨守某种作战方法。<br>C项正确，“坎坎伐檀兮，置之河之干兮”出自《诗经·伐檀》，意思是砍伐檀树声坎坎啊，把砍到的檀树一棵棵堆放在河边。<br>D项错误，“水能载舟、亦能覆舟”最早出自于战国时期荀子及其弟子所著的《荀子·王制》，内容是：“《传》曰：‘君者，舟也；庶人者，水也。水则载舟，水则覆舟’。”后世据此典故引申出成语“水能载舟，亦能覆舟”。贞观六年，唐太宗与群臣论治国之道，提出：“天子者，有道则人推而为主，无道则人弃而不用，诚可畏也。”魏征接着说道：“臣又闻古语云：君，舟也；人，水也。水能载舟，亦能覆舟。陛下以为可畏，诚如圣旨。”<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":25,"pid":"pc6b28bdffd"},{"qid":"16069758","no":7,"type":"人文常识","module":"常识判断","stem":"<p>下列论文的主标题与副标题匹配不恰当的是：</p>","options":[{"k":"A","t":"我欲乘风归去——苏轼豪放词的发生"},{"k":"B","t":"春蚕到死丝方尽——李商隐无题诗浅探"},{"k":"C","t":"常记溪亭日暮——白居易西湖美景诗赏析"},{"k":"D","t":"美人如花隔云端——李白女性诗用典研究"}],"answer":"C","multi":false,"explanation":"<p>A项正确，“我欲乘风归去”出自北宋苏轼的《水调歌头·明月几时有》。词句意思是我想要乘着清风回到天上的宫阙。词句意境豪迈，体现了苏轼的豪放词风，与副标题匹配恰当。<br>B项正确，“春蚕到死丝方尽”出自唐代李商隐的《无题·相见时难别亦难》。诗句意思是春蚕直到死去才会把丝吐尽，以春蚕吐丝比喻深情执着。这首诗是其无题诗的代表作，与副标题匹配恰当。<br>C项错误，“常记溪亭日暮”出自宋代李清照的《如梦令·常记溪亭日暮》，并非白居易的作品。词句意思是常常想起在溪边亭中游玩，直到夕阳西下的情景。词句描写李清照早年游玩之景，与“白居易西湖美景诗赏析”匹配不当。<br>D项正确，“美人如花隔云端”出自唐代李白的《长相思·其一》。诗句意思是所思美人像鲜花一般美好，却远在云天之外。诗句塑造动人女性形象，与副标题匹配恰当。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":26,"pid":"pc6b28bdffd"},{"qid":"16069757","no":8,"type":"科技常识","module":"常识判断","stem":"<p>下列诗句与其所描述的花卉对应正确的是：</p>","options":[{"k":"A","t":"暗淡轻黄体性柔，情疏迹远只香留——牡丹"},{"k":"B","t":"直须看尽洛城花，始共春风容易别——桂花"},{"k":"C","t":"飒飒西风满院栽，蕊寒香冷蝶难来——菊花"},{"k":"D","t":"东风袅袅泛崇光，香雾空蒙月转廊——樱花"}],"answer":"C","multi":false,"explanation":"<p>本题考查人文常识。<br>A项错误，“暗淡轻黄体性柔，情疏迹远只香留”出自李清照的《鹧鸪天·桂花》，意思是花色浅淡、体态轻柔，不刻意亲近人，只把香气长久留下。故该项描述的是桂花，而非牡丹。<br>B项错误，“直须看尽洛城花，始共春风容易别”出自欧阳修的《玉楼春》，意思是一定要把洛阳城的牡丹花看遍，才好和春风告别。洛阳牡丹甲天下，“洛城花”代指牡丹，而非桂花。<br>C项正确，“飒飒西风满院栽，蕊寒香冷蝶难来”出自黄巢的《题菊花》，意思是秋风萧瑟里满院栽种菊花，花蕊寒冷、香气清冷，蝴蝶都难飞来。“蕊寒香冷”指的是菊花耐寒的特点。<br>D项错误，“东风袅袅泛崇光，香雾空蒙月转廊”出自苏轼的《海棠》，意思是春风吹动了淡淡的云彩，露出了月亮，月光也是淡淡的，花朵的香气融在朦胧的雾里，月亮已移过了院中的回廊。全诗后两句“只恐夜深花睡去，故烧高烛照红妆”是写海棠的千古名句。故该项描述的是海棠，而非樱花。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":27,"pid":"pc6b28bdffd"},{"qid":"16069766","no":9,"type":"人文常识","module":"常识判断","stem":"<p>下列关于我国古代绘画说法错误的是：</p>","options":[{"k":"A","t":"“妙手丹青”中包含两种矿物染料"},{"k":"B","t":"《清明上河图》是纸本水墨画"},{"k":"C","t":"“胸有成竹”是苏轼对文同的评价"},{"k":"D","t":"“点染”是一种古代绘画技法"}],"answer":"B","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确，“妙手丹青”中的“丹青”确实指代两种矿物染料。“丹”指朱砂，是一种红色的矿物颜料；“青”指石青（如蓝铜矿）或曾青，是一种蓝色的矿物颜料。因此，该成语字面上包含了两种矿物染料，用来借代绘画艺术。<br>B项错误，《清明上河图》是由北宋画家张择端绘制的长卷，其绘制材质是“绢”（一种丝织品），而非纸张。同时，画作中运用了色彩渲染，属于“设色”作品，而非单纯的水墨画。因此《清明上河图》并非纸本水墨画，而是绢本设色风俗画。<br>C项正确，“胸有成竹”出自苏轼的《文与可画筼筜谷偃竹记》，是苏轼评价表兄文同（文与可）画竹时，心中先有完整意象，再下笔作画，因此是苏轼对文同的评价。<br>D项正确，“点染”是中国古代的一种绘画技法。根据记载，北齐颜之推在《颜氏家训·杂艺》中提到“武烈太子偏能写真，坐上宾客，随宜点染，即成数人”。在古代画论中，“点染无法”也被列为绘画十二忌之一，指设色时点染不得法，可见其作为一种技法的客观存在。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":28,"pid":"pc6b28bdffd"},{"qid":"16069759","no":10,"type":"人文常识","module":"常识判断","stem":"<p>下列诗句描述的现象与气象变化对应错误的是：</p>","options":[{"k":"A","t":"雨中百草秋烂死，阶下决明颜色鲜——软雹"},{"k":"B","t":"白雪却嫌春色晚，故穿庭树作飞花——倒春寒"},{"k":"C","t":"风驱急雨洒高城，云压轻雷殷地声——雷阵雨"},{"k":"D","t":"北风卷地白草折，胡天八月即飞雪——冷锋过境"}],"answer":"A","multi":false,"explanation":"<p>本题考查地理国情。<br>A项错误，“雨中百草秋烂死，阶下决明颜色鲜”出自唐代杜甫的《秋雨叹三首·其一》，意思是秋雨连绵百草烂死，台阶下的决明却颜色正鲜。诗句中秋雨现象主要由冷锋活动引起。当北方冷空气南下时，与较暖湿的空气相遇，冷空气迫使暖湿空气抬升，形成云系和降水。故诗句描写的气象变化是连绵秋雨，不是软雹。<br>B项正确，“白雪却嫌春色晚，故穿庭树作飞花”出自唐代韩愈的《春雪》，意思是白雪也嫌春色来得太晚了，所以有意化作花儿在庭院树间穿飞。诗句中描写的这种春季气温偏低、出现降雪或霜冻的天气，是典型的倒春寒。<br>C项正确，“风驱急雨洒高城，云压轻雷殷地声”出自明代刘基的《五月十九日大雨》，意思是疾风驱使着骤雨瞬间洒落高城，乌云密布，雷声滚滚，大地仿佛都在震动。故诗句描写的是夏季典型的雷阵雨天气。<br>D项正确，“北风卷地白草折，胡天八月即飞雪”出自唐代岑参的《白雪歌送武判官归京》，意思是北风席卷大地把白草吹折，胡地天气八月就纷扬落雪。北风带来寒冷空气，使气温骤降并出现降雪，这是冷锋过境的典型表现。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":29,"pid":"pc6b28bdffd"},{"qid":"16069760","no":11,"type":"地理国情","module":"常识判断","stem":"<p>下列关于亚洲的地理知识说法错误的是（    ）。</p>","options":[{"k":"A","t":"东亚地区没有内陆国家"},{"k":"B","t":"东南亚跨南、北两个半球"},{"k":"C","t":"中亚地区以大陆性气候为主"},{"k":"D","t":"古巴比伦文明产生在西亚地区"}],"answer":"A","multi":false,"explanation":"<p>本题考查地理国情。<br>A项错误，东亚包括中国、日本、韩国、朝鲜、蒙古五个国家，其中蒙古是无出海口、完全被陆地包围的内陆国家（被中国与俄罗斯包围），同时蒙古国也是世界上第二大的内陆国。<br>B项正确，东南亚由中南半岛和马来群岛两大部分组成，赤道横穿马来群岛中部，因此东南亚地跨南、北两个半球，该区域同时还地跨太平洋与印度洋两大核心大洋，是亚洲海上交通的关键枢纽。<br>C项正确，中亚深居亚欧大陆内部，远离海洋，海洋湿润气流难以抵达，区域内以温带大陆性气候为主，核心气候特征为干旱少雨、气温年较差与日较差大，也造就了区域内以内流河、内流湖为主的水文特征。<br>D项正确，古巴比伦文明是世界四大古文明之一，发源于西亚的两河流域（幼发拉底河、底格里斯河）之间的冲积平原（美索不达米亚），该区域核心在今伊拉克境内，属于西亚核心地带。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":30,"pid":"pc6b28bdffd"},{"qid":"16069836","no":12,"type":"地理国情","module":"常识判断","stem":"<p>下列李白所作诗句描述的名山与现在我国的地理分区对应正确的是（    ）。</p>","options":[{"k":"A","t":"西上太白峰，夕阳穷登攀——西北地区"},{"k":"B","t":"我有万古宅，嵩阳玉女峰——华北地区"},{"k":"C","t":"日照香炉生紫烟，遥看瀑布挂前川——西南地区"},{"k":"D","t":"衡山苍苍入紫冥，下看南极老人星——华南地区"}],"answer":"A","multi":false,"explanation":"<p>本题考查地理国情。<br>A项正确，“西上太白峰，夕阳穷登攀”出自唐代李白的《登太白峰》，意思是向西攀登太白峰，在日落时分才登上峰巅。诗句中的“太白峰”即太白山，又称太乙山、太一山，是秦岭山脉的主峰，位于陕西省宝鸡市眉县、太白县、周至县交界处，按照通用行政地理分区标准，陕西省属于西北五省之一（陕、甘、宁、青、新）。<br>B项错误，“我有万古宅，嵩阳玉女峰”出自唐代李白的《送杨山人归嵩山》，意思是我有万古不坏的仙宅，那就是嵩山之阳的玉女峰。诗句中“嵩阳”指嵩山之南；“玉女峰”为嵩山支脉太皇山二十四峰之一，因峰北有石如女而得此名。嵩山主体位于河南省登封市境内，按照通用分区标准，河南省属于华中三省之一（豫、鄂、湘），而非华北地区（京、津、冀、晋、蒙）。<br>C项错误，“日照香炉生紫烟，遥看瀑布挂前川”出自唐代李白的《望庐山瀑布》，意思是太阳照耀香炉峰生出袅袅紫烟，远远望去瀑布像长河悬挂山前。诗句描述的主体是庐山，位于江西省九江市庐山市境内，按照通用分区标准，江西省属于华东七省一市之一（上海、江苏、浙江、安徽、福建、江西、山东与台湾）。<br>D项错误，“衡山苍苍入紫冥，下看南极老人星”出自唐代李白的《与诸公送陈郎将归衡阳》，意思是衡山在夜色的天空下愈发苍翠，从山上俯视着南方升起的老人星。诗句描述的主体是衡山，位于湖南省衡阳市南岳区境内，按照通用分区标准，湖南省属于华中三省之一（豫、鄂、湘）。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":31,"pid":"pc6b28bdffd"},{"qid":"16069761","no":13,"type":"人文常识","module":"常识判断","stem":"<p>下列与肥料有关的说法错误的是（    ）。</p>","options":[{"k":"A","t":"钾肥具有抗倒伏的功效"},{"k":"B","t":"尿素是一种常见的氮肥"},{"k":"C","t":"“化作春泥”体现了腐殖化作用"},{"k":"D","t":"复合肥料可为农作物提供有机质"}],"answer":"D","multi":false,"explanation":"<p>本题考查科技常识。</p><p>A项正确，钾肥能促进作物茎秆细胞壁木质素合成，主要作用是增强作物茎秆的机械强度和韧性，促进作物根系发达、茎秆健壮，从而显著提升作物的抗倒伏、抗病虫害等抗逆能力，因此钾肥具有抗倒伏的功效。</p><p>B项正确，尿素是人体蛋白质代谢的主要终产物，化学式为<img src=\"assets/img/gongshi/formula-0a18323a9d8654fc.png\" class=\"tex\">，含氮量为40%以上，是目前使用最广泛、含氮量最高的固体氮肥之一，适用于各类土壤和作物，肥效较高且相对温和。</p><p>C项正确，“化作春泥”描述的是植物残体、枯枝落叶等有机物质在土壤中经过微生物分解、转化，逐渐形成腐殖质的过程，这一过程体现了腐殖化作用，腐殖质能改善土壤结构、提升土壤肥力。</p><p>D项错误，复合肥料是指同时含有氮、磷、钾中两种或两种以上大量营养元素的化学肥料，其核心作用是为农作物提供氮、磷、钾等矿质养分，并不含有机质；有机质主要来源于农家肥、堆肥、绿肥、腐殖质等有机肥，因此复合肥料不能为农作物提供有机质。</p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":32,"pid":"pc6b28bdffd"},{"qid":"16069830","no":14,"type":"人文常识","module":"常识判断","stem":"<p>下列关于物态变化的说法，错误的是（    ）。</p>","options":[{"k":"A","t":"夏天往饮料中加冰是因其熔化吸热"},{"k":"B","t":"东北雾凇的形成是由于发生了凝华"},{"k":"C","t":"冬天凝结在车窗上的雾气是液态的"},{"k":"D","t":"沸腾和蒸发涉及的物态变化不一样"}],"answer":"D","multi":false,"explanation":"<p>本题考查科技常识。<br>A项正确，熔化是物质从固态变为液态的过程，根据物态变化规律，熔化过程需要吸收热量。冰块从周围环境（包括饮料）吸收热量，使饮料温度降低，符合熔化的物理规律。<br>B项正确，凝华是指物质从气态直接变成固态的过程。雾凇俗称树挂，是指过冷却雾滴直接冻结在物体迎风面上，或空气中的饱和水汽直接凝华而形成的乳白色不透明的冰晶物，属于凝华现象。<br>‌C项正确，冬天车窗上的“雾气”，是因为车内温暖潮湿的水蒸气遇到冰冷的车窗玻璃后，放热液化成雾状小水珠附着在玻璃上，这些呈雾状的小水珠是液态的。<br>D项错误，蒸发和沸腾是汽化的两种不同方式。蒸发是在液体表面发生的汽化过程，沸腾则是在液体内部和表面上同时发生的剧烈的汽化现象。二者都是物质由液态变为气态，本质都属于汽化这一物态变化，只是发生条件、剧烈程度不同。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":33,"pid":"pc6b28bdffd"},{"qid":"16069775","no":15,"type":"科技常识","module":"常识判断","stem":"<p>下列与常用电器有关的说法正确的有几项？<br>①LED灯通常会比卤素灯更加节能<br>②油烟机工作时电能转化成机械能<br>③空调的压缩机通常装在室外机中<br>④洗衣机运行过程中会产生向心力</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"C","multi":false,"explanation":"<p>本题考查科技常识。</p><p>①正确，LED灯是半导体电子跃迁直接发光（冷光源），它可以直接把电能转化为光能。卤素灯靠钨丝高温发光（热光源），大量电能转化为热能。因此LED灯比卤素灯更加节能，是公认更高效的照明方案。</p><p>②正确，油烟机核心是电机驱动风轮旋转：电能<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">电机内部电磁作用<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">产生旋转力矩<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">带动风轮高速转动<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">形成机械能（动能）。风轮的机械能再转化为气流的动能与风压，实现吸排油烟。因此油烟机工作时，电能主要转化为机械能。</p><p>③正确，家用最常见的分体式空调（挂机/柜机），压缩机、冷凝器、散热风扇都装在室外机中；室内机只有蒸发器、风机与电控。压缩机工作产生大量热，室外机直接向室外散热，效率更高。</p><p>④错误，洗衣机运行（尤其脱水）时，桶壁对衣物的弹力提供向心力，让衣物做圆周运动，方向指向圆心。但是衣服上的水珠因衣物纤维的拉力不足以提供所需向心力，沿切线飞出，因此实现了脱水。需要注意的是，向心力是由弹力提供的，不是一种独立产生的力。</p><p>综上，①②③表述正确，共3项。<br></p><p>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":34,"pid":"pc6b28bdffd"},{"qid":"16069765","no":1,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>岭南盆景注重自然美与人工美的和谐统一，通过修剪、蟠扎、嫁接等多种技法，将树木、山石、水景等自然元素巧妙地融入盆中，创造出“<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>”的艺术效果。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"一叶知秋"},{"k":"B","t":"管中窥豹"},{"k":"C","t":"一日千里"},{"k":"D","t":"咫尺千里"}],"answer":"D","multi":false,"explanation":"<p>横线处形容“艺术效果”，根据“岭南盆景注重自然美与人工美的和谐统一······将树木、山石、水景等自然元素巧妙地融入盆中”可知，横线处所填成语意在指出盆景可将自然界的树木、山水等景色浓缩于方寸之中，达到“以小见大、缩景于盆”的艺术效果。D项“咫尺千里”指距离虽近，却像远在千里之外，在艺术创作中常用来形容在狭小的空间内展现出辽阔深远的意境，符合文意，当选。<br>A项“一叶知秋”比喻通过个别的细微的迹象，可以看到整个形势的发展趋向，侧重于推理和预见，与文意不符，排除；<br>B项“管中窥豹”指从竹管的小孔里看豹，只看到豹身上的一块斑纹，比喻所见不全面，只看到事物的一部分，与盆景追求的“小中见大”之意不符，并且“从小孔里看”的方式与“盆景”这一主题词无法对应，排除；<br>C项“一日千里”原形容马跑得很快，后比喻进展极快，侧重于速度，与盆景的艺术效果无关，与文意不符，排除。<br>故正确答案为D。<br>【文段出处】广州日报《一盆一景一世界 广州市文化馆“岭南盆景艺术传承推广季”启动》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":35,"pid":"pc6b28bdffd"},{"qid":"16069755","no":2,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>中国传统山水画通过<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的手法营造出万千意境。苏绣艺术家深谙这一理念，在山水题材创作中巧妙利用绣地绢帛本色的“空白”与丝线绣制的“形象”，营造出“超以象外”的空间意境，打破了传统刺绣的密集形态，提升了画面的艺术表现力。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"虚实相生"},{"k":"B","t":"天人合一"},{"k":"C","t":"刚柔兼济"},{"k":"D","t":"举重若轻"}],"answer":"A","multi":false,"explanation":"<p>根据“在山水题材创作中巧妙利用绣地绢帛本色的‘空白’与丝线绣制的‘形象’”可知，横线处需体现将绣地绢帛本色的“空白”，即“无”或“虚”，与丝线绣制的“形象”，即“有”或“实”结合在一起的意思。A项“虚实相生”指通过虚与实的结合来表达意境，与文意相符，当选。<br>B项“天人合一”指天与人的关系紧密相连，不可分割，强调自然和人的结合，文段并非强调人与自然的结合，与文意无关，排除；<br>C项“刚柔兼济”指刚强的和柔和的互相配合，使恰到好处，文段并没有“刚”和“柔”的对应，与文意不符，排除；<br>D项“举重若轻”形容处理艰难问题或进行繁重的工作时都显得很轻松，文段并未指出处理难题或进行繁重工作很轻松，与文意无关，排除。<br>故正确答案为A。<br>【文段出处】人民日报《苏绣山水的诗性美学》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":36,"pid":"pc6b28bdffd"},{"qid":"16069754","no":3,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>今天，人们出游已不再满足于<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、拍照留念，而是希望体验风土人情、感受人文精神。<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的“城市伴手礼”，能满足游客“带走一座城记忆”的情感需求，更能提供独特的审美体验和精神享受，创造新的消费场景、业态和模式。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"蜻蜓点水 花样翻新"},{"k":"B","t":"走马观花 别具一格"},{"k":"C","t":"囫囵吞枣 独出心裁"},{"k":"D","t":"浅尝辄止 特立独行"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“不再······而是······”可知，横线处成语应与“体验风土人情、感受人文精神”的含义相反，表达不再满足不深入、走过场式的旅游。A项“蜻蜓点水”意为做事肤浅不深入，B项“走马观花”比喻匆忙地不深入细致地观察事物，均符合文意，保留。C项“囫囵吞枣”指读书等不加分析地笼统接受，通常用于学习或理解事物，D项“浅尝辄止”指做事不深入钻研或学习不求甚解，多用于读书、研究学习的语境，均不适合描述出游观光，排除。<br>第二空，搭配“城市伴手礼”，根据“能满足游客‘带走一座城记忆’的情感需求，更能提供独特的审美体验和精神享受”可知，横线处成语应表达独特、有当地特色之意。B项“别具一格”意为具有独特的风格，与“城市伴手礼”搭配恰当，且符合文意，当选。A项“花样翻新”意为通过改变形式或手法实现创新，侧重形式、样式不断更新，不强调独特、特色，与文意不符，排除。<br>故正确答案为B。<br>【文段出处】人民网《“城市伴手礼”中的人文经济学》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":37,"pid":"pc6b28bdffd"},{"qid":"16069852","no":4,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>为适应不同地域和气候条件，昆虫需要<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的季节性适应策略以及合理的年度生活史，以应对低温、短光照、食物匮乏等不利环境。滞育是昆虫在特定时期或特定季节性信号（如光变化、温度等）的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>下发生的发育停滞行为，可以帮助昆虫应对不利环境并显著延长昆虫的世代周期，因此也是造成昆虫不同年度生活史的生理基础。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"有效 诱导"},{"k":"B","t":"灵活 推动"},{"k":"C","t":"复杂 调控"},{"k":"D","t":"适宜 影响"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据前文“为适应不同地域和气候条件”可知，横线处应体现昆虫的策略能适配多样的环境。A项“有效”指有成效，有效果，符合文意，保留。B项“灵活”指不拘泥于固有模式，善于变通，呼应前文“适应不同地域和气候条件”，符合文意，保留。C项“复杂”指事物的种类、头绪等多而杂，感情色彩偏消极，排除；D项“适宜”指合适、相宜，与“适应”表意重复，排除。<br>第二空，根据“滞育是昆虫在特定时期······发生的发育停滞行为”可知，横线处应体现“特定时期或特定季节性信号”引发滞育行为之意。A项“诱导”指劝诱，引导，常用于生物行为由外部信号引发的语境，符合文意，当选。B项“推动”指使事物前进，适用于积极主动的语境，而文段昆虫滞育是一种由外部信号触发内部生理程序的被动适应策略，语意不符，排除。<br>故正确答案为A。<br>【文段出处】中国科学院《昆虫滞育研究取得重要进展》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":38,"pid":"pc6b28bdffd"},{"qid":"16070031","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>声音权与肖像权一样，都是每个人不容侵犯的合法权益。在日常生活中，肖像权因肖像直观可见而更易被理解和<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，比如明星头像被盗用，大家一眼就能看出不妥。但声音无形，一些人便误以为其中有“操作空间 ”，这也成了部分商家<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>通过AI 训练生成“仿制声音 ”的心理诱因。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"感知 巧立名目"},{"k":"B","t":"识别 明目张胆"},{"k":"C","t":"维系 投机取巧"},{"k":"D","t":"重视 堂而皇之"}],"answer":"D","multi":false,"explanation":"<p>第一空，横线处搭配“肖像权”，且根据“肖像直观可见······比如明星头像被盗用，大家一眼就能看出不妥” 可知，横线处表达肖像权容易被识别，能引起大家重视之意。A项“感知”指感觉，D项“重视”指认为重要而认真对待，均符合文意，保留。B项“识别”指辨别、辨认，“肖像”可以“识别”，而“肖像权”通常不与“识别”搭配使用， C项“维系”指维持联系，亦与“肖像权”搭配不当，均排除。<br>第二空，横线处修饰商家通过 AI训练生成“仿制声音 ”的行为，根据 “一些人便误以为其中有‘操作空间’” 可知，横线处表达商家自认为有理而不加掩饰地做此事。D项“堂而皇之”指公开、不加掩饰且表面正当，契合商家的心理与行为，当选。 A项“巧立名目”指虚构名义以达到不正当目的的行为，文中无“虚构名义”之意，排除。<br>故正确答案为D。 <br>【文段出处】劳动报《“声音被偷”，这样滥用AI要不得》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":39,"pid":"pc6b28bdffd"},{"qid":"16070018","no":6,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>说起某地的地理情况，它既可以指这一地区的山川水文、地形走势、气候等自然要素，也可能涉及行政区划、人口分布、风俗习惯等看似和地理关系不大，却又<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地决定了一个地方发展模式的人文要素。正是因为这门学科的外延如此<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，地理的学习才成了一项复杂的系统性工作。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"不言而喻 宽广"},{"k":"B","t":"不容置疑 抽象"},{"k":"C","t":"潜移默化 模糊"},{"k":"D","t":"实实在在 丰富"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“却”可知，横线处与前文构成转折关系，转折前指出诸多要素“看似和地理关系不大”，横线处则应体现这些要素对地方发展模式的决定作用是明确的，这些要素和地方发展模式是有较大关联的。D项“实实在在”形容真实存在、不夸张的事物，能体现人文要素对发展模式的决定作用是真切存在的，符合文意，保留。A项“不言而喻”指不用说就可以明白，也形容道理很浅显，通常放在句子最后使用，如“······的重要性不言而喻”“······的分量不言而喻”，置于此处用法不当，排除；B项“不容置疑”指不允许有什么怀疑，侧重于权威性、不可质疑，文段未体现对人文要素作用的质疑，而是强调其“切实影响”，排除；C项“潜移默化”指人的思想或性格不知不觉受到感染、影响而发生了变化，文段并无不知不觉受到影响之意，与文意不符，排除。<br>第二空，代入验证。根据前文“既可以指这一地区的山川水文、地形走势、气候等自然要素，也可能涉及行政区划、人口分布、风俗习惯等·····人文要素”可知，横线处表达地理这门学科的外延包含内容很多。D项“丰富”指种类多或数量大，符合文意，当选。<br>故正确答案为D。<br>【文段出处】公众号地球知识局《地图上的全景中国地理，性价比很高，仅3.1折！》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":40,"pid":"pc6b28bdffd"},{"qid":"16070013","no":7,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>草原生态脆弱，游客却漫天抛撒纸屑，无论是纸片可降解，抑或是其他“无害声明”，都不该成为“放肆”的理由。户外运动中有“无痕山林七原则”，其中之一是“勿留下任何人类的影响”。这是一种对自然的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。人们既然无法完全预知自身行为对环境的影响，那么还是“少做为妙”，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>将相关风险降到最低。<br>依次填入画横线部分最恰当的一项是（<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>）。</p>","options":[{"k":"A","t":"信仰 力争"},{"k":"B","t":"敬畏 主动"},{"k":"C","t":"尊重 率先"},{"k":"D","t":"庇护 自觉"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“户外运动中有······‘勿留下任何人类的影响’”“人们既然无法完全预知自身行为对环境的影响，那么还是‘少做为妙’”可知，横线处所填词语应体现人类对自然重视、崇敬的态度。B项“敬畏”指又敬重又畏惧，C项“尊重”指重视并严肃对待，均符合文意，且与“自然”搭配恰当，保留。A项“信仰”指相信并奉为准则或指南的某种主张、主义、宗教等，强调内心的信念，与文意不符，排除；D项“庇护”指袒护、保护，文段并非强调自然是需要人类庇护的弱者，而是要降低对自然环境的影响，排除。<br>第二空，根据“人们既然无法完全预知自身行为对环境的影响，那么还是‘少做为妙’”可知，横线处所填词语应体现人类积极采取措施，将风险降到最低之意，B项“主动”指自觉、自发去做，符合文意，当选。C项“率先”指带头、首先，文段并未体现与他人对比，带头做某事的语境，排除。<br>故正确答案为B。<br>【文段出处】新京报《在呼伦贝尔大草原狂撒纸片，生态保护不容“放肆”|新京报快评》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":41,"pid":"pc6b28bdffd"},{"qid":"16069792","no":8,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>奶皮子与糖葫芦的组合，精准<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>了年轻人“怀旧+猎奇”的双重心理，因此迅速风靡各地。对这些消费者而言，在快节奏的现代生活中，排队3小时的等待不再是<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，而是为热爱付出的仪式感；为此花费数十元也不再是<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的消费支出，而是犒劳自己的“小确幸”。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"契合 负累 轻率"},{"k":"B","t":"击中 煎熬 单纯"},{"k":"C","t":"捕捉 浪费 纯粹"},{"k":"D","t":"匹配 虚耗 奢侈"}],"answer":"B","multi":false,"explanation":"<p>本题从第二空入手，根据“不再是······而是······”可知，横线处与“为热爱付出的仪式感”语义相反，应体现等待是消极的、令人不快的体验。A项“负累”指负担，B项“煎熬”比喻折磨，D项“虚耗”指白白地消耗，均符合文意，保留。C项“浪费”指不充分利用，不合理，不珍惜，不必要地废弃，与文意无关，排除。<br>第三空，搭配“消费支出”，且根据“不再是······而是······”可知，横线处与“犒劳自己的‘小确幸’”语义相反，“小确幸”指日常生活中微小而确实的幸福与满足，故横线处应体现消费支出仅仅是花钱，无法带来其他的附属价值。B项“单纯”指单一，符合文意，保留。A项“轻率”指随随便便，不慎重，与“消费支出”搭配不当，排除；D项“奢侈”指挥霍浪费钱财，过分追求享受，与文段“花费数十元”的语境不符，排除。<br>第一空，代入验证，搭配“双重心理”，且根据后文“迅速风靡各地”可知，奶皮子与糖葫芦的组合与年轻人的心理相符合，B项“击中”比喻触及，切中，符合文意，当选。<br>故正确答案为B。<br>【文段出处】新京报快评《98元一串糖葫芦，何以被年轻人捧成“顶流”》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":42,"pid":"pc6b28bdffd"},{"qid":"16069778","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>中国人对地域文化的执着，或许从对“籍贯”的强调中<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。每个人一出生，就要标记出“籍贯”，从此它成为伴随人一生的身份信息。籍贯，不仅是简单的地理坐标，更是家族历史、文化基因的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。陌生人初次见面，“你是哪里人”的询问，本质上是对地域文化背后情感联结与身份认同的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"见微知著 传承 探讨"},{"k":"B","t":"可见一斑 承载 探寻"},{"k":"C","t":"略知一二 延续 追究"},{"k":"D","t":"以偏概全 印记 追寻"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“中国人对地域文化的执着，或许从对‘籍贯’的强调中······”可知，横线处应表达通过“籍贯”这一具体表现，能了解到中国人对地域文化的执着之意。B项“可见一斑”比喻见到事物的一小部分就能推知整体，C项“略知一二”指稍微知道一些，均符合文意，保留。A项“见微知著”指见到事物的一点苗头就能知晓其发展趋势或问题的实质，文段并非强调知晓发展趋势或问题的实质，与文意不符，排除；D项“以偏概全”指用片面的观点看待整体问题，感情色彩偏消极，与文段感情色彩不符，排除。<br>第二空，形容籍贯对家族历史、文化基因的作用。B项“承载”指托着物体，承受它的重量，C项“延续”指照原来的样子持续下去，均可形容籍贯对家族历史、文化基因的作用，保留。<br>第三空，搭配“情感联结与身份认同”，且根据“陌生人初次见面，‘你是哪里人’的询问”可知，横线处应表达对情感联结与身份认同的探求之意。B项“探寻”指探求、寻找，与“情感联结与身份认同”搭配恰当，且符合文意，当选。C项“追究”指追问根由，追查原因、责任等，与“情感联结与身份认同”搭配不当，排除。<br>故正确答案为B。<br>【文段出处】光明网《“苏超”文化梗：超越胜负的地域文化叙事》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":43,"pid":"pc6b28bdffd"},{"qid":"16069908","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>眼睛是十分<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的人体器官，对它“动刀”需要万分谨慎，因为任何一个环节的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>都可能造成严重后果。互联网时代，千万不能通过网上的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，就选择一家医院去做近视手术。<br>依次填入画横线部分最恰当的一项是:</p>","options":[{"k":"A","t":"复杂 松懈 流言蜚语"},{"k":"B","t":"关键 差池 一面之词"},{"k":"C","t":"精密 疏漏 只言片语"},{"k":"D","t":"独特 失误 不经之谈"}],"answer":"C","multi":false,"explanation":"<p>第一空，描述眼睛作为人体器官的特点，根据后文“对它‘动刀’需要万分谨慎” “任何一个环节······都可能造成严重后果”可知，横线处所填词语应突出眼睛结构精细、重要的特性， A项“复杂”指事物的种类、头绪等多而杂，B项“关键”指事物最紧要的部分，C项“精密”指精确细密，均符合文意，保留。D项“独特”指特有的，特别的，独一无二、与众不同的，文段并未将眼睛与其他器官对比，且与后文无法对应，排除。<br>第二空，与“环节”搭配，且根据“造成严重后果”可知，横线处应体现手术过程中任何一个环节出现的小问题都可能造成严重后果。B项“差池”指差错、意外的事，C项“疏漏”指疏忽遗漏，强调因疏忽而造成的错漏缺失，均符合文意，且与“环节”搭配恰当，保留。A项“松懈”指放松懈怠，多指态度、纪律松散，与“环节”搭配不当，排除。<br>第三空，形容“网上的”信息，根据“千万不能通过网上的······，就选择一家医院去做近视手术”可知，横线处应体现网络信息的特性。C项“只言片语”指个别的词句或片段的话，契合互联网时代信息碎片化的特征，符合语境，当选。B项“一面之词”指争执中一方的话，通常用于纠纷场景，与语境不符，排除。<br>故正确答案为C。<br>【文段出处】读者——《第一批做近视手术的人，现在后悔了吗？》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":44,"pid":"pc6b28bdffd"},{"qid":"16069995","no":11,"type":"片段阅读","module":"言语理解与表达","stem":"<p>现代洛阳的城市格局，是历史上不同时期城市发展格局遗痕的综合体，是城市形态变化的记录复合体，属于考古学上所说的“古今重叠型”城市。所谓古今重叠型城市，是相对荒野型城址而言的，就是根据城址的保存状况，针对那些叠压在现代城市之下的古代城址考古特征的总括。唐宋以后的地方城市，多为古今重叠型城市。古今重叠型城市考古，对解决现代城市中文化遗产保护与城市建设的矛盾具有指导意义。<br>根据这段文字可以推出（    ）。</p>","options":[{"k":"A","t":"唐宋以后逐渐形成古今重叠型城市"},{"k":"B","t":"现代城市大多建立在古代城址之上"},{"k":"C","t":"现代洛阳存有古代时期的城市遗迹"},{"k":"D","t":"当前城市发展不利于城市遗址保护"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“所谓古今重叠型城市，是······针对那些叠压在现代城市之下的古代城址考古特征的总括”以及“唐宋以后的地方城市，多为古今重叠型城市”可知，文段仅论述了什么是古今重叠型城市以及唐宋以后多为古今重叠型城市，未提及唐宋以后逐渐形成古今重叠型城市，无中生有，排除；<br>B项，文段并未提及现代城市大多建立在古代城址之上，无中生有，排除；<br>C项，根据“现代洛阳的城市格局······属于考古学上所说的‘古今重叠型’城市”以及“所谓古今重叠型城市······针对那些叠压在现代城市之下的古代城址考古特征的总括”可知，表述正确，当选；<br>D项，根据“唐宋以后的地方城市，多为古今重叠型城市。古今重叠型城市考古，对解决现代城市中文化遗产保护与城市建设的矛盾具有指导意义”可知，文段仅论述了当前古今重叠型城市考古对解决现代城市中文化遗产保护与城市建设矛盾的积极作用，未提及城市发展对城市遗址保护的消极影响，无中生有，排除。<br>故正确答案为C。<br>【文段出处】刊物《考古》2023年第8期《宣仁门遗址时代辨析》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":45,"pid":"pc6b28bdffd"},{"qid":"16070028","no":12,"type":"片段阅读","module":"言语理解与表达","stem":"<p>人工智能的算法主要关注在训练数据中频繁出现的信息，而不够普遍或统计上不够强大的数据往往会被忽视和排除，从而无法得到算法的充分理解和适当响应。依赖于统计频率的算法设计构成了一种特定的“认知盲从”，进而导致部分群体的声音被系统性边缘化。这种设计上的缺陷不仅限制了算法的认知能力，也加剧了社会中的不平等和认知压迫，破坏了认知正义。<br>根据这段文字，“认知盲从”会导致认知正义被破坏的原因不包括（    ）。</p>","options":[{"k":"A","t":"算法的设计加剧了社会中的不平等现象"},{"k":"B","t":"算法过于关注训练数据中频繁出现的信息"},{"k":"C","t":"算法依赖统计频率而忽视了部分群体的声音"},{"k":"D","t":"算法不能充分理解和适当响应非频繁信息数据"}],"answer":"A","multi":false,"explanation":"<p>根据“人工智能的算法主要关注在训练数据中频繁出现的信息，而不够普遍或统计上不够强大的数据往往会被忽视和排除，从而无法得到算法的充分理解和适当响应。依赖于统计频率的算法设计构成了一种特定的‘认知盲从’，进而导致······破坏了认知正义”可知，文段前三个分句即为“‘认知盲从’会导致认知正义被破坏”的原因，故B、C、D三项均属于原因，排除；<br>A项，根据“依赖于统计频率的算法设计构成了一种特定的‘认知盲从’，进而导致······也加剧了社会中的不平等和认知压迫，破坏了认知正义”可知，“加剧了社会中的不平等现象”是结果，而非原因，当选。<br>本题为选非题，故正确答案为A。<br>【文段出处】光明日报《如何让人工智能实现认知正义》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":46,"pid":"pc6b28bdffd"},{"qid":"16070124","no":13,"type":"片段阅读","module":"言语理解与表达","stem":"<p>气溶胶和悬浮颗粒爆发式喷出月表后快速冷却，形成火山玻璃珠。这些火山玻璃珠一般只有几十到几百微米，由于质量和体积都很小，其飞行距离可以非常远。同时，月球上广泛存在的陨石撞击会使其更容易被运移到更远的地方。这使月壤样品中发现火山玻璃珠，尤其是远距离搬运的火山玻璃珠的可能性更大，如果发现了火山玻璃珠，就可以进一步对月球岩浆活动历史进行质疑。<br>根据这段文字，发现月球上的火山玻璃珠对月球研究的意义是（    ）。</p>","options":[{"k":"A","t":"证明了月球火山活动的活跃性"},{"k":"B","t":"明确了月球火山活动的时间线"},{"k":"C","t":"体现了陨石撞击对月球的影响"},{"k":"D","t":"引发了月球地质活动史新探索"}],"answer":"B","multi":false,"explanation":"<p>文段首先介绍了火山玻璃珠的形成，接着以“同时”为标志，从两个方面指出火山玻璃珠可以飞到或者被运移到很远的地方，随后通过“这”指代前文，指出在月壤样品中发现火山玻璃珠的可能性很大，最后明确指出发现火山玻璃珠可进一步质疑月球岩浆活动历史，即能够进一步确认月球哪个时间段有岩浆活动，哪个时间段没有岩浆活动，即明确月球火山活动的时间线，对应B项。<br>A项，“月球火山活动的活跃性”虽然通过火山玻璃珠可以证明，但是相较于B项，无法体现文段表达的火山玻璃珠对岩浆活动历史的质疑，排除；<br>C项，陨石撞击是火山玻璃珠被远距离搬运的原因，并非发现火山玻璃珠的意义，排除；<br>D项，“地质活动”范围扩大，文段强调的意义是针对岩浆活动，即火山活动的，排除。<br>故正确答案为B。<br>【文段出处】地球科普网《嫦娥五号火山玻璃珠揭示月球1.2亿年前仍存在火山活动》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":47,"pid":"pc6b28bdffd"},{"qid":"16070006","no":14,"type":"片段阅读","module":"言语理解与表达","stem":"<p>地球大气和海洋中的氧气，从几乎为零逐步增长至接近现代水平，是地球宜居环境形成和生命演化的重要基础。如何准确重建地质历史时期海洋与大气的氧气含量，是地球科学前沿课题之一。钼作为一种对氧化还原条件敏感的元素，其同位素组成被广泛用于追溯古海洋的氧化还原历史。然而，要准确解读这一“地球化学密码”，必须首先厘清现代海洋中钼的来源、去向及其同位素平衡机制。<br>这段文字未提及（    ）。</p>","options":[{"k":"A","t":"氧气增长对宜居环境形成的作用"},{"k":"B","t":"钼同位素在古海洋研究中的价值"},{"k":"C","t":"古海洋时期钼与其同位素的关系"},{"k":"D","t":"厘清现代海洋中钼来源的必要性"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“地球大气和海洋中的氧气，从几乎为零逐步增长至接近现代水平，是地球宜居环境形成和生命演化的重要基础”可知，文段有提及，排除；<br>B项，根据“钼作为一种对氧化还原条件敏感的元素，其同位素组成被广泛用于追溯古海洋的氧化还原历史”可知，文段有提及，排除；<br>C项，“古海洋时期钼与其同位素的关系”文段并未提及，无中生有，当选；<br>D项，根据“要准确解读这一‘地球化学密码’，必须首先厘清现代海洋中钼的来源、去向及其同位素平衡机制”可知，文段有提及，排除。<br>本题为选非题，故正确答案为C。<br>【文段出处】中国能源报《解读“地球化学密码”，我国科研人员有了新发现！》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":48,"pid":"pc6b28bdffd"},{"qid":"16069980","no":15,"type":"片段阅读","module":"言语理解与表达","stem":"<p>电池充放电全靠锂离子在正负极间“往返跑”，锂离子就像电池中的“快递员”，负责把电子从电池正极送到负极，固态电解质就是它们“送快递”的“高速公路”。常用的硫化物固体电解质硬度高、脆如陶瓷，而金属锂电极却软得像橡皮泥。这两种材料贴合时，就像把橡皮泥粘在陶瓷板上，界面处坑坑洼洼，这样难走的路会影响电池充放电效率。近来，我国多个科研团队纷纷出手，三大关键技术的突破让“陶瓷板”和“橡皮泥”实现严丝合缝，有望打通固态电池的续航瓶颈，实现固态电池性能的跨越式升级。<br>关于固态电池，这段文字未提及（    ）。</p>","options":[{"k":"A","t":"技术突破将带来性能提升"},{"k":"B","t":"电极新材料的创新之处"},{"k":"C","t":"界面接触问题的形成原因"},{"k":"D","t":"电解质材料的物理特性"}],"answer":"B","multi":false,"explanation":"<p>A项，根据“三大关键技术的突破让‘陶瓷板’和‘橡皮泥’实现严丝合缝，有望打通固态电池的续航瓶颈，实现固态电池性能的跨越式升级”可知，“技术突破将带来性能提升”文段已提及，排除；<br>B项，文段并未提及“电极新材料的创新之处”，无中生有，当选；<br>C项，根据“常用的硫化物固体电解质硬度高、脆如陶瓷，金属锂电极却软得像橡皮泥。这两种材料贴合时，就像把橡皮泥粘在陶瓷板上，界面处坑坑洼洼，这样难走的路，会影响电池充放电效率”可知，“界面接触问题的形成原因”文段已提及，排除；<br>D项，根据“常用的硫化物固体电解质硬度高、脆如陶瓷”可知，“电解质材料的物理特性”文段已提及，排除。<br>本题为选非题，故正确答案为B。<br>【文段出处】央视网《新进展、新突破、新标准 这些科技“硬核”技术彰显中国力量》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":49,"pid":"pc6b28bdffd"},{"qid":"16070015","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>科学启蒙是需要良器的。市面上能买到的儿童科学实验套装琳琅满目，但多数停留在“好玩”层面，对科学原理的通俗讲解相对较少。以科普、百科为旗号的立体书、翻翻书、洞洞书，也多停留在现象描绘、现实陈述层面。诸如悬索桥如何受力、电能如何产生、火箭为什么能冲出地球之类的“原理之问”，也有童书涉及，但数量占比就少得多了。科学启蒙光“好玩”还不够，还要“能懂”。“好玩”可以更好激发科学好奇心，“能懂”则可以更好满足科学求知欲。好奇心爆棚、求知欲强烈，青少年才能从小打牢科学素养的根基。<br>这段文字意在强调（    ）。</p>","options":[{"k":"A","t":"科普读物的质量良莠不齐"},{"k":"B","t":"科普图书应注重原理讲解"},{"k":"C","t":"科学启蒙需要兼顾“能懂”"},{"k":"D","t":"“好玩”激发科学好奇心"}],"answer":"C","multi":false,"explanation":"<p>文段开篇指出科学启蒙需要良器，随后介绍市面上儿童科学实验套装及科普童书存在对科学原理讲解较少的问题，并以“悬索桥如何受力”等“原理之问”为例，紧接着提出对策，科学启蒙不仅要“好玩”，还要“能懂”，最后通过论述“好玩”及“能懂”的作用进一步说明两者兼顾对打牢青少年科学素养根基的重要性。故文段重在强调科学启蒙在“好玩”的同时还要兼顾“能懂”，对应C项。<br>A项，“质量良莠不齐”文段并未提及，无中生有，排除；<br>B项，“科普图书”范围缩小，文段重点为“科学启蒙”，排除；<br>D项，“激发科学好奇心”对应解释说明，非重点，且缺少文段主题词“能懂”，排除。<br>故正确答案为C。<br>【文段出处】人民日报《从稚童送“芯片”说起（金台随笔）》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":50,"pid":"pc6b28bdffd"},{"qid":"16069984","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>太空水资源的发现，有助于人类更好地认识地球上的水到底从何而来。科研人员也可以通过后续研究，寻找与地球环境类似的宜居星球。外太空的水或许并不能帮科学家探寻到地外生命，但足以为人类实现星际旅行和外星定居带来新的希望和可能性。<br>这段文字意在说明太空水资源的（    ）。</p>","options":[{"k":"A","t":"研究意义"},{"k":"B","t":"具体构成"},{"k":"C","t":"可能来源"},{"k":"D","t":"发现过程"}],"answer":"A","multi":false,"explanation":"<p>文段开篇表明太空水资源的发现有助于人类认识地球上水的来源，接着通过“也”引导并列结构，指出科研人员能借此寻找宜居星球，最后说明外太空的水还为人类星际旅行和外星定居带来新希望与可能性。故整个文段为并列结构，重点讨论太空水资源的研究意义，对应A项。<br>B项“具体构成”、C项“可能来源”、D项“发现过程”文段均未提及，无中生有，排除。<br>故正确答案为A。<br>【文段出处】科普时报《太空找水，人类为何如此执着》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":51,"pid":"pc6b28bdffd"},{"qid":"16070008","no":18,"type":"片段阅读","module":"言语理解与表达","stem":"<p>棉花花朵的子房包含着未来会发育成棉籽的胚珠。棉花开花授粉后，胚珠的表皮细胞开始分化，一部分向外突起、伸长，发育成棉纤维，胚珠本身受精后发育成种子（棉籽）。棉纤维是主产品，广泛应用于纺织工业；棉籽传统上被视为副产品，实则浑身是宝——棉籽仁可以榨油，残渣（棉籽粕）是优质的蛋白质饲料原料。棉纤维和种子的发育同时进行，共享母体植株供给的营养与能量。前期大量研究表明，许多影响纤维和种子最终表型的基因均在胚珠发育早期集中表达，此时代谢活动也极为旺盛，决定了后续纤维的产量、品质和种子的营养价值。<br>这段文字接下来最可能讲的是（    ）。</p>","options":[{"k":"A","t":"棉籽仁及棉籽粕的加工技术"},{"k":"B","t":"棉纤维以及棉籽的经济价值"},{"k":"C","t":"棉花种子的品质以及营养价值判断"},{"k":"D","t":"胚珠发育早期的基因表达与代谢调控机制"}],"answer":"D","multi":false,"explanation":"<p>本题为接语选择题，通读全文，重点关注文段最后论述的核心话题。文段开篇引出棉花胚珠，然后介绍胚珠发育成棉纤维和棉籽，并论述了棉纤维和棉籽的用途。接着指出棉纤维和种子发育同时进行且共享营养与能量，尾句指出影响纤维和种子最终表型的基因在胚珠发育早期集中表达，此时代谢活动极为旺盛，决定了后续纤维和种子的相关情况。所以文段最后论述的核心话题为“胚珠发育早期的基因表达和代谢活动”，根据话题一致原则，文段接下来应继续围绕“胚珠发育早期的基因表达和代谢活动”展开论述，对应D项。<br>A项“棉籽仁及棉籽粕的加工技术”、C项“品质以及营养价值判断”均与文段最后论述的核心话题不一致，衔接不当，排除；<br>B项，“经济价值”前文已有详细论述，后文不会再阐述，排除。<br>故正确答案为D。<br>【文段出处】中国科学报《打开棉花“总开关”：从经验育种到多元化品种设计》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":52,"pid":"pc6b28bdffd"},{"qid":"16070055","no":19,"type":"片段阅读","module":"言语理解与表达","stem":"<p>明代中国，传统经济向市场经济转型，在需求供给经济规律指引下，本土内生原发型变革推动了中国走向海外。中国是当时世界上最大的经济体，也是最大的白银需求国，白银在世界贸易中是国际通用结算方式。这种国际交换关系，一端联系中国商品，另一端联系海外白银。围绕中国的三条海上主干线，跨越三大洲，构建全球贸易网络，形成了市场网络的全球性链接。<br>根据这段文字，明代中国走向海外的主要驱动力是（    ）。</p>","options":[{"k":"A","t":"中国需要大量的白银以供消费"},{"k":"B","t":"跨越三大洲的全球贸易网络的形成"},{"k":"C","t":"中国作为当时世界最大经济体的影响力"},{"k":"D","t":"需求供给经济规律指引下的市场经济转型"}],"answer":"D","multi":false,"explanation":"<p>由提问方式可知，本题重点是寻找明代中国走向海外的主要驱动力，因此阅读文段时需重点锁定“推动中国走向海外的核心因素”，排除背景、条件、结果等无关信息。<br>文段开篇指出明代中国传统经济向市场经济转型，在需求供给经济规律指引下，本土内生原发型变革推动中国走向海外，直接对应题干要求寻找的“主要驱动力”。随后具体阐述中国在当时国际贸易中的地位以及白银在贸易中的作用，是对核心驱动力的补充说明，解释了中国能够走向海外、参与国际贸易的客观条件和物质基础。接着阐述这种围绕中国的国际交换关系，最终形成了市场网络的全球性链接，即介绍中国走向海外后产生的具体成果。故明代中国走向海外的主要驱动力应为在需求供给经济规律指引下，本土内生原发型变革，对应D项。<br>A项，根据“中国是当时世界上最大的经济体，也是最大的白银需求国，白银在世界贸易中是国际通用结算方式”可知，“中国需要大量的白银以供消费”是中国走向海外的具体背景与表现，并非主要驱动力，排除；<br>B项，根据“围绕中国的三条海上主干线，跨越三大洲，构建全球贸易网络，形成了市场网络的全球性链接”可知，“全球贸易网络的形成”是中国走向海外后产生的结果，而非主要驱动力，排除；<br>C项，根据“中国是当时世界上最大的经济体”可知，其经济地位是客观背景，是后文补充的参与国际贸易的条件，文段未提及该地位的“影响力”是走向海外的主要驱动力，排除。<br>故正确答案为D。<br>【文段出处】中国社会科学网《何以全球化：明代中国与世界》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":53,"pid":"pc6b28bdffd"},{"qid":"16070016","no":20,"type":"片段阅读","module":"言语理解与表达","stem":"<p>世界是真与假、善与恶、美与丑的混合体，因而不存在黑白分明的“时代精神”，更不存在单一维度的“时代精神”。社会生活中的事件并不都是正剧或喜剧，有时是悲剧，有时是丑剧，有时是闹剧。所以，文学创作不能也不应回避假、恶、丑的对象，因为掩盖矛盾和问题不等于矛盾和问题不存在；把矛盾和问题的盖子掀起来，有利于问题的解决和社会的进步。就此而言，作家在描述这种现象时，必须对不同立场持多元观念和包容态度——深刻的思想和认识往往来自生活本身所具有的激烈矛盾和冲突，平静如水的生活不可能产生深刻的思想。<br>这段文字意在强调（    ）。</p>","options":[{"k":"A","t":"社会生活是文学艺术创作的唯一源泉"},{"k":"B","t":"新时代文学当具中国气质与时代精神"},{"k":"C","t":"优秀的文学作品应反映社会多元文化"},{"k":"D","t":"作家应具有包容意识和多元开放心态"}],"answer":"D","multi":false,"explanation":"<p>文段首先指出世界是复杂的，不存在单一维度的“时代精神”，社会生活事件有多种形态，文学创作不应回避假、恶、丑，揭露问题有利于社会进步。随后通过“就此而言”引出结论，强调作家在描述现象时必须对不同立场持多元观念和包容态度，最后进行原因解释，对应D项。<br>A项，“唯一源泉”表述过于绝对，文段仅强调生活对文学创作和深刻思想的重要性，并未提及“唯一”，排除；<br>B项，文段未提及“中国气质”，无中生有，排除；<br>C项，“优秀文学作品”非重点，文段重点强调的是作家对待社会多元现象的态度，排除。<br>故正确答案为D。<br>【文段出处】人民论坛网《弘扬时代精神，创造高峰文学作品》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":54,"pid":"pc6b28bdffd"},{"qid":"16070129","no":21,"type":"片段阅读","module":"言语理解与表达","stem":"<p>只有交通大发展，主产粮区和经济中心分开才成为可能。古代最大规模的粮食转移，就是大运河漕运。北京北枕燕山，西倚太行，南领平原，东望渤海，处于内蒙古高原、华北平原和东北平原联结带。明清时大运河一头连到北京，另一头是钱粮税赋的来源地江南。正是运河上往来如梭的船只，保障了京师朝廷的正常运转，也让北京成为东北亚的十字路口。相比于大运河的南粮北运，今天的北粮南运，其实与中国一千年来的整体经验相反。但是如果纵观中国历史，就会发现粮食转移的变化远不止这一次。<br>这段文字摘自某篇文章，该文章的主题最可能是（    ）。</p>","options":[{"k":"A","t":"大运河对中国历史的影响"},{"k":"B","t":"中国粮食生产的时空格局"},{"k":"C","t":"首都北京的自然地理特征"},{"k":"D","t":"古代内陆交通的发展历程"}],"answer":"B","multi":false,"explanation":"<p>文段开篇说明交通大发展可以将主产粮区的粮食运往经济中心。随后列举古代粮食转移的案例进行论证，古代通过大运河将产粮区江南的粮食运往北京，并说明这一举措对北京的意义。接着文段强调今天的“北粮南运”与历史上大运河的“南粮北运”是相反的，由此可知历史上粮食的主产地是南方地区，而今天粮食的主产地是北方地区，粮食产地的变化引发了粮食转运路线的改变。文段末尾通过转折词“但是”强调在中国历史上，粮食转移的变化较多。故文段围绕核心话题“粮食”展开，并强调从古至今粮食产地发生多次变化，对应B项。<br>A项“对中国历史的影响”、D项“古代内陆交通的发展历程”文段均未提及，无中生有，且缺少主题词“粮食”，排除；<br>C项，“首都北京的自然地理特征”为举例内容，非重点，且缺少主题词“粮食”，排除。<br>故正确答案为B。<br>【文段出处】北粮南运时代，中国北方在供养南方？</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":55,"pid":"pc6b28bdffd"},{"qid":"16070017","no":22,"type":"片段阅读","module":"言语理解与表达","stem":"<p>价格、品质和服务决定了一款产品是否具备竞争力。无论是保证品质还是提供服务，这些动作都是有成本的。若一味追求低价，不断压榨商家的利润空间，很可能导致用心经营的商家或被迫以次充好，或因资金链断裂而被劣币驱逐。特别是在当前经济环境承压、消费有效需求不足的背景下，平台打价格战，为此兜底的商家遭受的打击无疑是毁灭性的。长此以往，行业生态必将被破坏殆尽，微观企业生存都成问题，遑论各个产业的高质量发展。为低价又劣质的产品买单的消费者，还是最大的受害者。<br>这段文字意在说明（   ）。</p>","options":[{"k":"A","t":"平台打价格战可能会造成严重恶果"},{"k":"B","t":"企业在经营上面临前所未有的挑战"},{"k":"C","t":"品质与服务才是产品的核心竞争力"},{"k":"D","t":"良好的市场生态能使各方从中受益"}],"answer":"A","multi":false,"explanation":"<p>文段开篇指出价格、品质和服务共同决定产品竞争力，且品质和服务均有成本。接着表明若一味追求低价、打价格战可能导致用心经营的商家被驱逐、行业生态被破坏、企业生存艰难，消费者最终也受害。故文段围绕“价格”展开，强调一味追求低价、打价格战的危害极大，对应A项。<br>B项，“前所未有的挑战”表述不明确，排除；<br>C项，“品质与服务是核心竞争力”为文段开头引出话题部分，非重点，排除；<br>D项，文段强调价格战的危害，未提及“良好市场生态使各方受益”，无中生有，排除。<br>故正确答案为A。<br>【文段出处】《为低价狂欢的时代过去了》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":56,"pid":"pc6b28bdffd"},{"qid":"16069997","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>人类已探测到的100多次引力波事件中，绝大多数来自双黑洞并合，双黑洞是如何形成和演化的？目前学术界尚无定论。中国科学家首次提出新颖的三体系统“极端质量比旋近双星”理论设想，即双黑洞是被一个超大质量致密天体抓住，形成“三人组”。双黑洞在这个致密天体附近“跳舞”，进而辐射多频段的引力波。为证实该设想，他们深入研究已探测到的引力波事件，最终将目标锁定在GW190814。该事件中的两个黑洞质量相差近10倍，如此悬殊的组合，很可能就是因为它们背后存在一个致密天体，让它们在彼此引力拉扯下越靠越近。<br>最适合做这段文字标题的是（    ）。</p>","options":[{"k":"A","t":"双黑洞并合之谜已被破解"},{"k":"B","t":"引力波的探测历程与突破"},{"k":"C","t":"双黑洞“三人组”理论亮相"},{"k":"D","t":"GW190814事件独特性解析"}],"answer":"C","multi":false,"explanation":"<p>文段开篇介绍引力波绝大多数来自双黑洞并合，而双黑洞如何形成和演化尚无定论，接着指出中国科学家首次提出三体系统“极端质量比旋近双星”理论设想，即双黑洞与超大质量致密天体形成“三人组”，进而辐射多频段的引力波。后文详细介绍了科学家为证实该设想的具体研究过程。故文段重点介绍的是中国科学家提出的双黑洞“三人组”理论设想，对应C项。<br>A项，“双黑洞并合之谜已被破解”无中生有，科学家只是提出理论设想，并非已经破解谜团，排除；<br>B项，“引力波”偏离文段重点，且“探测历程”无中生有，排除；<br>D项，“GW190814事件”为解释说明部分，非文段重点，排除。<br>故正确答案为C。<br>【文段出处】新华网《星空有约丨我国科研人员首次发现：双黑洞背后可能隐藏第三个致密天体》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":57,"pid":"pc6b28bdffd"},{"qid":"16070022","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>微波辅助催化技术是一项实现填埋场混杂废塑料高值利用的新技术，特制的Zn/b-ZnO催化剂和微波的独特作用，是该技术为塑料垃圾带来“重生”的关键。Zn/b-ZnO催化剂由两个功能单元组成：b-ZnO能吸收微波能量并转化为局部热量，就像给塑料垃圾搭建了一个烹饪炉，使其更易发生反应；原位生成的Zn团簇则像菜刀，专门负责切断塑料分子中顽固的C-C键。微波则像厨师，通过选择性加热对塑料垃圾进行处理。相比于传统加热方式，微波能精准找到催化剂，只对其加热，反应速度更快，还能大大减少能量浪费。<br>最适合做这段文字标题的是：</p>","options":[{"k":"A","t":"从塑料到资源：原子簇-氧化物的协同效应"},{"k":"B","t":"告别能量浪费：神奇的微波选择性加热技术"},{"k":"C","t":"塑料垃圾处理新技术：微波与催化剂的烹饪二重奏"},{"k":"D","t":"塑料垃圾的蜕变：微波助力塑料垃圾实现高值利用"}],"answer":"C","multi":false,"explanation":"<p>文段开篇指出微波辅助催化技术是实现废塑料资源化利用的新技术，接着强调特制Zn/b-ZnO催化剂与微波两者在其中发挥关键作用，随后分别围绕Zn/b-ZnO催化剂和微波两方面展开论述，介绍两者在其中发挥的具体作用。故文段围绕微波辅助催化技术处理塑料垃圾展开，介绍了微波与催化剂两者的协同作用，对应C项。<br>A项，缺少文段主题词“微波”和“塑料垃圾处理”，且“原子簇-氧化物的协同效应”表述不准确，文段强调的是Zn/b-ZnO催化剂和微波共同作用处理塑料垃圾，排除；<br>B项，缺少文段主题词“塑料垃圾处理”，且“神奇的微波选择性加热技术”仅强调微波作用，未体现催化剂的关键作用，表述片面，排除；<br>D项，仅强调微波助力塑料垃圾实现高值利用，未突出特制Zn/b-ZnO催化剂的重要作用，表述片面，排除。<br>故正确答案为C。<br>【文段出处】中国科学院《微波催化有望让塑料垃圾变废为宝》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":58,"pid":"pc6b28bdffd"},{"qid":"16070005","no":25,"type":"片段阅读","module":"言语理解与表达","stem":"<p>西方传统海洋政治叙事往往基于一国利益的考量，主张通过控制海洋、战胜敌国进而实现“制海”的战略目标，但这种依托个体理性构建的海洋治理观无视海洋治理的全球公共性和整体关联性，给国际社会带来的是大国争霸海洋和海洋治理赤字，因而亟须代之以新的海洋治理理念和叙事。新型海洋命运共同体叙事遵循关系理性，以构建关系共同体和命运共同体为长远目标，主张关系治理和合作治理，促进国家间关系和谐及“人海和谐”，进而推动全球海洋治理和善治，真正实现人类的“治海”理想。<br>假如这是一篇论文的摘要，那么最适合作为论文标题的是（    ）。</p>","options":[{"k":"A","t":"大变局下的全球海洋治理与中国"},{"k":"B","t":"对新时期中国参与全球海洋治理的思考"},{"k":"C","t":"从“制海”到“治海”：构建海洋命运共同体"},{"k":"D","t":"海洋命运共同体：海洋治理体系变革的中国贡献"}],"answer":"C","multi":false,"explanation":"<p>文段开篇指出西方传统海洋政治叙事主张通过控制海洋、战胜敌国实现“制海”目标，但存在无视海洋治理的全球公共性和整体关联性，引发争霸与治理赤字的弊端。随后提出亟须新的海洋治理理念，引出新型海洋命运共同体叙事，其遵循关系理性，主张关系治理和合作治理，目标是实现“治海”理想。故文段围绕海洋治理理念从“制海”到“治海”的转变展开论述，核心话题为构建海洋命运共同体，对应C项。<br>A、B两项，均未提及文段主题词“海洋命运共同体”，排除；<br>D项，未体现从“制海”到“治海”的转变过程，重点强调“中国贡献”，偏离了文段核心，排除。<br>故正确答案为C。<br>【文段出处】人民论坛网·国家治理网《从“制海”到“治海”：构建海洋命运共同体》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":59,"pid":"pc6b28bdffd"},{"qid":"16070019","no":26,"type":"片段阅读","module":"言语理解与表达","stem":"<p>中国整体位于中纬度，大部分地区四季分明，由夏季到冬季的冷热转换是由于太阳直射点移动造成的风带和气压带的季节移动。①在冬季，西北风将西伯利亚的强冷空气带进并横扫中国，造成大幅度降温和大风天气。②在北半球冬季，由于接收到的太阳辐射较少，北极近地面形成冷性高压，高空则对应低压，在地转偏向力和山地地形的作用下形成极地涡旋，这就是冷空气的“仓库”。③在涡旋变弱时，来自低纬度的气团就会挤压北部冷空气使其向南移动。④据统计，欧亚大陆95%的冷空气都要经过西伯利亚中部地区，并在那里积累加强，我们称其为“寒潮关键区”。<br>下面这段文字应该放在文中哪个位置？（    ）<br>与大多数人所想的不同，冷空气真正的“老窝”并非西伯利亚，而是在北极。</p>","options":[{"k":"A","t":"①处"},{"k":"B","t":"②处"},{"k":"C","t":"③处"},{"k":"D","t":"④处"}],"answer":"B","multi":false,"explanation":"<p>所填句子应与前后文话题衔接得当，所给句子指出冷空气的来源并非西伯利亚，而是北极，故所填位置的前后文话题应与之保持一致。B项，②处前文介绍西北风将西伯利亚的强冷空气带进中国，造成降温和大风天气，后文介绍因太阳辐射较少，北极形成极地涡旋，即冷空气的“仓库”，填入此处前后文衔接恰当，当选。<br>A项，①处前文介绍中国大部分地区四季分明的原因，后文介绍冷空气的来源是西伯利亚，放入此处衔接不当，排除；<br>C项，③处前文介绍北极形成极地涡旋，是冷空气的“仓库”，后文介绍极地涡旋变弱的情况，内容衔接紧密，无法插入所给句子，排除；<br>D项，④处前文介绍极地涡旋变弱的情况，后文介绍“寒潮关键区”，放入此处衔接不当，排除。<br>故正确答案为B。<br>【文段出处】科学与中国《我们会迎来一个最冷的冬天吗？》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":60,"pid":"pc6b28bdffd"},{"qid":"16070029","no":27,"type":"语句表达","module":"言语理解与表达","stem":"<p>我们常说的“视听盛宴”是一种联觉反应，它是视觉和听觉的感官联合。我们在观看表演时，看到了宏伟的场面，听到了振奋人心的音乐，就会产生震撼感；如果我们看到的是舞者翩翩起舞，听到的是优美的音乐，就会觉得心旷神怡。<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。如《梁山伯与祝英台》“十八相送”中的双人舞，非常轻曼、凄美，可如果伴奏音乐是美国西部牛仔音乐，就会使人产生很不舒服的撕裂感。<br>填入画横线部分最恰当的一项是（<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>）。</p>","options":[{"k":"A","t":"如果表演和音乐搭配不当，就会让产生的感觉大打折扣"},{"k":"B","t":"人们看到冲击性较大的图片时，会引发听觉区域的兴奋"},{"k":"C","t":"当视觉与听觉配合失衡时，舞蹈的美感会严重受损"},{"k":"D","t":"我们在观看电影时，需要视觉和听觉的共同作用"}],"answer":"A","multi":false,"explanation":"<p>横线位于文段中间，需结合前后文进行分析。横线前指出“视听盛宴”是视觉和听觉的感官联合，接着指出当看到的表演和听到的音乐相契合时，会给人带来很好的感受。横线后又通过举例说明，当看到的表演和听到的音乐配合不当时，会给人带来很不舒服的撕裂感。故横线处所填内容应承上启下，体现表演和音乐搭配不当会产生不良感觉之意，对应A项。<br>B项，“图片”无中生有，与后文“如”中的例子无法衔接，排除；<br>C项，“舞蹈”虽与后文例子衔接得当，但前文长句为并列结构，“舞蹈”仅对应分号之后，因此有概念范围缩小之嫌，不及A项更为准确，排除；<br>D项，“电影”无中生有，且“需要共同作用”表述不当，文段表达的是表演和音乐需搭配得当，而非只是共同作用，无法与前后文衔接，排除。<br>故正确答案为A。<br>【文段出处】大科技微信公众号《你能听到GIF的声音吗？》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":61,"pid":"pc6b28bdffd"},{"qid":"16070023","no":28,"type":"语句表达","module":"言语理解与表达","stem":"<p>我国《宪法》明确了劳动权是公民的基本权利之一，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。按照《就业促进法》的规定，用人单位、人力资源服务机构不得基于法律禁止的归类因素对劳动者实施差别对待，这些法律禁止的归类因素通常都是个人通过主观努力而无法改变的因素，包括民族、种族、性别等。如果在招录时无正当理由对劳动者差别对待，就构成违法的就业歧视行为。<br>填入画横线部分最恰当的一项是（<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>）。</p>","options":[{"k":"A","t":"这就要求用人单位秉持公平原则"},{"k":"B","t":"而平等就业是劳动权的重要内容"},{"k":"C","t":"但在现实中，就业歧视普遍存在"},{"k":"D","t":"任何单位均需在用工环节遵守《宪法》"}],"answer":"B","multi":false,"explanation":"<p>横线出现在文段首句，且为首句中的分句，需结合前后文内容进行分析。横线前提出“劳动权”的话题，指出劳动权是公民的基本权利之一，横线后指出用人单位、人力资源服务机构不得基于法律禁止的归类因素对劳动者实施差别对待，否则就构成就业歧视，强调应注重平等就业，故横线处既要承接前文“劳动权”的话题，又要引出后文“平等就业”的话题，对应B项。<br>A项，“秉持公平原则”表述较为笼统，后文重点强调“平等就业”，且“用人单位”表述片面，后文还提及了“人力资源服务机构”，与后文衔接不当，排除；<br>C项，“就业歧视普遍存在”文段并未提及，无中生有，排除；<br>D项，未提及“劳动权”“平等就业”，与前后文衔接不当，排除。<br>故正确答案为B。<br>【文段出处】经济观察网《携带地贫基因被解聘，体检“国标”该修了》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":62,"pid":"pc6b28bdffd"},{"qid":"16070126","no":29,"type":"语句表达","module":"言语理解与表达","stem":"<p>①这个舒适圈可从两个方面来理解，一方面是来源于用户对它的使用依赖，另一方面则是已然形成的信息茧房<br>②算法舒适圈中的用户在对生成式人工智能的过度依赖中被算法规训，不断丧失独立性和多元化意识<br>③生成式人工智能生成的观点对受众传输，算法推荐机制运行让其在心理、认知等方面产生舒适圈<br>④个人看似在选择性地接受和拒绝，实则自由意志受到技术的严重侵蚀<br>⑤生成式人工智能输出的内容是基于筛选过的数据和信息生成，是算法选择呈现的结果<br>⑥平台和网络供应商通过算法技术提供个性化体验的同时，也可能成为形成个人本位困境、群体极化和碎片化的原因<br>将以上6个句子重新排列，语序正确的一项是（    ）。</p>","options":[{"k":"A","t":"⑤④⑥③①②"},{"k":"B","t":"③①⑤⑥④②"},{"k":"C","t":"⑤④②③①⑥"},{"k":"D","t":"③①④②⑤⑥"}],"answer":"B","multi":false,"explanation":"<p>对比选项，确定首句。③句通过生成式人工智能的运作机制引出“算法舒适圈”的话题，⑤句介绍生成式人工智能输出的内容是如何产生的，首句不易判断，寻找其他线索解题。<br>观察选项可知，四个选项③①均相连，③①引出话题“算法舒适圈”，并从两个方面进行解释说明，观察可知，②句也提及话题“算法舒适圈”，指出算法舒适圈会让用户丧失独立性和多元意识，按行文逻辑，应先引出话题“算法舒适圈”，再介绍其所带来的危害，③①在②句之前，排除C项。<br>对比A、B、D三项，⑤句之后接④或⑥句，⑤句对生成式人工智能输出的内容进行介绍，⑥句指出人工智能为用户带来个性化体验的同时也会带来负面影响，④句介绍用户表面是“自由选择”人工智能输出的观点，实则个人意识已受技术侵蚀，分析可知，④句在对⑥句论述的负面影响作进一步解释说明，故⑥句应在④句之前，答案锁定B项。<br>验证选项，③①引出话题“算法舒适圈”并进行解释，⑤⑥④三句指出生成式人工智能借助算法进行内容输出，为用户带来个性化体验（即形成算法舒适圈）的同时也可能带来一定的负面影响，②句对整个过程进行总结，呼应了③①中提到的舒适圈“使用依赖”和“信息茧房”导致的最终结果，逻辑合理恰当，并且④句中“个人的自由意志受到技术的严重侵蚀”与②句中“被算法规训，不断丧失独立性和多元化意识”衔接顺畅，B项当选。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":63,"pid":"pc6b28bdffd"},{"qid":"16070021","no":30,"type":"语句表达","module":"言语理解与表达","stem":"<p>①所以，经典的意义不仅仅在于为我们提供某种现实的启示<br>②不仅仅是对文章的解读，更有观念上的激荡<br>③我们对于经典的关注，并不是为了获取某种特定的知识<br>④在阅读经典的过程中，我们一方面领略了以往思想家的心路历程，另一方面又可以和历史上的思想家展开某种独特的对话，形成一种思想上的互动<br>⑤在与以往思想家的沟通、互动中，我们可以不断深入社会，并由此推动对世界和人本身的理解<br>⑥更多的是要回溯前人所经历的思想智慧的历程<br>将以上6个句子重新排列，语序正确的一项是：</p>","options":[{"k":"A","t":"③②①④⑥⑤"},{"k":"B","t":"⑤④②③⑥①"},{"k":"C","t":"③⑥①④②⑤"},{"k":"D","t":"⑤④③⑥②①"}],"answer":"C","multi":false,"explanation":"<p>本题可从尾句入手。⑤句“我们可以······，并由此推动对世界和人本身的理解”是对前文经典意义的总结，属于结论性尾句；①句指出“所以，经典的意义不仅仅在于······”未完整点明经典的意义何在，不适合做尾句，因此排除B、D两项，保留A、C两项。<br>对比A、C两项，③句后所接句子分别为②句和⑥句。⑥句“更多的是”作为肯定表述，可与③句的“并不是······”构成反义并列，两句衔接恰当，C项当选。②句“不仅仅······”无法与③句的“并不是······”对应，两句逻辑上无法衔接，排除A项。<br>故正确答案为C。<br>【文段出处】搜狐《宣讲家文稿：历史中的经典及其意义》</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":64,"pid":"pc6b28bdffd"},{"qid":"16069782","no":1,"type":"数学运算","module":"数量关系","stem":"<p>小刘在某APP上学习党史知识，第一天有若干道题，答完8道后，剩下未答完的题目数量自动增加一倍；第二天答8道题，剩下未答完的题目数量又增加一倍；第三天答8道题后正好答完，问第一天开始时有多少道题？</p>","options":[{"k":"A","t":"14"},{"k":"B","t":"15"},{"k":"C","t":"16"},{"k":"D","t":"17"}],"answer":"A","multi":false,"explanation":"<p>方法一：设第一天开始时有x道题，每天剩余题目如下：</p><p><img src=\"assets/img/timu/19ceb4e7edfecff.png\" class=\"fig\" style=\"width:610px;height:100px;\"></p><p>根据题干第三天答8道题后正好答完，可得方程：<img src=\"assets/img/gongshi/formula-6dfcd5754e899b64.png\" class=\"tex\">，解得：x=14。故第一天开始时有14道题。</p><p>方法二：根据题意，第二天答题剩余题目增加一倍后的题量，第三天答8道题后正好答完，考虑代入排除法：</p><p>代入A项，当第一天开始有14道题时，第一天答题完毕剩余题量为14-8=6道，增加一倍后剩余题目为2×6=12道，第二天答题完毕剩余题量为12-8=4道，增加一倍后剩余题目为4×2=8道，第三天答8道题后正好答完，符合题意，当选；</p><p>代入B项，当第一天开始有15道题时，第一天答题完毕剩余题量为15-8=7道，增加一倍后剩余题目为2×7=14道，第二天答题完毕剩余题量为14-8=6道，增加一倍后剩余题目为2×6=12道，第三天答8道题后不能正好答完，排除；</p><p>代入C项，当第一天开始有16道题时，第一天答题完毕剩余题量为16-8=8道，增加一倍后剩余题目为2×8=16道，第二天答题完毕剩余题量为16-8=8道，增加一倍后剩余题目为2×8=16道，第三天答8道题后不能正好答完，排除；</p><p>代入D项，当第一天开始有17道题时，第一天答题完毕剩余题量为17-8=9道，增加一倍后剩余题目为2×9=18道，第二天答题完毕剩余题量为18-8=10道，增加一倍后剩余题目为2×10=20道，第三天答8道题后不能正好答完，排除。</p><p>故正确答案为A。</p><p>备注：代入A项符合题目所有条件，其他选项无需代入。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":65,"pid":"pc6b28bdffd"},{"qid":"16069763","no":2,"type":"数学运算","module":"数量关系","stem":"<p>某商店第1天销售m件商品，从第2天开始，每天都比前一天多卖n件，其前10天售出的商品是前5天的2.5倍。问m是n的多少倍？</p>","options":[{"k":"A","t":"5"},{"k":"B","t":"6"},{"k":"C","t":"7"},{"k":"D","t":"8"}],"answer":"D","multi":false,"explanation":"<p>根据题意，设商店每天销售商品的销量为首项<img src=\"assets/img/gongshi/formula-50402be19e50b0e0.png\" class=\"tex\">、公差d=n的等差数列。根据等差数列求和公式：<img src=\"assets/img/gongshi/formula-2978d14a3289486d.png\" class=\"tex\">，该商店前10天的销量为：<img src=\"assets/img/gongshi/formula-d6b20ab804ce75f1.png\" class=\"tex\">；前5天的销量为：<img src=\"assets/img/gongshi/formula-83d1131722754efd.png\" class=\"tex\">。又根据：前10天售出的商品是前5天的2.5倍，则10m+45n=2.5×（5m+10n），解得：<img src=\"assets/img/gongshi/formula-0f0f08ab3bae33f8.png\" class=\"tex\">。即m是n的8倍。</p><p>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":66,"pid":"pc6b28bdffd"},{"qid":"16069786","no":3,"type":"数学运算","module":"数量关系","stem":"<p>甲和乙从全长n米的环形跑道上某一点同时匀速出发，如两人同向跑步，则甲第一次追上乙的用时是两人反向跑步第一次相遇用时的8倍。如两人反向跑步，那么第一次相遇时乙跑了多少米？</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-6832f942cfa9eadf.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-8445298a564867a6.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-56bee9c20d07fe5a.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-d69486bc29ad9767.png\" class=\"tex\"></p>"}],"answer":"D","multi":false,"explanation":"<p>根据题意，设两人反向跑步第一次相遇时所用时间为t，甲的速度为<img src=\"assets/img/gongshi/formula-2abaad9453fe9869.png\" class=\"tex\">，乙的速度为<img src=\"assets/img/gongshi/formula-c88e62867b5bd942.png\" class=\"tex\">，根据环形相遇公式<img src=\"assets/img/gongshi/formula-84d8b8cb1bcef3c1.png\" class=\"tex\">，可得<img src=\"assets/img/gongshi/formula-f750192e6158546d.png\" class=\"tex\">······①；则两人同向追及时间为8t，根据环形追及公式<img src=\"assets/img/gongshi/formula-ad24c16b11552ad7.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-9c123d350610f4f9.png\" class=\"tex\">······②；将①-②可得<img src=\"assets/img/gongshi/formula-a931ef1f86ac4f3f.png\" class=\"tex\">，故两人反向跑步，第一次相遇时乙跑了<img src=\"assets/img/gongshi/formula-d71a6230cce363e4.png\" class=\"tex\">米。</p><p>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":67,"pid":"pc6b28bdffd"},{"qid":"16069941","no":4,"type":"数学运算","module":"数量关系","stem":"<p>某市低空经济示范区要为8个无人机起降点设计航线网络。若任意两个起降点之间最多1条航线，且每个起降点至少连接3条航线，问最少需要设计多少条航线？</p>","options":[{"k":"A","t":"12"},{"k":"B","t":"22"},{"k":"C","t":"28"},{"k":"D","t":"56"}],"answer":"A","multi":false,"explanation":"<p>把题干中提到的8个无人机起降点理解为平面几何图形的8个顶点，航线为点与点之间的连线，即为该几何图形的边。题目要求“每个起降点至少连接3条航线，且要使航线数最少”，可以判断出每个起降点只需连接三条航线可使总航线数最少，即构成的图形中每个顶点的度数为3（一个顶点的度数指的是与该顶点相连的边的数量）。由此这个题目可以理解为：有8个顶点的平面几何图形（无重复边），每个顶点的度数为3，求图形的边数。这类题型可以根据“握手定理”解决：所有顶点度数之和=边数×2。该题目共8个顶点，每个顶点的度数为3，8个顶点度数之和=8×3=24，根据“握手定理”的公式可以求得：边数<img src=\"assets/img/gongshi/formula-b775fa4bd34e1b13.png\" class=\"tex\">，因此该图形最少的边数为12条，即最少需要设计12条航线。</p><p>故正确答案为A。</p><p>备注：关于“握手定理”的理解，可以把每个顶点都想象成一个参加会议的人，他们之间相互握手，每一次握手构成一条“边”，每个人握手的次数就是顶点的度数。每一次握手都会涉及两个人，所以一次握手事件会分别被双方记录一次，次数计入到自己的握手次数中，算成自己的度数。所以可得：总握手次数（总度数）=2×握手事件发生的次数（边的数量）。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":68,"pid":"pc6b28bdffd"},{"qid":"16069808","no":5,"type":"数学运算","module":"数量关系","stem":"<p>某企业每周从下属8个门店中随机选择6个进行巡查。问下周巡查的门店正好有5个与本周相同的概率为：</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-c631bfd5fefeed63.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-51535774e33263f4.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-bf55216495bd73d0.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-0577654965e9c91a.png\" class=\"tex\"></p>"}],"answer":"C","multi":false,"explanation":"<p>根据题意，下周巡查门店的情况为从8个门店中随机选择6个进行巡查，总情况数<img src=\"assets/img/gongshi/formula-0a56fd52588c203c.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-f02ae442262b50f5.png\" class=\"tex\">种；满足条件的情况为“下周巡查的门店正好有5个与本周相同”，先从本周巡查的6个门店中选择5个与下周相同，情况数为<img src=\"assets/img/gongshi/formula-afb60a3dfc0ab780.png\" class=\"tex\">种；再从本周没选的2个门店里选1个，情况数为<img src=\"assets/img/gongshi/formula-fbe21ccf27467a8d.png\" class=\"tex\">种，则满足条件的情况数=6×2=12种。根据公式：概率<img src=\"assets/img/gongshi/formula-3856d4d2bd50dbfa.png\" class=\"tex\">，则题干所求概率<img src=\"assets/img/gongshi/formula-0110feed9bd2ace6.png\" class=\"tex\">。</p><p>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":69,"pid":"pc6b28bdffd"},{"qid":"16069774","no":6,"type":"数学运算","module":"数量关系","stem":"<p>某公司招聘经理，应聘者需通过笔试和面试各一轮。小杨通过笔试的概率为0.7，面试时他要从5道题中随机抽取1道回答，但5道题中只有1道与他专业相关，如果抽到这道题，他通过面试的概率为0.6，否则为0.4。问他应聘通过的概率在以下哪个范围？</p>","options":[{"k":"A","t":"不到0.2"},{"k":"B","t":"0.2~0.25之间"},{"k":"C","t":"0.25~0.3之间"},{"k":"D","t":"超过0.3"}],"answer":"D","multi":false,"explanation":"<p>根据题意，小杨通过笔试的概率为0.7，通过面试的概率可分类讨论如下：</p><p>①抽到与他专业相关的面试题目且通过：<img src=\"assets/img/gongshi/formula-75b5cb1ced76609b.png\" class=\"tex\">；</p><p>②抽到与他专业不相关的面试题目且通过：<img src=\"assets/img/gongshi/formula-5ff4cb0b2c46e258.png\" class=\"tex\">。</p><p>所以小杨通过面试的概率=0.12+0.32=0.44。</p><p>因此小杨应聘通过的概率=0.7×0.44=0.308&gt;0.3。</p><p>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":70,"pid":"pc6b28bdffd"},{"qid":"16069866","no":7,"type":"数学运算","module":"数量关系","stem":"<p>某电脑设有6位开机密码，且每一位密码都是字母a、b、c、d中的一个。若密码必须包含a、b字母至少各1个，且首尾字母相同，问符合要求的密码有多少种？</p>","options":[{"k":"A","t":"320"},{"k":"B","t":"450"},{"k":"C","t":"570"},{"k":"D","t":"960"}],"answer":"C","multi":false,"explanation":"<p>根据题意，出现至少······，正面考虑较为复杂，可以从反面考虑。</p><p>即：正面情况数=总情况数-反面情况数。</p><p>总情况数即首尾字母相同，中间位置字母任选：</p><p>第一步：确定首尾字母，有a、b、c、d共<img src=\"assets/img/gongshi/formula-1906815443a6b35c.png\" class=\"tex\">种选择；</p><p>第二步：确定中间4个位置，每个位置都可从4个字母中任选，共<img src=\"assets/img/gongshi/formula-f479cc70cf12c10b.png\" class=\"tex\">种选择；</p><p>总情况数=4×256=1024种情况。</p><p>反面情况数可分类讨论：</p><p>根据两集合容斥原理，反面情况数=不含a的情况数+不含b的情况数-既不含a也不含b的情况数（重复计算部分）</p><p>①不含a的情况：即所有位置只有b、c、d共3个字母可供选择。</p><p>第一步：确定首尾字母，有b、c、d共<img src=\"assets/img/gongshi/formula-4a7c070f65c27fee.png\" class=\"tex\">种选择；</p><p>第二步：确定中间4个位置，每个位置都可从3个字母中任选，共<img src=\"assets/img/gongshi/formula-fcd83a6dadb99ff4.png\" class=\"tex\">种选择；</p><p>不含a的情况数=3×81=243种情况；</p><p>②不含b的情况：即所有位置只有a、c、d共3个字母可供选择。</p><p>第一步：确定首尾字母，有a、c、d共<img src=\"assets/img/gongshi/formula-4a7c070f65c27fee.png\" class=\"tex\">种选择；</p><p>第二步：确定中间4个位置，每个位置都可从3个字母中任选，共<img src=\"assets/img/gongshi/formula-fcd83a6dadb99ff4.png\" class=\"tex\">种选择；</p><p>不含b的情况数=3×81=243种情况；</p><p>③既不含a也不含b的情况：即所有位置只有c、d共2个字母可供选择。</p><p>第一步：确定首尾字母，有c、d共<img src=\"assets/img/gongshi/formula-5b361a76737d1ad0.png\" class=\"tex\">种选择；</p><p>第二步：确定中间4个位置，每个位置都可从2个字母中任选，共<img src=\"assets/img/gongshi/formula-a1b60b2a3a6a1efb.png\" class=\"tex\">种选择；</p><p>既不含a也不含b的情况数=2×16=32种情况；</p><p>所以，反面情况数=243+243−32=454种。</p><p>因此，正面情况数=总情况数-反面情况数=1024−454=570种。</p><p>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":71,"pid":"pc6b28bdffd"},{"qid":"16069798","no":8,"type":"数学运算","module":"数量关系","stem":"<p>某农学院在一块正方形试验田中划出4块尽可能大、且彼此相切的等大圆形土地，并计划在灰色、黑色区域分别种植小麦和玉米（如下图所示）。问小麦和玉米的种植面积之比为：</p><p><img src=\"assets/img/timu/19ceb40378f93c3.png\" class=\"fig\" style=\"width:250px;height:249px;\"></p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-da2cc95db9b9b2ee.png\" class=\"tex\"></p>"},{"k":"B","t":"<p>2：1</p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-1fca1cc448a8f96d.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-afe73ff77cd6e385.png\" class=\"tex\"></p>"}],"answer":"A","multi":false,"explanation":"<p>赋值每个圆的半径为1，则正方形边长为4。过AB、AD中点分别作平行于边长的直线EF、GH，相交于O点。因为4个圆大小相等，则把中间灰色区域分成4个面积大小相等的部分MON，那么小麦的种植面积=一个圆的面积+4个MON的面积=正方形AEOG的面积<img src=\"assets/img/gongshi/formula-f431e7c382a95e13.png\" class=\"tex\">。根据圆的面积公式：<img src=\"assets/img/gongshi/formula-e5cf4a73de869f00.png\" class=\"tex\">，可得玉米的种植面积为<img src=\"assets/img/gongshi/formula-9cfacd461b19088a.png\" class=\"tex\">。则小麦和玉米的种植面积之比为<img src=\"assets/img/gongshi/formula-da2cc95db9b9b2ee.png\" class=\"tex\">。</p><p><img src=\"assets/img/timu/19ceb4240ca7d44.png\" class=\"fig\" style=\"width:250px;height:239px;\"></p><p>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":72,"pid":"pc6b28bdffd"},{"qid":"16069802","no":9,"type":"数学运算","module":"数量关系","stem":"<p>一条输电线沿着A地的东北方向（<img src=\"assets/img/gongshi/formula-66d1763c3dc7ea2b.png\" class=\"tex\">）布设，B地、C地均在A地正东方向，距离A地分别为4公里、6公里，D地在C地正北方向2公里处。现从输电线的某处P点分别搭建两条电缆至B、D两地，则这两条电缆长度之和最小为多少公里？</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-20d90da4188a0322.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-72c7ee33aa0b80a8.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-d04f9aba7f8b897b.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-de2483b6639bdd79.png\" class=\"tex\"></p>"}],"answer":"D","multi":false,"explanation":"<p>根据几何最短路径问题的结论，选择点B作输电线的镜像对称点<img src=\"assets/img/gongshi/formula-d8984cb67d738a2b.png\" class=\"tex\">，连接点<img src=\"assets/img/gongshi/formula-d8984cb67d738a2b.png\" class=\"tex\">和点D，并与输电线交于点P。则点P为搭建两条电缆长度之和最小的位置。</p><p><img src=\"assets/img/timu/19ceb46fc035076.png\" class=\"fig\" style=\"width:293px;height:200px;\"></p><p>根据题意可得：<img src=\"assets/img/gongshi/formula-fcba3045fccbe8aa.png\" class=\"tex\">，且<img src=\"assets/img/gongshi/formula-30247767a364da0d.png\" class=\"tex\">，则<img src=\"assets/img/gongshi/formula-ae6d3ae51dc9bb72.png\" class=\"tex\">为等腰直角三角形。因为AB=4公里，故<img src=\"assets/img/gongshi/formula-1d4ab55d2a7f05d6.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-c8d56e262da73d7b.png\" class=\"tex\">。因此<img src=\"assets/img/gongshi/formula-2cd31255461b149c.png\" class=\"tex\">。又因为BC=CD=2公里，且<img src=\"assets/img/gongshi/formula-30b36381f5a501e6.png\" class=\"tex\">，则<img src=\"assets/img/gongshi/formula-ed16f176598b0300.png\" class=\"tex\">为等腰直角三角形。故<img src=\"assets/img/gongshi/formula-ab3fb4118daf3a22.png\" class=\"tex\">公里。且<img src=\"assets/img/gongshi/formula-b89e6804a3e28982.png\" class=\"tex\">，则<img src=\"assets/img/gongshi/formula-73a9599be3dae699.png\" class=\"tex\">，根据勾股定理<img src=\"assets/img/gongshi/formula-512784eec301b6e3.png\" class=\"tex\">公里。</p><p>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":73,"pid":"pc6b28bdffd"},{"qid":"16069892","no":10,"type":"数学运算","module":"数量关系","stem":"<p>某容器下部分是一个圆柱，上部分是一个圆台，圆台底面刚好与圆柱重合。已知圆台上面半径的2倍等于圆台底面半径，圆台的高和圆柱相等。现匀速向容器内注水，3秒装满了圆柱部分的一半，那么还需要多长时间才能装满整个容器（容器壁厚忽略不计）？</p><p><img src=\"assets/img/timu/19ceb690aa03cbb.png\" class=\"fig\" style=\"width:160px;height:200px;\"></p>","options":[{"k":"A","t":"6秒"},{"k":"B","t":"6.5秒"},{"k":"C","t":"7秒"},{"k":"D","t":"7.5秒"}],"answer":"B","multi":false,"explanation":"<p>设圆台上面半径为r，高为h，则圆台下面半径与圆柱半径均为2r，圆柱的高度为h。</p><p>方法一：下方圆柱体积为<img src=\"assets/img/gongshi/formula-66c5651ecffd13b1.png\" class=\"tex\">，将上方圆台母线延长相交于一点（如图所示），所求圆台体积可看做一个大圆锥体积与上方小圆锥体积之差。大圆锥底面为圆台下底面，半径为2r；小圆锥底面为圆台上底面，半径为r，大圆锥与小圆锥相似，底面半径之比为2r：r=2：1，即相似比为2：1，大圆锥与小圆锥高度之比也为2：1，圆台高为h，则大圆锥高为2h，小圆锥高为h。故小圆锥体积<img src=\"assets/img/gongshi/formula-330a569d9b4b5cbc.png\" class=\"tex\">，大圆锥体积<img src=\"assets/img/gongshi/formula-6ef241a2cd785671.png\" class=\"tex\">，圆台体积=大圆锥体积-小圆锥体积<img src=\"assets/img/gongshi/formula-26063b70265f41c1.png\" class=\"tex\">。该容器总体积<img src=\"assets/img/gongshi/formula-da208d4f78391074.png\" class=\"tex\">。目前容器内注水体积为下方圆柱部分的一半，即注水体积<img src=\"assets/img/gongshi/formula-569e4990e2a39e06.png\" class=\"tex\">，注水时间为3秒，注水速度不变，则注水体积与注水时间成正比，设还需注水时间为t秒，则<img src=\"assets/img/gongshi/formula-a3e4cf9fe19791e3.png\" class=\"tex\">，解得t=6.5秒。</p><p><img src=\"assets/img/timu/19ceb7581475ddf.png\" class=\"fig\" style=\"width:197px;height:259px;\"></p><p>方法二：下方圆柱体积为<img src=\"assets/img/gongshi/formula-270ca8122457ac87.png\" class=\"tex\">，上方圆台体积<img src=\"assets/img/gongshi/formula-a04598d8839f7292.png\" class=\"tex\">，该容器总体积<img src=\"assets/img/gongshi/formula-3d4aacfd08cd24cf.png\" class=\"tex\">。目前容器内注水体积为下方圆柱部分的一半，即注水体积<img src=\"assets/img/gongshi/formula-e15eb4f7264b50ab.png\" class=\"tex\">，注水时间为3秒，注水速度不变，则注水体积与注水时间成正比，设还需注水时间为t秒，则<img src=\"assets/img/gongshi/formula-b8743fbc3c89da1e.png\" class=\"tex\">，解得t=6.5秒。</p><p>故正确答案为B。</p><p>粉笔备注：圆台体积公式<img src=\"assets/img/gongshi/formula-b2150d065c94b6de.png\" class=\"tex\"></p><p>R—圆台底面半径</p><p>r—圆台顶面半径</p><p>h—圆台高度</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":74,"pid":"pc6b28bdffd"},{"qid":"16069886","no":1,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</p><p><img src=\"assets/img/timu/19ceb67c12f7e79.png\" class=\"fig\" style=\"width:600px;height:251px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>元素组成相同，但无明显位置规律，也无明显属性规律，考虑数量规律。观察发现，题干图形均存在大面积黑块，且黑块有明显分堆，优先考虑黑白块的部分数。第一组图形中，黑块部分数依次为1、2、3，第二组前两幅图形的黑块部分数依次为1、2，故“？”处图形的黑块部分数应为3，只有B项符合。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":75,"pid":"pc6b28bdffd"},{"qid":"16069776","no":2,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</p><p><img src=\"assets/img/timu/19ceb38b99b1bde.png\" class=\"fig\" style=\"width:600px;height:268px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形封闭面明显，优先考虑面数量。题干图形的面数量均为7，因此“？”处图形的面数量应为7，D项图形的面数量为8，排除。继续观察发现，题干图形内部均由直线和曲线构成，其中全直线面数量依次为5、4、3、2、1，呈递减规律，故“？”处图形的全直线面数量应为0，只有C项符合。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":76,"pid":"pc6b28bdffd"},{"qid":"16069800","no":3,"type":"图形推理","module":"判断推理","stem":"<p>以下哪两个图形交换位置之后，整个图形序列将呈现一定的规律性？</p><p><img src=\"assets/img/timu/19ceb44e429e06e.png\" class=\"fig\" style=\"width:600px;height:133px;\"></p>","options":[{"k":"A","t":"②和③"},{"k":"B","t":"③和④"},{"k":"C","t":"④和⑤"},{"k":"D","t":"⑤和⑥"}],"answer":"D","multi":false,"explanation":"<p>解析一：元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干每幅图形的内部线条均与外框相交，且内部线条与外框的交点数均为3。继续观察发现，图①到图④的3个框上交点每次沿顺时针方向移动一个边，交换图⑤和图⑥后，六个图形交点移动规律连贯，对应D项。<br>解析二：元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干每幅图都是一个六边形被内部线条分割成3个面，其中有且只有一个面与外边框有3条边重合，观察这3条重合边，图①到图④的3条重合边每次沿顺时针方向移动一个边，交换图⑤和图⑥后，六个图形的3条重合边移动规律连贯，对应D项。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":77,"pid":"pc6b28bdffd"},{"qid":"16069767","no":4,"type":"图形推理","module":"判断推理","stem":"<p>以下四个选项中，哪一个是由8个白色、4个黑色正方体组合而成的长方体的外表面展开图？</p><p><img src=\"assets/img/timu/19ceb31d5c2e424.png\" class=\"fig\" style=\"width:500px;height:193px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>本题为空间重构题，可以通过公共边进行判断，由构成直角的两条边为公共边可知，公共边两侧对应的黑白块颜色应相同，逐一分析选项。</p><p><img src=\"assets/img/timu/19ceb335907a8dc.png\" class=\"fig\" style=\"width:500px;height:191px;\"></p><p>A项：所有公共边两侧黑白块颜色均相同；</p><p>B项：公共边两侧黑白块颜色不同；</p><p>C项：公共边两侧黑白块颜色不同；</p><p>D项：公共边两侧黑白块颜色不同。</p><p>因此只有A项是由8个白色、4个黑色正方体组合而成的长方体的外表面展开图。</p><p>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":78,"pid":"pc6b28bdffd"},{"qid":"16069844","no":5,"type":"图形推理","module":"判断推理","stem":"<p>左图为两个正方体组合而成的长方体，则这两个正方体的外表面展开图分别是：</p><p><img src=\"assets/img/timu/19ceb51d74a6a0c.png\" class=\"fig\" style=\"width:600px;height:135px;\"></p>","options":[{"k":"A","t":"①和②"},{"k":"B","t":"③和④"},{"k":"C","t":"①和④"},{"k":"D","t":"②和③"}],"answer":"A","multi":false,"explanation":"<p>将题干两个正方体的面标上字母序号，并在立体图形和外表面展开图的“小正方形”面（面e和面g）中以“小正方形”与外框的公共顶点为起始点，顺时针画边标号，如下图所示：</p><p><img src=\"assets/img/timu/19ceb775986e73e.png\" class=\"fig\" style=\"width:600px;height:135px;\"></p><p>图①中，标出“小正方形”面中对应的边1和边2后发现，二者与题干右侧正方体中面g的边1和边2对应一致，故图①可能是题干右侧正方体的外表面展开图；</p><p>图②中，标出“小正方形”面中对应的边2后发现，该公共边与题干左侧正方体中面e的边2对应一致，故图②可能是题干左侧正方体的外表面展开图；</p><p>图③中，标出“小正方形”面中对应的边1和边2后发现，二者与题干右侧正方体中面g的边1和边2对应不一致，故图③不可能是题干右侧正方体的外表面展开图，且与题干左侧正方体中面e的边2也对应不一致，故图③不可能是题干左侧正方体的外表面展开图；</p><p>图④中，标出“小正方形”面中对应的边1和边2后发现，二者与题干右侧正方体中面g的边1和边2对应不一致，故图④不可能是题干右侧正方体的外表面展开图，且与题干左侧正方体中面e的边2也对应不一致，故图④不可能是题干左侧正方体的外表面展开图。</p><p>综上，两个正方体的外表面展开图可能是①和②，对应A项。</p><p>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":79,"pid":"pc6b28bdffd"},{"qid":"16069973","no":6,"type":"定义判断","module":"判断推理","stem":"<p>分权时序是指政府或组织在权力分配过程中，依据特定逻辑，分阶段、按顺序逐步下放权力的策略，其核心逻辑是通过“时序规划”降低分权风险，确保权力下放与承接能力、管理成熟度相匹配。<br>根据上述定义，下列属于分权时序的是：</p>","options":[{"k":"A","t":"某企业市场部根据产品推广计划安排不同地区的促销活动时间"},{"k":"B","t":"某政府部门在公共设施建设中，根据项目进度和资金安排分阶段推进不同区域的设施建设"},{"k":"C","t":"某公司研发团队在产品研发过程中，根据项目进度安排团队不同成员的工作任务和时间顺序"},{"k":"D","t":"某矿区开展生态修复项目时，地方政府优先赋予矿区环境监管权，但未同步下放排污费征收权"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“政府或组织在权力分配过程中”、“分阶段、按顺序逐步下放权力”。<br>第二步：逐一分析选项。<br>A项：某企业市场部根据产品推广计划安排不同地区的促销活动时间，属于工作时间安排，没有体现权力分配与下放权力，不符合“政府或组织在权力分配过程中”、“分阶段、按顺序逐步下放权力”，不符合定义，排除；<br>B项：某政府部门根据项目进度和资金安排分阶段推进公共设施建设，属于项目建设推进，没有体现权力分配与下放权力，不符合“政府或组织在权力分配过程中”、“分阶段、按顺序逐步下放权力”，不符合定义，排除；<br>C项：某公司研发团队根据项目进度安排成员工作任务和时间顺序，属于工作分工与进度安排，没有体现权力分配与下放权力，不符合“政府或组织在权力分配过程中”、“分阶段、按顺序逐步下放权力”，不符合定义，排除；<br>D项：地方政府优先赋予矿区环境监管权，未同步下放排污费征收权，体现权力分配与下放权力，符合“政府或组织在权力分配过程中”、“分阶段、按顺序逐步下放权力”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":80,"pid":"pc6b28bdffd"},{"qid":"16069992","no":7,"type":"定义判断","module":"判断推理","stem":"<p>人口粘性是以人口迁移惰性与地理空间稳定性为核心特征的社会地理现象，指特定区域内居民因资源依赖、社会交往、文化认同或制度约束等因素，形成对原居地的长期驻留倾向，抑制人口外迁动力，从而维持或强化区域人口规模与结构稳定性。<br>根据上述定义，下列属于人口粘性的是（    ）。</p>","options":[{"k":"A","t":"老刘退休后搬迁至深圳和子女一起生活，但每年清明节都会返乡扫墓"},{"k":"B","t":"在上海打工的赵某十年来一直租住在房租低廉的城中村，虽然日均通勤3小时，但仍不打算迁离"},{"k":"C","t":"山东农户李某每年冬季赴海南种植反季瓜菜，春季返乡务农，虽然每年往返，但多了一份额外收入"},{"k":"D","t":"煤矿工人孙某因国企改制获得矿区住房产权，子女教育依托企业附属学校，尽管薪资偏低仍拒绝南下务工"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“资源依赖、社会交往、文化认同或制度约束”、“对原居地的长期驻留倾向”。<br>第二步：逐一分析选项。<br>A项：老刘退休后搬去深圳，每年清明节返乡扫墓，说明老刘已经搬走、定居外地，只是偶尔回去，不符合“对原居地的长期驻留倾向”，不符合定义，排除；<br>B项：赵某在上海城中村租房，说明赵某并非长期驻留原居地，不符合“对原居地的长期驻留倾向”，不符合定义，排除；<br>C项：李某冬季去海南，春季回山东务农，说明李某并非长期驻留原居地，不符合“对原居地的长期驻留倾向”，不符合定义，排除；<br>D项：孙某有矿区住房产权、子女在企业附属学校上学，薪资低也不南下，说明是对矿区住房产权及子女企业附属学校有资源依赖，符合“资源依赖、社会交往、文化认同或制度约束”，且薪资偏低也拒绝南下，说明确实存在长期驻留倾向，符合“对原居地的长期驻留倾向”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":81,"pid":"pc6b28bdffd"},{"qid":"16069978","no":8,"type":"定义判断","module":"判断推理","stem":"<p>种间互作是一种以跨物种直接或间接影响为核心特征的生态学现象，不同物种通过竞争、捕食、互利共生等关系，在资源利用、空间分配或生理功能上产生动态关联，驱动群落结构演化、物种适应性分化及生态系统功能维持，其作用机制可表现为促进、抑制或协同进化。<br>根据上述定义，下列属于种间互作的是（    ）。</p>","options":[{"k":"A","t":"一西伯利亚狼群中的两只公狼因争夺头狼地位发生争斗，导致群体内部等级重构"},{"k":"B","t":"酸雨导致土壤pH值下降，间接影响蚯蚓与植物根系之间通过养分循环的共生关系"},{"k":"C","t":"旱季来临，持续的干旱导致塞伦盖蒂草原的羚羊与斑马同时向植物茂盛的水源地迁徙"},{"k":"D","t":"兔子感染某类寄生虫后行动迟缓更易被郊狼捕食，郊狼继而成为了寄生虫的新宿主，该类寄生虫由此提高了传播效率"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“跨物种直接或间接影响”、“不同物种”、“竞争、捕食、互利共生等关系”、“资源利用、空间分配或生理功能上产生动态关联”、“驱动群落结构演化、物种适应性分化及生态系统功能维持”。<br>第二步：逐一分析选项。<br>A项：西伯利亚狼群中的两只公狼属于同一物种，不符合“不同物种”，不符合定义，排除；<br>B项：酸雨导致土壤pH值下降，间接影响蚯蚓与植物的共生关系，是外在环境因素对这两个物种的关系产生了影响，并非物种之间的直接或间接相互作用，不符合“跨物种直接或间接影响”、“资源利用、空间分配或生理功能上产生动态关联”、“驱动群落结构演化、物种适应性分化及生态系统功能维持”，不符合定义，排除；<br>C项：羚羊与斑马同时向植物茂盛的水源地迁徙，是受干旱环境影响的被动行为，并非物种之间的直接或间接相互作用，不符合“跨物种直接或间接影响”、“资源利用、空间分配或生理功能上产生动态关联”、“驱动群落结构演化、物种适应性分化及生态系统功能维持”，不符合定义，排除；<br>D项：兔子、寄生虫、郊狼，符合“不同物种”，寄生虫感染兔子使得兔子更易被郊狼捕食，郊狼捕食兔子后成为寄生虫新宿主提升了寄生虫的传播效率，符合“跨物种直接或间接影响”、“竞争、捕食、互利共生等关系”、“资源利用、空间分配或生理功能上产生动态关联”、“驱动群落结构演化、物种适应性分化及生态系统功能维持”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":82,"pid":"pc6b28bdffd"},{"qid":"16069989","no":9,"type":"定义判断","module":"判断推理","stem":"<p>语法惊异是指刻意违反语法规则以触发认知冲突与情感共鸣，在特定语境中制造“预期与现实”的认知落差，从而引发短暂而强烈的惊异体验的语言创新机制。这种体验不但能清除既有认知干扰，又能通过唤起兴趣促进认知重构，最终实现语言表达的戏剧化效果或语义增殖。<br>根据上述定义，下列不属于语法惊异的是（    ）。</p>","options":[{"k":"A","t":"“梦，涂鸦了现实的画布”将“梦”比作人进行涂鸦，带来新奇感受"},{"k":"B","t":"广告文案“好喝到哭，这奶茶！”打破常规语序，强化情感强度，制造消费冲动"},{"k":"C","t":"社交媒体中流行“被幸福”等表达，将“被”强行与抽象名词组合，制造反讽效果"},{"k":"D","t":"“风，温柔了田野”赋予“温柔”动作意味，使风的形象更加生动鲜活，不再是抽象的自然现象"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“刻意违反语法规则”、“以触发认知冲突与情感共鸣”。<br>第二步：逐一分析选项。<br>A项：“梦，涂鸦了现实的画布”将“梦”比作人，使用了拟人的修辞手法，但并未违反语法规则，“梦”是主语，“涂鸦”是谓语，“画布”是宾语，句子整体遵循“主谓宾”的常规语法规则，不符合“刻意违反语法规则”，不符合定义，当选；<br>B项：“好喝到哭，这奶茶！”将主语“这奶茶”后置，违反“主谓宾”的常规语序（常规语序应为“这奶茶好喝到哭！”），强化情感强度，制造消费冲动，符合“刻意违反语法规则”、“以触发认知冲突与情感共鸣”，符合定义，排除；<br>C项：“被幸福”将“被”强行与抽象名词“幸福”组合（“被”通常用于被动句，后接及物动词，如“被爱”，“幸福”是抽象名词，不能作“被”的宾语），制造反讽效果，符合“刻意违反语法规则”、“以触发认知冲突与情感共鸣”，符合定义，排除；<br>D项：“风，温柔了田野”将形容词“温柔”用作动词，带宾语“田野”（违反“形容词不能带宾语”的语法规则），使风的形象更加生动鲜活，符合“刻意违反语法规则”、“以触发认知冲突与情感共鸣”，符合定义，排除。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":83,"pid":"pc6b28bdffd"},{"qid":"16069990","no":10,"type":"定义判断","module":"判断推理","stem":"<p>解构式技能重组是一种主动的学习策略，指学习者为突破复杂技能的学习瓶颈，有意识地将目标技能分解为若干个独立的、可单独训练的核心子模块，然后对这些子模块进行高强度的专项练习，待各模块熟练后，再将其重新整合，最终实现对整体技能的精通。<br>根据上述定义，下列属于解构式技能重组的是（    ）。</p>","options":[{"k":"A","t":"某厨师学徒严格按照菜谱，从食材处理到火候掌握一步步学习制作一道新派融合菜，最终成功复刻了这道菜肴"},{"k":"B","t":"小赵为准备一场重要演讲，将自己以往演讲中反响最好的几个案例和金句进行重新编排和串联，形成了一套全新的演讲稿"},{"k":"C","t":"为提高百米自由泳成绩，某游泳运动员聘请体能师进行为期三个月的核心力量与腿部爆发力专项训练，有效增强划水与打腿效果"},{"k":"D","t":"小高为提升篮球突破能力，认真练习了变向运球、篮下脚步和非惯用手上篮动作，并在对抗训练中流畅组合运用，得分效率大增"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“学习者为突破复杂技能的学习瓶颈”、“将目标技能分解为若干个独立的、可单独训练的核心子模块”、“对这些子模块进行高强度的专项练习”、“各模块熟练后，再将其重新整合”、“最终实现对整体技能的精通”。<br>第二步：逐一分析选项。<br>A项：厨师学徒严格按照菜谱，从食材处理到火候掌握一步步学习，是按流程顺序模仿学习，并非将复杂技能分解、专项训练再整合，不符合“将目标技能分解为若干个独立的、可单独训练的核心子模块”、“对这些子模块进行高强度的专项练习”、“各模块熟练后，再将其重新整合”，不符合定义，排除；<br>B项：小赵只是将以往演讲中反响最好的几个案例和金句重新编排和串联，仅是对内容的重组，并非对演讲技能进行分解、专项训练再整合，不符合“将目标技能分解为若干个独立的、可单独训练的核心子模块”、“对这些子模块进行高强度的专项练习”、“各模块熟练后，再将其重新整合”，不符合定义，排除；<br>C项：游泳运动员进行了核心力量与腿部爆发力的专项训练后，有效增强划水与打腿效果，但未体现两个模块的整合，不符合“各模块熟练后，再将其重新整合”，不符合定义，排除；<br>D项：小高以篮球突破这一整体技能为目标，将其拆解为变向运球、篮下脚步、非惯用手上篮动作3个独立可训练的核心子模块，认真练习后，在对抗训练中流畅组合运用，得分效率大增，符合“学习者为突破复杂技能的学习瓶颈”、“将目标技能分解为若干个独立的、可单独训练的核心子模块”、“对这些子模块进行高强度的专项练习”、“各模块熟练后，再将其重新整合”、“最终实现对整体技能的精通”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":84,"pid":"pc6b28bdffd"},{"qid":"16070003","no":11,"type":"定义判断","module":"判断推理","stem":"<p>资产轻量化重组是一种企业财务与运营策略，指企业为了优化资本结构和聚焦核心业务，将自身拥有的、运营所必需的重资产出售给第三方，同时通过签订长期租赁或服务协议的方式，保留对这些资产的持续使用权，从而将固产转化为运营现金流，实现从“持有资产”向“使用资产”的模式转变。<br>根据上述定义，下列属于资产轻量化重组的是（    ）。</p>","options":[{"k":"A","t":"某连锁酒店集团为快速扩张，放弃自建的模式，转为长期租赁城市核心区现有的商业楼宇，并将其改造为旗下品牌酒店进行运营"},{"k":"B","t":"某制造企业为实现技术升级，将位于市中心的老旧厂房整体出售，并用所得款项在高新产业园建设了一座全新的智能化工厂"},{"k":"C","t":"为改善现金流状况，某航空公司将一批客机出售给一家金融公司，随即又从该公司租回同批客机，继续用于其航线运营"},{"k":"D","t":"某高科技公司为盘活资产，将其为员工提供的宿舍楼整体出售，并随即签订长期包租协议，继续将其作为员工福利"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“将自身拥有的、运营所必需的重资产出售给第三方”、“通过签订长期租赁或服务协议的方式，保留持续使用权”、“将固产转化为运营现金流”。<br>第二步：逐一分析选项。<br>A项：某连锁酒店集团放弃自建的模式，转为长期租赁的方式，并未将重资产出售，不符合“将自身拥有的、运营所必需的重资产出售给第三方”，不符合定义，排除；<br>B项：某制造企业将位于市中心的老旧厂房整体出售，并用所得款项建设了全新的工厂，不符合“通过签订长期租赁或服务协议的方式，保留持续使用权”，不符合定义，排除；<br>C项：为改善现金流状况，某航空公司将一批客机出售给一家金融公司，符合“将自身拥有的、运营所必需的重资产出售给第三方”，随即又从该公司租回同批客机，继续用于其航线运营，符合“通过签订长期租赁或服务协议的方式，保留持续使用权”、“将固产转化为运营现金流”，符合定义，当选；<br>D项：某高科技公司为员工提供的宿舍楼，并不是运营所必需的重资产，不符合“将自身拥有的、运营所必需的重资产出售给第三方”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":85,"pid":"pc6b28bdffd"},{"qid":"16069976","no":12,"type":"定义判断","module":"判断推理","stem":"<p>表现反弹效应是一种心理现象，指个体在某项有明确目标的任务中遭遇失败或挫折后，并未陷入沮丧，而是将该挫折归因于可控的外部因素或自身可修正的具体行为，并由此激发出一股强烈的补偿性动机，在另一项性质不同但领域相关的任务中，表现出远超其通常水准的卓越绩效。<br>根据上述定义，下列属于表现反弹效应的是（    ）。</p>","options":[{"k":"A","t":"小张在模拟考试中因时间分配不当而成绩不佳，他并未气馁，而是立即模拟考场环境重做了一遍试卷，最终取得了高分"},{"k":"B","t":"程序员小许因项目需求频繁变更导致返工，深感烦躁，下班后他通过打篮球的方式发泄了情绪，并发现投篮准确率显著提高"},{"k":"C","t":"推销员小王因准备不充分丢掉一笔大订单后并未灰心，而是立刻找到另一位潜在客户，凭借出色的发挥成功签下了一份价值不菲的合同"},{"k":"D","t":"棋手小庄在正式比赛中因开局策略失误而憾负对手，赛后他立刻登录在线对战平台，在快棋挑战赛中发挥神勇，刷新了个人最高等级分"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“在某项有明确目标的任务中遭遇失败或挫折”、“并未陷入沮丧”、“将该挫折归因于可控的外部因素或自身可修正的具体行为”、“在另一项性质不同但领域相关的任务中”、“远超其通常水准的卓越绩效”。<br>第二步：逐一分析选项。<br>A项：小张因时间分配不当模拟考试失利，重做同一份试卷取得高分，说明前后任务均为完成该份试卷，属于同一项任务，不符合“在另一项性质不同但领域相关的任务中”，不符合定义，排除；<br>B项：程序员小许因项目需求变更返工，下班后打篮球发泄，投篮准确率提高，说明前后任务分别是项目开发与打篮球，领域完全无关，不符合“在另一项性质不同但领域相关的任务中”，不符合定义，排除；<br>C项：推销员小王因准备不足丢了一笔大订单，随即签下另一位客户的大额合同，说明前后任务均为向客户推销并签下订单，仅更换了客户，任务性质完全相同，不符合“在另一项性质不同但领域相关的任务中”，不符合定义，排除；<br>D项：棋手小庄在正式比赛中因开局策略失误憾负，符合“在某项有明确目标的任务中遭遇失败或挫折”，他将失利归因于自己开局准备不足这一可修正问题，符合“并未陷入沮丧”、“将该挫折归因于可控的外部因素或自身可修正的具体行为”，赛后在在线快棋挑战赛中发挥神勇，刷新个人最高等级分，正式慢棋赛事与在线快棋挑战赛均属于棋类竞技领域，但赛事性质不同，符合“在另一项性质不同但领域相关的任务中”、“远超其通常水准的卓越绩效”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":86,"pid":"pc6b28bdffd"},{"qid":"16069994","no":13,"type":"定义判断","module":"判断推理","stem":"<p>梯度循环转化是指根据不同生产环节对物质能量需求的差异，将前一生产过程产生的废弃物或副产物直接作为后一生产过程的核心原材料，通过多个连续的转化链条，依次提取物质价值，实现资源多级、深度循环利用的过程。<br>根据上述定义，下列属于梯度循环转化的是（    ）。</p>","options":[{"k":"A","t":"某生态农场在水稻田中同时套养鱼类和鸭子，鱼和鸭能够捕虫肥田，而水稻则为鱼和鸭提供遮阴避敌的场所"},{"k":"B","t":"某酒厂将酿酒剩下的窖糟用于栽培食用菌，栽培后的菌渣接着用于养殖蚯蚓，最终将蚓粪作为有机肥用于酿酒高粱的种植"},{"k":"C","t":"某化工厂在生产硫酸的过程中，利用反应释放的高温余热进行蒸汽发电，并收集尾气中的二氧化硫用于制造另一种精细化工产品"},{"k":"D","t":"某林场在春夏季节利用林间空地种植草本药材，秋季采摘药材后，将枯枝落叶粉碎发酵，为冬季温室橱内的花卉提供基肥和热量"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“根据不同生产环节对物质能量需求的差异”、“前一生产过程产生的废弃物或副产物直接作为后一生产过程的核心原材料”、“通过多个连续的转化链条”、“依次提取物质价值，实现资源多级、深度循环利用”。<br>第二步：逐一分析选项。<br>A项：某生态农场在水稻田中同时套养鱼类和鸭子，鱼和鸭捕虫肥田，水稻为鱼和鸭提供遮阴避敌场所，“同时套养”说明三者是同时存在的，不存在“多个连续的转化链条”，也没有“前一生产过程产生的废弃物或副产物直接作为后一生产过程的核心原材料”，不符合定义，排除；<br>B项：某酒厂将酿酒剩下的窖糟用于栽培食用菌，栽培后的菌渣接着用于养殖蚯蚓，最终将蚓粪作为有机肥用于酿酒高粱的种植，窖糟、菌渣、蚓粪依次作为后一生产环节的核心原材料，形成连续转化链条，符合“前一生产过程产生的废弃物或副产物直接作为后一生产过程的核心原材料”、“通过多个连续的转化链条”、“依次提取物质价值，实现资源多级、深度循环利用”，符合定义，当选；<br>C项：某化工厂在生产硫酸的过程中，利用反应释放的高温余热进行蒸汽发电，并收集尾气中的二氧化硫用于制造另一种精细化工产品，余热属于能源而非“废弃物或副产物”，并且没有作为“前一生产过程产生的废弃物或副产物直接作为后一生产过程的核心原材料”、只是用于另一种化工产品的生产，不符合定义，排除；<br>D项：某林场在春夏季节利用林间空地种植草本药材，秋季采摘药材后，将枯枝落叶粉碎发酵，枯枝落叶并非药材种植环节的“核心副产物”，并且只是不同的季节做不同的事情，没有“多个连续的转化链条”，不符合“通过多个连续的转化链条”、“依次提取物质价值，实现资源多级、深度循环利用”，不符合定义，排除。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":87,"pid":"pc6b28bdffd"},{"qid":"16069983","no":14,"type":"定义判断","module":"判断推理","stem":"<p>差错导向是指个体对错误本身以及应对错误方式的主观看法，差错掩盖导向指个体出于自我形象或短期利益的维护而产生对负面评价或惩罚的恐惧，倾向于通过否认、隐藏或推卸责任等方式掩盖错误，避免他人察觉。差错学习导向指个体以开放的心态将错误视为改进机会，主动反思错误原因、总结经验并积极调整行为以实现自我提升。<br>根据上述定义，下列属于差错学习导向的是（    ）。</p>","options":[{"k":"A","t":"某餐厅食材变质导致多名顾客食物中毒，餐厅经理把原因归结为“厨师与采购沟通不足，导致食材新鲜度不达标”"},{"k":"B","t":"某三甲医院建立“无惩罚差错上报系统”，医护人员可匿名分享失误案例以供全院学习"},{"k":"C","t":"小赵在考试失利后大量刷题，但拒绝分析错题原因导致相同知识点反复出错"},{"k":"D","t":"某企业宣称“已从用户数据泄露事件中汲取教训”，但并未升级安全系统"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>差错导向：“个体对错误本身以及应对错误方式”、“主观看法”；<br>差错掩盖导向：“个体出于自我形象或短期利益的维护”、“对负面评价或惩罚的恐惧”、“通过否认、隐藏或推卸责任等方式掩盖错误”、“避免他人察觉”；<br>差错学习导向：“个体以开放的心态将错误视为改进机会”、“主动反思并积极调整行为”、“以实现自我提升”。<br>第二步：逐一分析选项。<br>A项：餐厅经理将中毒事件简单归咎于沟通不足，未主动反思问题根源、未总结经验、未采取改进措施，不符合“主动反思并积极调整行为”、“以实现自我提升”，不符合“差错学习导向”定义，排除；<br>B项：医院建立无惩罚差错上报系统，医护人员可匿名分享失误案例以供学习，符合“个体以开放的心态将错误视为改进机会”、“主动反思并积极调整行为”、“以实现自我提升”，符合“差错学习导向”定义，当选；<br>C项：小赵拒绝分析错题原因，不符合“主动反思并积极调整行为”，不符合“差错学习导向”定义，排除；<br>D项：企业未升级安全系统，不符合“主动反思并积极调整行为”，不符合“差错学习导向”定义，排除。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":88,"pid":"pc6b28bdffd"},{"qid":"16069977","no":15,"type":"定义判断","module":"判断推理","stem":"<p>推理句是基于已知信息、知识或前提，通过逻辑推导得出结论的语句，属于逻辑思维在语言中的体现，它凭借合理的推理规则，从给定条件推导出可能性或必然性的结果，其结论的成立依赖于前提的真实性及逻辑有效性，核心功能在于论证观点或预测可能性，因果句是指通过显性逻辑连接词或隐性语义关联，明确表达一个事件导致另一个事件的发生，前后分句间存在客观的事理关联，其核心功能在于解释现象成因或行为动机。<br>根据上述定义，下列属于因果句的有几项？<br>①因为合同明确约定违约条款，所以甲方就应承担赔偿责任<br>②因为玉米价格持续下跌，所以农民明年可能改种大豆<br>③因为服务器散热系统故障，所以网站瘫痪3小时<br>④因为听到外面雨声很大，所以地面肯定湿了</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>推理句：“基于已知信息、知识或前提”、“通过逻辑推导得出结论的语句”、“它凭借合理的推理规则，从给定条件推导出可能性或必然性的结果”、“其结论的成立依赖于前提的真实性及逻辑有效性，核心功能在于论证观点或预测可能性”；<br>因果句：“通过显性逻辑连接词或隐性语义关联，明确表达一个事件导致另一个事件的发生”、“前后分句间存在客观的事理关联”、“其核心功能在于解释现象成因或行为动机”。<br>第二步：逐一进行分析。<br>①因为合同明确约定违约条款，所以甲方就应承担赔偿责任，“就应”表示“应该”出现某个结果，符合“它凭借合理的推理规则，从给定条件推导出可能性或必然性的结果”，属于推理句，不符合“明确表达一个事件导致另一个事件的发生”，也不符合“前后分句间存在客观的事理关联”，符合推理句定义，不符合因果句定义；<br>②因为玉米价格持续下跌，所以农民明年可能改种大豆，是基于经验的预测，符合“它凭借合理的推理规则，从给定条件推导出可能性或必然性的结果”、“其结论的成立依赖于前提的真实性及逻辑有效性，核心功能在于论证观点或预测可能性”，符合推理句定义，不符合因果句定义；<br>③因为服务器散热系统故障，所以网站瘫痪3小时，“服务器散热系统故障”直接导致“网站瘫痪3小时”的发生，符合“通过显性逻辑连接词或隐性语义关联，明确表达一个事件导致另一个事件的发生”、“前后分句间存在客观的事理关联”、“其核心功能在于解释现象成因或行为动机”，符合因果句定义；<br>④因为听到外面雨声很大，所以地面肯定湿了，是基于经验的预测，符合“它凭借合理的推理规则，从给定条件推导出可能性或必然性的结果”、“其结论的成立依赖于前提的真实性及逻辑有效性，核心功能在于论证观点或预测可能性”，符合推理句定义，不符合因果句定义。<br>综上，属于因果句的只有③，共1项。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":89,"pid":"pc6b28bdffd"},{"qid":"16069769","no":16,"type":"类比推理","module":"判断推理","stem":"<p>江山：画卷</p>","options":[{"k":"A","t":"琴弦：心声"},{"k":"B","t":"节气：农事"},{"k":"C","t":"火药：军事"},{"k":"D","t":"春雨：甘露"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>江山可以被比喻为画卷，二者为比喻象征义。<br>第二步：判断选项词语间逻辑关系。<br>A项：琴弦是传递心声的工具，二者不是比喻象征义，与题干逻辑关系不一致，排除；<br>B项：农事活动依据节气，二者为依据对应关系，与题干逻辑关系不一致，排除；<br>C项：火药可用于军事领域，二者为应用领域对应关系，与题干逻辑关系不一致，排除；<br>D项：春雨可以被比喻为甘露，二者为比喻象征义，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":90,"pid":"pc6b28bdffd"},{"qid":"16069772","no":17,"type":"类比推理","module":"判断推理","stem":"<p>直径：最长弦</p>","options":[{"k":"A","t":"半圆：半周长"},{"k":"B","t":"正方形：菱形"},{"k":"C","t":"公里：千米"},{"k":"D","t":"梯形：长方形"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>弦是圆上任意两点连起来的线段，连接圆上两点并通过圆心的线段是圆中的最长弦，也称直径，二者为全同关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：半圆是圆的一半，是平面图形，半周长是闭合几何图形周长的一半，是长度，二者无明显逻辑关系，与题干逻辑关系不一致，排除；<br>B项：菱形是有一组邻边长度相等的平行四边形，正方形是一种特殊的菱形，二者为种属关系，与题干逻辑关系不一致，排除；<br>C项：千米是长度计量单位，俗称公里，二者为全同关系，与题干逻辑关系一致，当选；<br>D项：梯形与长方形是两种不同的平面图形，二者为并列关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":91,"pid":"pc6b28bdffd"},{"qid":"16069764","no":18,"type":"类比推理","module":"判断推理","stem":"<p>输液泵：病房：精准给药</p>","options":[{"k":"A","t":"雷达站：机场：情报传输"},{"k":"B","t":"变压器：电网：电压调节"},{"k":"C","t":"消防栓：街道：应急供水"},{"k":"D","t":"服务器：硬盘：数据存储"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>输液泵是作用于输液导管以控制输液速度、严格控制输液量和药量的机械或电子装置，输液泵可在病房内使用，具有精准给药的功能，前两词是事物与地点的对应关系，第一词与第三词是功能的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：雷达站可放置在机场内，但其作用是通过探测来保障飞行安全和进行空中交通管制，并非传输情报，第一词与第三词并非功能的对应关系，与题干逻辑关系不一致，排除；<br>B项：变压器是电网中不可或缺的核心设备，前两词是组成关系，与题干逻辑关系不一致，排除；<br>C项：消防栓可放在街道中，且消防栓在特定条件下，具有应急供水的功能，前两词是事物与地点的对应关系，第一词与第三词是功能的对应关系，与题干逻辑关系一致，当选；<br>D项：服务器是在网络环境中提供计算能力并运行软件应用程序的特定IT设备，硬盘是服务器的重要组成部分，前两词是组成关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":92,"pid":"pc6b28bdffd"},{"qid":"16069805","no":19,"type":"类比推理","module":"判断推理","stem":"<p>原料采购：模具设计：成品出厂</p>","options":[{"k":"A","t":"市场调研：产品开发：用户反馈"},{"k":"B","t":"土地审批：建筑设计：房屋交付"},{"k":"C","t":"货物装载：运输规划：仓储管理"},{"k":"D","t":"原型测试：功能优化：专利申报"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>原料采购、模具设计、成品出厂是先后顺序的对应关系，且成品出厂是最终目的。<br>第二步：判断选项词语间逻辑关系。<br>A项：市场调研、产品开发、用户反馈是先后顺序的对应关系，但用户反馈不是最终目的，与题干逻辑关系不一致，排除；<br>B项：土地审批、建筑设计、房屋交付是先后顺序的对应关系，且房屋交付是最终目的，与题干逻辑关系一致，当选；<br>C项：运输规划应在货物装载之前，与题干逻辑关系不一致，排除；<br>D项：功能优化与专利申报时间先后顺序不明确，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":93,"pid":"pc6b28bdffd"},{"qid":"16069773","no":20,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 轨道 相当于 候鸟 对于 （    ）</p>","options":[{"k":"A","t":"卫星；迁徙路线"},{"k":"B","t":"车道；大雁"},{"k":"C","t":"汽车；湿地公园"},{"k":"D","t":"马路；丹顶鹤"}],"answer":"A","multi":false,"explanation":"<p>逐一代入选项。<br>A项：卫星沿着轨道运行，二者是主体与运动轨迹的对应关系；候鸟沿着迁徙路线飞行，二者是主体与运动轨迹的对应关系，前后逻辑关系一致，当选；<br>B项：车道和轨道是两种不同的道路设施，二者是并列关系；大雁是一种候鸟，二者是种属关系，前后逻辑关系不一致，排除；<br>C项：某些特殊的轨道汽车可以在轨道上行驶，二者是主体与运动轨迹的对应关系；湿地公园是候鸟的栖息地，二者是地点的对应关系，前后逻辑关系不一致，排除；<br>D项：马路和轨道是两种不同的道路设施，二者是并列关系；丹顶鹤是一种候鸟，二者是种属关系，前后逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":94,"pid":"pc6b28bdffd"},{"qid":"16069794","no":21,"type":"逻辑判断","module":"判断推理","stem":"<p>某大学研发的B系列首颗卫星B-1正常在轨运行时间达到了其设计寿命。但是，第二批3颗B系列卫星（B-2/3/4）仅运行2个月便坠入大气层，远低于其设计寿命。对于B系列卫星在轨寿命短的原因，有研究人员认为B-1发射于2021年，整体处于太阳活动周的上升初期，空间天气水平相对较低；而B-2/3/4发射于2024年，其运行期间处于太阳活动高年，空间天气急剧增强，导致B系列卫星寿命缩短。但也有科学家认为，低轨大气密度大幅增加引发了B-2/3/4卫星的加速陨落。<br>以下哪项如果为真，最能质疑上述科学家的观点？</p>","options":[{"k":"A","t":"空间天气的急剧增强会导致低轨大气密度大幅度增加"},{"k":"B","t":"低轨大气密度增加会对卫星产生阻力，使卫星轨道高度衰减"},{"k":"C","t":"太阳活动在上升期、峰值期和下降期的太阳辐射指数不同"},{"k":"D","t":"低轨大气密度受到地磁活动和地球自转、公转等因素影响"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：低轨大气密度大幅增加引发了B-2/3/4卫星的加速陨落。<br>论据：无。<br>本题只有论点没有论据，削弱优先考虑削弱论点，即说明卫星的加速陨落并非由低轨大气密度大幅增加导致的。<br>第二步：逐一分析选项。<br>A项：该项说的是空间天气的急剧增强会导致低轨大气密度大幅度增加，即导致B-2/3/4卫星加速陨落的根本原因是空间天气的急剧增强，而非低轨大气密度大幅增加，削弱论点，可以削弱，当选；<br>B项：该项说的是低轨大气密度增加会对卫星产生阻力，使卫星轨道高度衰减，解释了低轨大气密度增加如何导致卫星加速陨落，为加强项，无法削弱，排除；<br>C项：该项说的是太阳活动在不同时期的太阳辐射指数不同，与论点讨论的低轨大气密度大幅增加是否会导致卫星加速陨落无关，为无关项，无法削弱，排除；<br>D项：该项说的是低轨大气密度受到地磁活动和地球自转、公转等因素影响，讨论的是影响低轨大气密度的原因，与论点讨论的低轨大气密度大幅增加是否会导致卫星加速陨落无关，为无关项，无法削弱，排除。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":95,"pid":"pc6b28bdffd"},{"qid":"16069810","no":22,"type":"逻辑判断","module":"判断推理","stem":"<p>一项随机对照研究以某地区90余名36~66岁的肥胖人群作为研究对象，实验组每天早餐前喝220克酸奶，对照组喝相同量的牛奶。该实验持续24周，结果发现，与对照组相比，实验组受试者的身体脂肪平均减少了2.26公斤。研究者认为，喝酸奶可以降低体脂率。<br>以下哪项如果为真，最能削弱题干中研究者的结论？</p>","options":[{"k":"A","t":"市场上的许多酸奶产品添加了糖分以提升口感，但也增加了热量摄入"},{"k":"B","t":"实验期间除规律饮食外，实验组有人每天保持了一定强度的有氧锻炼"},{"k":"C","t":"酸奶富含钙质及蛋白质等营养成分，餐前半小时喝酸奶可减轻饥饿感"},{"k":"D","t":"酸奶中的益生菌对于改善消化功能有显著效果，有助于身体新陈代谢"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：喝酸奶可以降低体脂率。<br>论据：一项随机对照研究以某地区90余名36~66岁的肥胖人群作为研究对象，实验组每天早餐前喝220克酸奶，对照组喝相同量的牛奶。该实验持续24周，结果发现，与对照组相比，实验组受试者的身体脂肪平均减少了2.26公斤。<br>本题论点说的是“喝酸奶”可以“降低体脂率”，论据通过实验证明“喝酸奶”可以“减少身体脂肪”，二者话题一致，削弱可以考虑削弱论点，且论点中存在因果关系，削弱还可以考虑他因削弱和因果倒置。<br>第二步：逐一分析选项。<br>A项：选项指出市场上的许多酸奶因添加糖分会增加热量摄入，但不清楚实验中所选酸奶的糖分情况，且并未直接削弱实验组喝酸奶可以降低体脂率的结论，无法削弱，排除；<br>B项：选项指出实验组除规律饮食外，部分人每天还保持了一定强度的有氧锻炼，说明实验组的这部分人也可能是通过有氧锻炼而降低了体脂率，他因削弱，可以削弱，当选；<br>C项：选项指出在餐前喝酸奶可以减轻饥饿感，解释了为什么喝酸奶可以降低体脂率，为加强项，无法削弱，排除；<br>D项：选项指出酸奶有助于改善消化功能和身体的新陈代谢，解释了为什么喝酸奶可以降低体脂率，为加强项，无法削弱，排除。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":96,"pid":"pc6b28bdffd"},{"qid":"16069861","no":23,"type":"逻辑判断","module":"判断推理","stem":"<p>冻雨是冬季常见的灾害性天气之一，它落地凝结成冰，给生产生活带来不小威胁。Z地区冻雨分布呈现“西部多、东部少，中部多、南北少”的鲜明特点。对于该地区冻雨分布的特点，有气象学家认为，这与当地地形有关。Z地区的西部、中部分布着大片高海拔的山区，而东部、南北部则分布着低海拔的河谷和平缓地带。高海拔的山区气温更低，为冻雨形成提供了充分的温度条件；而在低海拔的河谷和平缓地带冻雨出现概率低、范围小。因此有气象学家认为，Z地区冻雨分布特点是由当地的地形决定的。<br>以下哪项如果为真，最能削弱上述论证？</p>","options":[{"k":"A","t":"受大气环流及地形等影响，Z地区气候多样且不稳定，灾害性天气种类较多，干旱、凌冻、冰雹等频度大"},{"k":"B","t":"除了地势西高东低外，Z地区还有大面积的丘陵地带，通过地形抬升作用促进了水汽的积聚和冷却，从而增加了冻雨发生的可能性"},{"k":"C","t":"气温低和降水是形成冻雨的条件，雨滴在下降过程中以过冷水滴的形式存在，这样当它们到达地面时，就出现了冻结的情况，即冻雨"},{"k":"D","t":"冬季，来自北方的冷气团与来自东南的暖湿气流在Z地区交汇，形成难以消散的准静止锋，它与地形共同作用形成了当地冻雨分布的特点"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：Z地区冻雨分布特点是由当地的地形决定的。<br>论据：Z地区冻雨分布呈现“西部多、东部少，中部多、南北少”的鲜明特点。Z地区的西部、中部分布着大片高海拔的山区，而东部、南北部则分布着低海拔的河谷和平缓地带。高海拔的山区气温更低，为冻雨形成提供了充分的温度条件；而在低海拔的河谷和平缓地带冻雨出现概率低、范围小。<br>本题论点和论据均围绕Z地区冻雨分布特点与地形的关系展开，话题一致，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项指出Z地区受大气环流及地形等影响，气候多样且不稳定，灾害性天气种类较多，但没有涉及这些因素对冻雨分布特点的具体影响，与论点讨论的冻雨分布特点是否由地形决定无关，为无关项，无法削弱，排除；<br>B项：该项指出Z地区的丘陵地带通过地形抬升作用增加了冻雨发生的可能性，强调了地形对冻雨分布的促进作用，可以加强，无法削弱，排除；<br>C项：该项指出气温低与冻雨的形成有关，肯定了论据“高海拔的山区气温更低，为冻雨形成提供了充分的温度条件”，可以加强，无法削弱，排除；<br>D项：该项指出冬季来自北方的冷气团与来自东南的暖湿气流在Z地区交汇形成难以消散的准静止锋，是准静止锋与地形共同作用形成了当地冻雨分布的特点，说明Z地区冻雨分布特点并非仅由地形决定，直接削弱了论点，可以削弱，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":97,"pid":"pc6b28bdffd"},{"qid":"16069781","no":24,"type":"逻辑判断","module":"判断推理","stem":"<p>继黄金、白银价格大幅拉涨后，近日期货市场上铂金价格也出现了上涨。作为有色金属，铂、钯等铂族金属可吸收氢气，是汽车尾气催化剂以及氢能等新兴应用场景的关键原材料。有专家认为，此轮铂金行情看涨并非短期情绪驱动，铂金价格将持续走高。<br>以下除哪一项外，均能支持上述专家的观点？</p>","options":[{"k":"A","t":"由于国际市场的需要，未来燃油汽车产业和清洁能源行业对铂金的需求会持续扩大"},{"k":"B","t":"在美元信用走弱的趋势下，交易市场基于稳定预期，会将投资目光转向黄金、白银、铂金等贵金属"},{"k":"C","t":"铂金具有化学稳定性、催化活性和生物相容性，一直以来被广泛应用于航空航天、生物医药等现代高科技产业"},{"k":"D","t":"N国拥有全球70%以上铂金产量，但该国近期面临电力短缺、矿体老化和运营成本上升等情况，导致全球铂金供应不足进一步加剧"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：此轮铂金行情看涨并非短期情绪驱动，铂金价格将持续走高。<br>论据：近日期货市场上铂金价格也出现了上涨。作为有色金属，铂、钯等铂族金属可吸收氢气，是汽车尾气催化剂以及氢能等新兴应用场景的关键原材料。<br>本题论点与论据都在说铂族金属是新兴应用场景的关键原材料，所以后续价格会持续走高，论点和论据话题一致，加强优先考虑补充论据，即解释原因或举例子，且本题为选非题，将可以加强的选项排除即可。<br>第二步：逐一分析选项。<br>A项：该项讨论的是燃油汽车产业和清洁能源行业对铂金的需求会持续扩大，而需求扩大会带来铂金价格的持续走高，补充论据，可以加强，排除；<br>B项：该项讨论的是美元信用走弱，使得资金流向黄金、白银、铂金等贵金属，资金流入铂族金属时会增加铂族金属的需求，而需求增加会带来铂金价格的持续走高，补充论据，可以加强，排除；<br>C项：该项讨论的是铂金因化学稳定性、催化活性等，一直被广泛应用于航空航天、生物医药等高科技产业，只能表明其用途广泛，并未提到其未来需求增加或供给减少，不能证明其价格是否会持续走高，为不明确项，无法加强，当选；<br>D项：该项讨论的是N国铂金产量占全球70%以上，但其面临电力短缺、矿体老化、运营成本上升等情况导致全球铂金供应不足加剧，说明铂金供给减少，而供给减少会带来铂金价格的持续走高，补充论据，可以加强，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":98,"pid":"pc6b28bdffd"},{"qid":"16069788","no":25,"type":"逻辑判断","module":"判断推理","stem":"<p>S岛位于太平洋，考古证据表明，S岛上的P族人在政治上并没有统一，因此学界对于岛上数百座石像是否由一个首领协调建造观点不一。岛上只有一个提供石像所用火山岩的采石场，近期研究人员使用无人机和高科技测绘设备，创建了采石场的首张三维地图，其中包含大量未完成的石像。研究人员发现，采石场被划分为30个工作区，每个区域似乎都是独立的。研究人员据此认为，S岛上的石像是由许多不同的部落制作的。<br>以下哪项如果为真，最能支持上述结论?</p>","options":[{"k":"A","t":"研究中发现，未完成的石像在采石场的各个工作区中均有分布，且石像的完成进度不同"},{"k":"B","t":"在与P族人同时代其他地区的部落中，也有很多部落没有统一的首领，处在去中心化的阶段"},{"k":"C","t":"据史料记载，S岛上曾经出现过多个部落共存的局面，各部落之间还会爆发不同规模的领地冲突"},{"k":"D","t":"研究人员在S岛上找到了426个代表不同完成阶段的石像，发现它们采用了不同的雕刻技术，特征也不一样"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：S岛上的石像是由许多不同的部落制作的。<br>论据：岛上只有一个提供石像所用火山岩的采石场，近期研究人员使用无人机和高科技测绘设备，创建了采石场的首张三维地图，其中包含大量未完成的石像。研究人员发现，采石场被划分为30个工作区，每个区域似乎都是独立的。<br>本题论点在讨论“石像”和“不同部落”，论据在讨论“石像”和“独立区域”，其中“不同部落”和“独立区域”关系密切，所以论点和论据二者话题一致，加强考虑补充论据。<br>第二步：逐一分析选项。<br>A项：选项说的是未完成的石像在采石场的各个工作区中均有分布，论点讨论的是S岛上的石像是由谁制作的，二者话题不一致，不能加强，排除；<br>B项：选项说的是与P族人同时代其他地区的部落首领的情况，论点讨论的是S岛上的石像是由谁制作的，二者话题不一致，不能加强，排除；<br>C项：选项说的是S岛多个部落共存的情况，论点讨论的是S岛上的石像是由谁制作的，二者话题不一致，不能加强，排除；<br>D项：选项说的是426个石像采用了不同的雕刻技术，特征也不一样，补充论据，说明S岛上的石像的确是由许多不同的部落制作的，可以加强，当选。<br>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":99,"pid":"pc6b28bdffd"},{"qid":"16069789","no":26,"type":"逻辑判断","module":"判断推理","stem":"<p>某干旱地区近年来大力推广高效节水灌溉技术，通过精准滴灌系统替代传统的漫灌方式，使单位面积农田的灌溉用水量平均降低了40%。然而，该地区的年度水资源监测报告显示，农业灌溉用水总量不仅没有如预期般下降，反而比推广节水技术前增长了约15%。<br>以下哪项如果为真，最能解释上述看似矛盾的现象？</p>","options":[{"k":"A","t":"节水灌溉系统的初期安装和设备维护需要投入大量资金，这导致部分农户的生产成本有所上升"},{"k":"B","t":"该地区在推广节水技术的同时，也对地下水开采进行了严格限制，农户转而使用价格更高的地表水"},{"k":"C","t":"灌溉效率的提升大幅降低了单位水量的边际成本，农户因此显著扩大了耕地面积并改种了高需水作物"},{"k":"D","t":"气象监测数据显示，该地区在过去一年中遭遇了罕见的持续高温天气，土壤水分的自然蒸发量显著增加"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出题干矛盾。<br>某干旱地区推广高效节水灌溉技术，单位面积农田灌溉用水量平均降低40%，但农业灌溉用水总量不仅未下降，反而较推广前增长约15%。<br>第二步：逐一分析选项。<br>A项：指出节水灌溉系统的安装和维护使农户生产成本上升，生产成本与农业灌溉用水总量无关，无法解释题干矛盾，排除；<br>B项：指出农户用水从地下水转为地表水，仅改变水源类型，不影响农业灌溉用水的总量，无法解释题干矛盾，排除；<br>C项：指出灌溉效率的提升大幅降低了单位水量的边际成本，农户因此扩大耕地面积且改种高需水作物，解释了虽然单位面积用水量降低了，但由于种植面积扩大和作物需水量增加，导致农业灌溉用水总量反而增长，可以解释题干矛盾，当选；<br>D项：指出持续高温天气使土壤水分蒸发量显著增加，但不明确蒸发量增加是否会导致农业灌溉用水总量增长，无法解释题干矛盾，排除。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":100,"pid":"pc6b28bdffd"},{"qid":"16069793","no":27,"type":"逻辑判断","module":"判断推理","stem":"<p>近期的一项研究发现，氢排放会间接加剧全球变暖，1990年至2020年累积的氢排放为工业化后的全球平均气温上升“贡献”了0.02摄氏度。氢气间接加剧全球变暖的主要原因是它会消耗大气中能够分解温室气体甲烷的天然净化物质，大气中的氢气越多，这类天然净化物质就越少，从而延长甲烷在大气中的留存时间，加剧升温。此外，另有研究发现，近三十年人类活动在整体规模、强度与对全球影响范围上显著增强。由此可见，人类活动加剧了全球变暖。<br>上述论证的成立，必须基于以下哪一前提？</p>","options":[{"k":"A","t":"人类活动排放的大量二氧化碳是推动全球变暖的元凶"},{"k":"B","t":"1990年至2020年间，全球氢气排放量的增加主要由于人类活动"},{"k":"C","t":"氢气与这类天然净化物质的反应会生成臭氧、水蒸气等温室气体"},{"k":"D","t":"氢气排放会对人类的工业、农业等活动产生直接或间接不利影响"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：人类活动加剧了全球变暖。<br>论据：氢排放会间接加剧全球变暖，1990年至2020年累积的氢排放为工业化后的全球平均气温上升“贡献”了0.02摄氏度。氢气间接加剧全球变暖的主要原因是它会消耗大气中能够分解温室气体甲烷的天然净化物质，大气中的氢气越多，这类天然净化物质就越少，从而延长甲烷在大气中的留存时间，加剧升温。此外，另有研究发现，近三十年人类活动在整体规模、强度与对全球影响范围上显著增强。<br>本题论点讨论的是人类活动加剧了全球变暖，论据讨论的是氢排放加剧全球变暖，且近三十年人类活动增强。论点和论据有话题不一致的地方，加强可考虑搭桥，即建立“人类活动”与“氢排放”之间的联系。<br>第二步：逐一分析选项。<br>A项：该项说人类活动排放的大量二氧化碳是推动全球变暖的元凶，补充论据说明人类活动加剧了全球变暖，可以加强，保留；<br>B项：该项说1990年至2020年间（即近三十年），全球氢气排放量的增加主要由于人类活动，建立了“人类活动”与“氢排放”之间的联系，搭桥项，可以加强，保留；<br>C项：该项说氢气会通过反应生成温室气体，但没有提及人类活动，无法说明是否是人类活动加剧了全球变暖，话题不一致，无法加强，排除；<br>D项：该项说氢气排放会对人类活动产生影响，没有提及全球变暖，与论点讨论的人类活动加剧全球变暖话题不一致，无法加强，排除。<br>对比A、B两项，B项搭桥的加强力度大于A项补充论据，当选。<br>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":101,"pid":"pc6b28bdffd"},{"qid":"16069791","no":28,"type":"逻辑判断","module":"判断推理","stem":"<p>在近期的古生物学研究中，科学家通过对一种巨型食肉恐龙的化石进行同位素分析，发现其骨骼样本中的氧-18同位素比例与同时代的鳄类化石高度一致，而与陆生恐龙的样本存在显著差异，这一发现表明，该恐龙长期生活在水生或半水生环境中，因此研究团队得出结论，这种史前巨兽很可能是一种以鱼类为主要食物来源的捕食者。<br>上述论证的成立，必须基于以下哪一前提？</p>","options":[{"k":"A","t":"长期生活在水生或半水生环境中的大型食肉动物通常以鱼类为食"},{"k":"B","t":"该恐龙的牙齿形态呈现出圆锥形，这与现代以鱼为食的鳄类相似"},{"k":"C","t":"化石的同位素特征表明，同时代的陆生恐龙以当时的陆地植物为食"},{"k":"D","t":"化石记录显示，该恐龙的栖息地在远古时期曾是广阔的淡水河流系统"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：这种史前巨兽（巨型食肉恐龙）很可能是一种以鱼类为主要食物来源的捕食者。<br>论据：科学家通过对一种巨型食肉恐龙的化石进行同位素分析，发现其骨骼样本中的氧-18同位素比例与同时代的鳄类化石高度一致，而与陆生恐龙的样本存在显著差异，这一发现表明，该恐龙长期生活在水生或半水生环境中。<br>本题论点在讨论“巨型食肉恐龙以鱼类为主要食物来源”，论据在讨论“巨型食肉恐龙长期生活在水生或半水生环境中”，话题不一致，且提问方式为“前提”，加强优先考虑搭桥，可直接寻找同时包含“长期生活在水生或半水生环境中”和“以鱼类为主要食物来源”的选项。<br>第二步：逐一分析选项。<br>A项：该项指出长期生活在水生或半水生环境中的大型食肉动物通常以鱼类为食，即在“长期生活在水生或半水生环境中”和“以鱼类为主要食物来源”之间建立联系，为搭桥项，可以加强，当选；<br>B项：该项指出该恐龙的牙齿形态与现代以鱼为食的鳄类相似，说明该恐龙有可能和鳄类一样也以鱼类为食，类比加强，但不是上述论证成立的前提，排除；<br>C项：该项讨论的是同时代的陆生恐龙，而论点讨论的是这种巨型食肉恐龙，主体不一致，为无关项，无法加强，排除；<br>D项：该项指出该恐龙的栖息地在远古时期曾是广阔的淡水河流系统，栖息地环境是河流系统不代表其就以鱼类为主要食物来源，话题不一致，为无关项，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":102,"pid":"pc6b28bdffd"},{"qid":"16069795","no":29,"type":"逻辑判断","module":"判断推理","stem":"<p>小王、小李、小张分别负责公司产品策划、技术研发和市场推广三个项目中的某一项。已知负责产品策划的员工年终业绩得分低于小王；小李的业绩得分不是最低的；负责技术研发的员工业绩得分低于负责产品策划的员工。<br>根据以上信息，可以推出：</p>","options":[{"k":"A","t":"小王负责市场推广"},{"k":"B","t":"小张负责产品策划"},{"k":"C","t":"小李的业绩得分最高"},{"k":"D","t":"负责技术研发的员工比负责市场推广的业绩得分高"}],"answer":"A","multi":false,"explanation":"<p>第一步：分析题干条件。<br>（1）产品策划＜小王；<br>（2）小李的业绩得分不是最低的；<br>（3）技术研发＜产品策划；<br>（4）小王、小李、小张分别负责公司产品策划、技术研发和市场推广三个项目中的某一项。<br>第二步：根据题干条件进行推理。<br>题干中“产品策划”提及次数最多，优先从此处入手进行推理。<br>根据条件（1）和条件（3）可以得到：技术研发＜产品策划＜小王，结合条件（4）可知，小王负责市场推广；结合条件（2）和条件（4）可知，小李负责产品策划，小张负责技术研发，只有A项符合。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":103,"pid":"pc6b28bdffd"},{"qid":"16069806","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>要研发出安全可靠的通用人工智能，首先必须为其建立一套清晰的伦理边界。如果一个人工智能系统被植入了清晰的伦理边界，那么它在决策时就会主动规避潜在的伦理风险。只有主动规避潜在的伦理风险，该系统的大规模应用才能被认为是负责任的。此外，一个系统若要被认为是安全可靠的，其算法还必须通过全面的压力测试，只有通过了全面的压力测试，该系统的决策逻辑才算获得了初步的验证，从而真正迈向通用人工智能。<br>由此可以推出：</p>","options":[{"k":"A","t":"只要一个系统的决策逻辑获得了初步验证，它就是安全可靠的"},{"k":"B","t":"任何一个真正迈向通用人工智能的系统，其算法都必须通过全面的压力测试"},{"k":"C","t":"若人工智能系统的大规模应用被认为是负责任的，那么它一定植入了清晰的伦理边界"},{"k":"D","t":"如果一个系统未被植入清晰的伦理边界，它在决策时就不会主动规避潜在的伦理风险"}],"answer":"B","multi":false,"explanation":"<p>第一步：翻译题干。</p><p>①安全可靠的通用人工智能<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">建立一套清晰的伦理边界；</p><p>②植入了清晰的伦理边界<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">主动规避潜在的伦理风险；</p><p>③系统的大规模应用被认为是负责任的<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">主动规避潜在的伦理风险；</p><p>④系统被认为是安全可靠的<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">算法通过了全面的压力测试；</p><p>⑤真正迈向通用人工智能<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">决策逻辑获得了初步的验证<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">算法通过了全面的压力测试。</p><p>第二步：逐一分析选项。</p><p>A项：该项翻译为“决策逻辑获得了初步验证<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">系统是安全可靠的”，是对⑤第二个箭头前的肯定，可以推出“算法通过了全面的压力测试”，“算法通过了全面的压力测试”是对④箭头后的肯定，肯后得不到确定性的结论，无法推出，排除；</p><p>B项：该项翻译为“真正迈向通用人工智能<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">算法通过了全面的压力测试”，是对⑤第一个箭头前的肯定，肯前必肯后，可以推出，当选；</p><p>C项：该项翻译为“系统的大规模应用被认为是负责任的<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">植入了清晰的伦理边界”，是对③箭头前的肯定，可以推出“主动规避潜在的伦理风险”，“主动规避潜在的伦理风险”是对②箭头后的肯定，肯后得不到确定性的结论，不能推出，排除；</p><p>D项：该项翻译为“<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">被植入清晰的伦理边界<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">主动规避潜在的伦理风险”，是对②箭头前的否定，否前得不到确定性的结论，不能推出，排除。</p><p>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":104,"pid":"pc6b28bdffd"},{"qid":"16069813","no":1,"type":"综合","module":"资料分析","stem":"<p>2024年，我国有进出口实绩的企业约有多少万家？</p>","material":"<p>        2009年，民营企业进出口3.45万亿元，占同期我国进出口总额的22.9%，比重首次超过国有企业。2019年，民营企业进出口13.49万亿元，占同期我国进出口总额的42.7%，首次成为第一大外贸经营主体并保持至今。2024年，民营企业进出口占同期我国进出口总额的55.5%。2025年前两个月，民营企业进出口3.69万亿元。</p><p>        2022年，我国有进出口实绩的民营企业数量迈上50万家台阶。2024年，我国有进出口实绩的民营企业数量达60.9万家，占我国有进出口实绩企业的87.1%。</p><p>        2024年，民营企业出口高新技术产品3.05万亿元，较2019年增长94.5%，占我国同类商品出口比重较2019年（下同）提升17.5个百分点至48.6%。手机、汽车（包括底盘）、蓄电池、电脑、船舶出口额较2019年分别增长123.8%、10.5倍、461.6%、83.9%、375%，占比分别提升30.1个、18.3个、19.4个、11.2个、20.3个百分点至59.7%、51.5%、69.4%、27.2%、38.6%。2025年前两个月，民营企业上述商品出口额同比分别增长11.8%、11%、20.3%、1.7%、25.2%。</p><p>        2024年，民营企业进口大宗商品1.91万亿元，较2019年增长107.8%。同期，国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别较2019年下降8.6个、0.7个百分点至55.4%、9.3%。</p><p>        2025年前两个月，民营企业对传统市场（美国、欧盟、日本、我国香港地区、英国等）、东盟、拉美分别进出口1.26万亿元、6310.2亿元、3247.9亿元，同比分别增长4%、增长4.8%、下降1.3%。</p>","materialNo":1,"options":[{"k":"A","t":"57"},{"k":"B","t":"70"},{"k":"C","t":"81"},{"k":"D","t":"96"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2024年，我国有进出口实绩的企业约有多少万家”，结合材料给出了2024年有进出口实绩的民营企业数量及其占比，可判定本题为现期比重问题。定位文字材料第二段可得：2024年，我国有进出口实绩的民营企业数量达60.9万家，占我国有进出口实绩企业的87.1%。根据公式：整体<img src=\"assets/img/gongshi/formula-5330a9f4c84330f7.png\" class=\"tex\">，可得所求<img src=\"assets/img/gongshi/formula-4095ae4cb7b48d12.png\" class=\"tex\">万家。</p><p>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":105,"pid":"pc6b28bdffd"},{"qid":"16069815","no":2,"type":"比重","module":"资料分析","stem":"<p>将手机、蓄电池、船舶三类商品按2019年民营企业出口额占我国同类产品出口额比重从高到低排列，正确的是：</p>","material":"<p>        2009年，民营企业进出口3.45万亿元，占同期我国进出口总额的22.9%，比重首次超过国有企业。2019年，民营企业进出口13.49万亿元，占同期我国进出口总额的42.7%，首次成为第一大外贸经营主体并保持至今。2024年，民营企业进出口占同期我国进出口总额的55.5%。2025年前两个月，民营企业进出口3.69万亿元。</p><p>        2022年，我国有进出口实绩的民营企业数量迈上50万家台阶。2024年，我国有进出口实绩的民营企业数量达60.9万家，占我国有进出口实绩企业的87.1%。</p><p>        2024年，民营企业出口高新技术产品3.05万亿元，较2019年增长94.5%，占我国同类商品出口比重较2019年（下同）提升17.5个百分点至48.6%。手机、汽车（包括底盘）、蓄电池、电脑、船舶出口额较2019年分别增长123.8%、10.5倍、461.6%、83.9%、375%，占比分别提升30.1个、18.3个、19.4个、11.2个、20.3个百分点至59.7%、51.5%、69.4%、27.2%、38.6%。2025年前两个月，民营企业上述商品出口额同比分别增长11.8%、11%、20.3%、1.7%、25.2%。</p><p>        2024年，民营企业进口大宗商品1.91万亿元，较2019年增长107.8%。同期，国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别较2019年下降8.6个、0.7个百分点至55.4%、9.3%。</p><p>        2025年前两个月，民营企业对传统市场（美国、欧盟、日本、我国香港地区、英国等）、东盟、拉美分别进出口1.26万亿元、6310.2亿元、3247.9亿元，同比分别增长4%、增长4.8%、下降1.3%。</p>","materialNo":1,"options":[{"k":"A","t":"手机、船舶、蓄电池"},{"k":"B","t":"蓄电池、船舶、手机"},{"k":"C","t":"蓄电池、手机、船舶"},{"k":"D","t":"船舶、手机、蓄电池"}],"answer":"C","multi":false,"explanation":"<p>根据题干“······按2019年······比重从高到低排列······”，结合材料时间为2024年，可判定本题为基期比重问题。定位文字材料第三段可得：2024年，手机、蓄电池、船舶出口额占比较2019年分别提升30.1个、19.4个、20.3个百分点至59.7%、69.4%、38.6%。则2019年这三类商品占比分别为：手机=59.7%-30.1%=29.6%、蓄电池=69.4%-19.4%=50%、船舶=38.6%-20.3%=18.3%。综上，2019年所占比重从高到低排列为蓄电池、手机、船舶。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":106,"pid":"pc6b28bdffd"},{"qid":"16069817","no":3,"type":"综合","module":"资料分析","stem":"<p>2019年，国有企业大宗商品进口额约是外商投资企业大宗商品进口额的多少倍？</p>","material":"<p>        2009年，民营企业进出口3.45万亿元，占同期我国进出口总额的22.9%，比重首次超过国有企业。2019年，民营企业进出口13.49万亿元，占同期我国进出口总额的42.7%，首次成为第一大外贸经营主体并保持至今。2024年，民营企业进出口占同期我国进出口总额的55.5%。2025年前两个月，民营企业进出口3.69万亿元。</p><p>        2022年，我国有进出口实绩的民营企业数量迈上50万家台阶。2024年，我国有进出口实绩的民营企业数量达60.9万家，占我国有进出口实绩企业的87.1%。</p><p>        2024年，民营企业出口高新技术产品3.05万亿元，较2019年增长94.5%，占我国同类商品出口比重较2019年（下同）提升17.5个百分点至48.6%。手机、汽车（包括底盘）、蓄电池、电脑、船舶出口额较2019年分别增长123.8%、10.5倍、461.6%、83.9%、375%，占比分别提升30.1个、18.3个、19.4个、11.2个、20.3个百分点至59.7%、51.5%、69.4%、27.2%、38.6%。2025年前两个月，民营企业上述商品出口额同比分别增长11.8%、11%、20.3%、1.7%、25.2%。</p><p>        2024年，民营企业进口大宗商品1.91万亿元，较2019年增长107.8%。同期，国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别较2019年下降8.6个、0.7个百分点至55.4%、9.3%。</p><p>        2025年前两个月，民营企业对传统市场（美国、欧盟、日本、我国香港地区、英国等）、东盟、拉美分别进出口1.26万亿元、6310.2亿元、3247.9亿元，同比分别增长4%、增长4.8%、下降1.3%。</p>","materialNo":1,"options":[{"k":"A","t":"5.2"},{"k":"B","t":"5.8"},{"k":"C","t":"6.4"},{"k":"D","t":"7.0"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2019年······是······的多少倍”，结合材料时间为2024年，可判定本题为基期倍数问题。定位文字材料第四段可得：2024年，国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别较2019年下降8.6个、0.7个百分点至55.4%、9.3%。则2019年国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别为55.4%+8.6%=64%、9.3%+0.7%=10%。则题干所求倍数<img src=\"assets/img/gongshi/formula-45ed2377b26312c2.png\" class=\"tex\">。</p><p>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":107,"pid":"pc6b28bdffd"},{"qid":"16069865","no":4,"type":"比重","module":"资料分析","stem":"<p>关于2025年前两个月民营企业进出口总额，以下饼图能准确反映传统市场（白色）、东盟（灰色）和其他地区（黑色）占比关系的是：</p>","material":"<p>        2009年，民营企业进出口3.45万亿元，占同期我国进出口总额的22.9%，比重首次超过国有企业。2019年，民营企业进出口13.49万亿元，占同期我国进出口总额的42.7%，首次成为第一大外贸经营主体并保持至今。2024年，民营企业进出口占同期我国进出口总额的55.5%。2025年前两个月，民营企业进出口3.69万亿元。</p><p>        2022年，我国有进出口实绩的民营企业数量迈上50万家台阶。2024年，我国有进出口实绩的民营企业数量达60.9万家，占我国有进出口实绩企业的87.1%。</p><p>        2024年，民营企业出口高新技术产品3.05万亿元，较2019年增长94.5%，占我国同类商品出口比重较2019年（下同）提升17.5个百分点至48.6%。手机、汽车（包括底盘）、蓄电池、电脑、船舶出口额较2019年分别增长123.8%、10.5倍、461.6%、83.9%、375%，占比分别提升30.1个、18.3个、19.4个、11.2个、20.3个百分点至59.7%、51.5%、69.4%、27.2%、38.6%。2025年前两个月，民营企业上述商品出口额同比分别增长11.8%、11%、20.3%、1.7%、25.2%。</p><p>        2024年，民营企业进口大宗商品1.91万亿元，较2019年增长107.8%。同期，国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别较2019年下降8.6个、0.7个百分点至55.4%、9.3%。</p><p>        2025年前两个月，民营企业对传统市场（美国、欧盟、日本、我国香港地区、英国等）、东盟、拉美分别进出口1.26万亿元、6310.2亿元、3247.9亿元，同比分别增长4%、增长4.8%、下降1.3%。</p>","materialNo":1,"options":[{"k":"A","t":"<p><img src=\"assets/img/timu/19cebc34db0fb7d.png\" class=\"fig\" style=\"width:200px;height:195px;\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/timu/19cebf56735af25.png\" class=\"fig\" style=\"width:204px;height:201px;\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/timu/19cebc39e988cf0.png\" class=\"fig\" style=\"width:200px;height:201px;\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/timu/19cebc3bed1aebd.png\" class=\"fig\" style=\"width:200px;height:197px;\"></p>"}],"answer":"A","multi":false,"explanation":"<p>根据题干“······2025年前两个月······占比关系的是”，结合材料时间涉及2025年前两个月，可判定本题为现期比重问题。定位文字材料第一段可得：2025年前两个月，民营企业进出口3.69万亿元；定位文字材料第五段可得：2025年前两个月，民营企业对传统市场、东盟分别进出口1.26万亿元、6310.2亿元。根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，</p><p>则民营企业进出口总额中，对传统市场和东盟所占比重之和为<img src=\"assets/img/gongshi/formula-b953aebeb11c0553.png\" class=\"tex\">稍大于50%，排除C、D两项；民营企业对传统市场进出口额是对东盟进出口额的<img src=\"assets/img/gongshi/formula-4f8758086c2936ef.png\" class=\"tex\">倍，排除B项。</p><p>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":108,"pid":"pc6b28bdffd"},{"qid":"16069885","no":5,"type":"综合","module":"资料分析","stem":"<p>能够从上述资料中推出的是：</p>","material":"<p>        2009年，民营企业进出口3.45万亿元，占同期我国进出口总额的22.9%，比重首次超过国有企业。2019年，民营企业进出口13.49万亿元，占同期我国进出口总额的42.7%，首次成为第一大外贸经营主体并保持至今。2024年，民营企业进出口占同期我国进出口总额的55.5%。2025年前两个月，民营企业进出口3.69万亿元。</p><p>        2022年，我国有进出口实绩的民营企业数量迈上50万家台阶。2024年，我国有进出口实绩的民营企业数量达60.9万家，占我国有进出口实绩企业的87.1%。</p><p>        2024年，民营企业出口高新技术产品3.05万亿元，较2019年增长94.5%，占我国同类商品出口比重较2019年（下同）提升17.5个百分点至48.6%。手机、汽车（包括底盘）、蓄电池、电脑、船舶出口额较2019年分别增长123.8%、10.5倍、461.6%、83.9%、375%，占比分别提升30.1个、18.3个、19.4个、11.2个、20.3个百分点至59.7%、51.5%、69.4%、27.2%、38.6%。2025年前两个月，民营企业上述商品出口额同比分别增长11.8%、11%、20.3%、1.7%、25.2%。</p><p>        2024年，民营企业进口大宗商品1.91万亿元，较2019年增长107.8%。同期，国有企业、外商投资企业大宗商品进口额占我国大宗商品进口额比重分别较2019年下降8.6个、0.7个百分点至55.4%、9.3%。</p><p>        2025年前两个月，民营企业对传统市场（美国、欧盟、日本、我国香港地区、英国等）、东盟、拉美分别进出口1.26万亿元、6310.2亿元、3247.9亿元，同比分别增长4%、增长4.8%、下降1.3%。</p>","materialNo":1,"options":[{"k":"A","t":"2024年3-12月民营企业进出口总额"},{"k":"B","t":"2024年前两个月民营企业高新技术产品出口额"},{"k":"C","t":"2024年前两个月民营企业手机、电脑进出口总额"},{"k":"D","t":"2024年非民营企业高新技术产品出口额相较2019年增速"}],"answer":"D","multi":false,"explanation":"<p>A项：定位文字材料第一段可得：2024年民营企业进出口占同期我国进出口总额的55.5%，2025年前两个月民营企业进出口3.69万亿元。没有给出2024年3-12月民营企业进出口总额相关数据，无法推出，错误；</p><p>B项：定位文字材料第三段可得：2024年民营企业出口高新技术产品3.05万亿元。没有给出2024年前两个月民营企业高新技术产品出口额相关数据，无法推出，错误；</p><p>C项：定位文字材料第三段可得：2024年民营企业手机、电脑出口额较2019年的增速及比重变化，2025年前两个月民营企业手机、电脑出口额的同比增速。没有给出2024年前两个月民营企业手机、电脑进出口总额相关数据，无法推出，错误；</p><p>D项：定位文字材料第三段可得：2024年民营企业出口高新技术产品3.05万亿元，较2019年增长94.5%，占我国同类商品出口比重较2019年（下同）提升17.5个百分点至48.6%。则2024年非民营企业高新技术产品出口额=高新技术产品出口额-民营企业高新技术产品出口额<img src=\"assets/img/gongshi/formula-0148c627e981be10.png\" class=\"tex\">万亿元，2019年非民营企业高新技术产品出口额<img src=\"assets/img/gongshi/formula-7ae24c0d36f9900c.png\" class=\"tex\">万亿元。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，2024年非民营企业高新技术产品出口额相较2019年的增速<img src=\"assets/img/gongshi/formula-32c0e8440daa3afc.png\" class=\"tex\">，可以推出，正确。</p><p>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":109,"pid":"pc6b28bdffd"},{"qid":"16069826","no":6,"type":"平均数","module":"资料分析","stem":"<p>2025年，我国服装整体市场规模比2020~2024年间的平均值高：</p>","material":"<p><img src=\"assets/img/timu/19ceb4fa69ebbc7.png\" class=\"fig\" style=\"width:565px;height:452px;\"></p>","materialNo":2,"options":[{"k":"A","t":"不到1000亿元"},{"k":"B","t":"1000~1300亿元"},{"k":"C","t":"1300~1600亿元"},{"k":"D","t":"1600亿元以上"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2025年······比2020~2024年间的平均值高”，可判定本题为现期平均数问题。定位统计表可得：2020~2025年我国服装整体市场规模分别为19600.7亿元、21938.2亿元、19950.5亿元、21619.5亿元、21698.2亿元、22049.5亿元。则所求<img src=\"assets/img/gongshi/formula-a768790fc1cd7ce8.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7daaa0e09e5d0f38.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-95dca307989c9201.png\" class=\"tex\">亿元，在B项范围内。</p><p>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":110,"pid":"pc6b28bdffd"},{"qid":"16069828","no":7,"type":"比重","module":"资料分析","stem":"<p>2025年，我国运动鞋类市场规模占鞋类市场规模的比重比运动服装占服装市场规模的比重高约多少个百分点？</p>","material":"<p><img src=\"assets/img/timu/19ceb4fa69ebbc7.png\" class=\"fig\" style=\"width:565px;height:452px;\"></p>","materialNo":2,"options":[{"k":"A","t":"37"},{"k":"B","t":"41"},{"k":"C","t":"45"},{"k":"D","t":"49"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2025年······比重高约多少个百分点”，可判定本题为现期比重问题。定位表格材料可得：2025年我国鞋类市场规模4787.7亿元，其中运动鞋类市场规模2393.7亿元；我国服装市场规模22049.5亿元，其中运动服装市场规模1982.8亿元。根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，则题干所求<img src=\"assets/img/gongshi/formula-770422f9b8778700.png\" class=\"tex\">，即高约41个百分点。</p><p>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":111,"pid":"pc6b28bdffd"},{"qid":"16069831","no":8,"type":"增长","module":"资料分析","stem":"<p>如保持2025年同比增量不变，我国运动服装市场规模将在哪一年首次超过运动鞋类市场规模？</p>","material":"<p><img src=\"assets/img/timu/19ceb4fa69ebbc7.png\" class=\"fig\" style=\"width:565px;height:452px;\"></p>","materialNo":2,"options":[{"k":"A","t":"2034年"},{"k":"B","t":"2035年"},{"k":"C","t":"2036年"},{"k":"D","t":"2037年"}],"answer":"A","multi":false,"explanation":"<p>根据题干“如保持2025年同比增量不变······将在哪一年首次超过······”，可判定本题为现期计算问题。定位统计表可得：2024年我国运动服装市场规模为1831.1亿元，运动鞋类市场规模为2292.6亿元；2025年我国运动服装市场规模为1982.8亿元，运动鞋类市场规模为2393.7亿元。根据公式：增长量=现期量-基期量，可得2025年我国运动服装市场规模同比增量=1982.8-1831.1=151.7亿元，我国运动鞋类市场规模同比增量=2393.7-2292.6=101.1亿元。根据公式：现期量=基期量+增长量×n，可列式：1982.8+151.7×n&gt;2393.7+101.1×n，解得n&gt;8.1，则n取整最小为9，即如保持2025年同比增量不变，我国运动服装市场规模将在2025+9=2034年首次超过运动鞋类市场规模。<br>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":112,"pid":"pc6b28bdffd"},{"qid":"16069832","no":9,"type":"增长","module":"资料分析","stem":"<p>以下柱状图反映了2022~2025年间，哪一类商品市场规模同比增量的变化趋势（横轴位置代表增量为0）？</p><p><img src=\"assets/img/timu/19ceb55405d747d.png\" class=\"fig\" style=\"width:462px;height:270px;\"></p>","material":"<p><img src=\"assets/img/timu/19ceb4fa69ebbc7.png\" class=\"fig\" style=\"width:565px;height:452px;\"></p>","materialNo":2,"options":[{"k":"A","t":"户外服装"},{"k":"B","t":"时尚服装"},{"k":"C","t":"功能鞋类"},{"k":"D","t":"时尚鞋类"}],"answer":"C","multi":false,"explanation":"<p>根据题干“以下柱状图反映了2022~2025年间······同比增量的变化趋势（横轴位置代表增量为0）”，可判定本题为增长量比较问题。定位统计表可得2021~2025年我国户外服装、时尚服装、功能鞋类、时尚鞋类各年份市场规模。根据公式：增长量=现期量-基期量，结合柱形图变化趋势分析如下：<br>A项，户外服装，2022年同比增长量=260.7-221.9&gt;0，而柱状图中2022年同比增长量为负，不符合柱状图变化趋势，排除；<br>B项，时尚服装，2022年同比增长量=673.1−771.9=−98.8亿元，2023年同比增长量=753.4−673.1=80.3亿元，2022年同比增长量的绝对值（98.8亿元）&gt;2023年同比增长量的绝对值（80.3亿元），不符合柱状图变化趋势，排除；<br>C项，功能鞋类，2022年同比增长量=735.6−749.1=-13.5亿元，2023年同比增长量=857.0−735.6=121.4亿元，2024年同比增长量=915.2−857.0=58.2亿元，2025年同比增长量=973.6−915.2=58.4亿元，符合柱状图变化趋势，当选；<br>D项，时尚鞋类，2022年同比增长量=1094.3−1176.7=−82.4亿元，2023年同比增长量=1185.7−1094.3=91.4亿元，2023年同比增长量的绝对值（91.4亿元）是2022年同比增长量绝对值（82.4亿元）的1倍多，而柱状图中前者是后者的好几倍，不符合柱状图变化趋势，排除。<br>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":113,"pid":"pc6b28bdffd"},{"qid":"16069834","no":10,"type":"综合","module":"资料分析","stem":"<p>不能从上述资料中推出的是：</p>","material":"<p><img src=\"assets/img/timu/19ceb4fa69ebbc7.png\" class=\"fig\" style=\"width:565px;height:452px;\"></p>","materialNo":2,"options":[{"k":"A","t":"2023~2025年，我国非运动服装市场规模不到6万亿元"},{"k":"B","t":"2023~2025年，我国功能服装市场规模同比增速逐年加快"},{"k":"C","t":"2021~2025年，我国非运动鞋类市场规模比运动鞋类高不到1万亿元"},{"k":"D","t":"2025年，我国功能鞋类市场规模同比增量占运动鞋类市场规模同比增量的一半以上"}],"answer":"B","multi":false,"explanation":"<p>A项：定位统计表可得，2023~2025年各年份我国非运动服装市场规模分别为19946.3亿元、19867.1亿元、20066.7亿元。则2023~2025年，我国非运动服装市场规模为19946.3+19867.1+20066.7=59880.1亿元&lt;6万亿元，正确；</p><p>B项：定位统计表可得，2022~2025年各年份我国功能服装市场规模分别为495.9亿元、580.6亿元、612.5亿元、643.1亿元。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，则2023年我国功能服装市场规模同比增速<img src=\"assets/img/gongshi/formula-7af366aede5f2273.png\" class=\"tex\">，2024年我国功能服装市场规模同比增速<img src=\"assets/img/gongshi/formula-e87d6c74e5aa767e.png\" class=\"tex\">，2023年同比增速&gt;2024年同比增速，同比增速并非逐年加快，错误；</p><p>C项：定位统计表可得，2021~2025年各年份我国非运动鞋类和运动鞋类市场规模。则所求=2641.2+2286.9+2455.9+2414.3+2394.0-（2029.3+1947.5+2186.3+2292.6+2393.7）<img src=\"assets/img/gongshi/formula-2ee93fe9e223e4c6.png\" class=\"tex\">2600＋2300+2500+2400+2400-（2000+1900+2200+2300+2400）=12200-10800=1400亿元&lt;1万亿元，正确；</p><p>D项：定位统计表可得，2024年、2025年我国功能鞋类市场规模分别为915.2亿元、973.6亿元，运动鞋类市场规模分别为2292.6亿元、2393.7亿元。根据公式：增长量=现期量-基期量、比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，则所求<img src=\"assets/img/gongshi/formula-eadbfd083423fc52.png\" class=\"tex\">，正确。</p><p>本题为选非题，故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":114,"pid":"pc6b28bdffd"},{"qid":"16069867","no":11,"type":"综合","module":"资料分析","stem":"<p>2025年12月，我国除纯电动和插电式混动之外的新能源汽车销量占汽车总销量的：</p>","material":"<p>        2025年12月，我国新能源汽车产销量分别为171.8万辆和171万辆，同比分别增长12.3%和7.2%，环比分别下降8.6%和6.2%。其中，纯电动车销量110.8万辆，同比增长13.8%，环比下降5.3%；插电式混动销量59.9万辆，同比下降3.7%，环比下降8.1%。2025年新能源汽车产销量分别为1662.6万辆和1649万辆，同比分别增长29%和28.2%。其中，纯电动车销量1062.2万辆，同比增长37.6%；插电式混动销量586.1万辆，同比增长14%。2025年新能源汽车渗透率（新能源汽车销量占汽车销量比重）47.9%，同比上升7个百分点；12月新能源汽车渗透率52.3%，环比下降0.9个百分点。2025年新能源汽车出口261.5万辆，同比增长1倍；12月新能源汽车出口30万辆，同比增长1.2倍，环比下降0.1%。</p><p>        2025年12月，我国动力和储能电池产量201.7GWh（1GWh=100万千瓦时），环比增长14.4%，同比增长62.1%；销量199.3GWh，环比增长11.1%，同比增长57.5%。其中，动力电池销量143.8GWh，环比增长7.3%，同比增长49.2%。出口方面：12月我国动力和储能电池出口32.6GWh。其中，动力电池出口量19GWh，环比减少10.4%，同比增长47.1%，储能电池出口量13.6GWh，环比增长23.9%，同比增长52.2%。装车量方面：12月国内动力电池装车量（生产的新能源汽车上安装的所有动力电池的总能量）98.1GWh，环比增长4.9%，同比增长35.1%。</p>","materialNo":3,"options":[{"k":"A","t":"不到0.1%"},{"k":"B","t":"0.1%~0.3%"},{"k":"C","t":"0.3%~0.6%"},{"k":"D","t":"0.6%以上"}],"answer":"A","multi":false,"explanation":"<p>根据题干“2025年12月······占······”，结合材料时间为2025年12月，可判定本题为现期比重问题。定位文字材料第一段可知：2025年12月，我国新能源汽车销量为171万辆，纯电动车销量110.8万辆，插电式混动销量59.9万辆，新能源汽车渗透率（新能源汽车销量占汽车销量比重）52.3%。根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，则题干所求为<img src=\"assets/img/gongshi/formula-5d1c82acf154f195.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-341b2d275e64459f.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-d4969f4bc350a594.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-5d5889d7a39f2c08.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-6162e0bd25ec58cd.png\" class=\"tex\">，在A项范围内。</p><p>故正确答案为A。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":115,"pid":"pc6b28bdffd"},{"qid":"16069868","no":12,"type":"综合","module":"资料分析","stem":"<p>2024年12月，我国新能源汽车出口量比2024年月均出口量：</p>","material":"<p>        2025年12月，我国新能源汽车产销量分别为171.8万辆和171万辆，同比分别增长12.3%和7.2%，环比分别下降8.6%和6.2%。其中，纯电动车销量110.8万辆，同比增长13.8%，环比下降5.3%；插电式混动销量59.9万辆，同比下降3.7%，环比下降8.1%。2025年新能源汽车产销量分别为1662.6万辆和1649万辆，同比分别增长29%和28.2%。其中，纯电动车销量1062.2万辆，同比增长37.6%；插电式混动销量586.1万辆，同比增长14%。2025年新能源汽车渗透率（新能源汽车销量占汽车销量比重）47.9%，同比上升7个百分点；12月新能源汽车渗透率52.3%，环比下降0.9个百分点。2025年新能源汽车出口261.5万辆，同比增长1倍；12月新能源汽车出口30万辆，同比增长1.2倍，环比下降0.1%。</p><p>        2025年12月，我国动力和储能电池产量201.7GWh（1GWh=100万千瓦时），环比增长14.4%，同比增长62.1%；销量199.3GWh，环比增长11.1%，同比增长57.5%。其中，动力电池销量143.8GWh，环比增长7.3%，同比增长49.2%。出口方面：12月我国动力和储能电池出口32.6GWh。其中，动力电池出口量19GWh，环比减少10.4%，同比增长47.1%，储能电池出口量13.6GWh，环比增长23.9%，同比增长52.2%。装车量方面：12月国内动力电池装车量（生产的新能源汽车上安装的所有动力电池的总能量）98.1GWh，环比增长4.9%，同比增长35.1%。</p>","materialNo":3,"options":[{"k":"A","t":"低不到1万辆"},{"k":"B","t":"低1万辆以上"},{"k":"C","t":"高不到1万辆"},{"k":"D","t":"高1万辆以上"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2024年12月······比2024年月均······”，结合材料时间为2025年，可判定本题为基期和差问题。定位文字材料第一段可知：2025年新能源汽车出口261.5万辆，同比增长1倍；12月新能源汽车出口30万辆，同比增长1.2倍。根据公式：基期量<img src=\"assets/img/gongshi/formula-0136d9c7a25c249d.png\" class=\"tex\">、平均数<img src=\"assets/img/gongshi/formula-93cc026ba1bfce7e.png\" class=\"tex\">，可得2024年12月我国新能源汽车出口量<img src=\"assets/img/gongshi/formula-315bf62ca241c07e.png\" class=\"tex\">万辆；2024年我国新能源汽车月均出口量<img src=\"assets/img/gongshi/formula-e869858b7e586260.png\" class=\"tex\">万辆，则所求差值=13.6−10.9&gt;1万辆，即高1万辆以上。</p><p>故正确答案为D。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":116,"pid":"pc6b28bdffd"},{"qid":"16069869","no":13,"type":"综合","module":"资料分析","stem":"<p>2025年11月，我国动力电池出口量约是储能电池出口量的多少倍？</p>","material":"<p>        2025年12月，我国新能源汽车产销量分别为171.8万辆和171万辆，同比分别增长12.3%和7.2%，环比分别下降8.6%和6.2%。其中，纯电动车销量110.8万辆，同比增长13.8%，环比下降5.3%；插电式混动销量59.9万辆，同比下降3.7%，环比下降8.1%。2025年新能源汽车产销量分别为1662.6万辆和1649万辆，同比分别增长29%和28.2%。其中，纯电动车销量1062.2万辆，同比增长37.6%；插电式混动销量586.1万辆，同比增长14%。2025年新能源汽车渗透率（新能源汽车销量占汽车销量比重）47.9%，同比上升7个百分点；12月新能源汽车渗透率52.3%，环比下降0.9个百分点。2025年新能源汽车出口261.5万辆，同比增长1倍；12月新能源汽车出口30万辆，同比增长1.2倍，环比下降0.1%。</p><p>        2025年12月，我国动力和储能电池产量201.7GWh（1GWh=100万千瓦时），环比增长14.4%，同比增长62.1%；销量199.3GWh，环比增长11.1%，同比增长57.5%。其中，动力电池销量143.8GWh，环比增长7.3%，同比增长49.2%。出口方面：12月我国动力和储能电池出口32.6GWh。其中，动力电池出口量19GWh，环比减少10.4%，同比增长47.1%，储能电池出口量13.6GWh，环比增长23.9%，同比增长52.2%。装车量方面：12月国内动力电池装车量（生产的新能源汽车上安装的所有动力电池的总能量）98.1GWh，环比增长4.9%，同比增长35.1%。</p>","materialNo":3,"options":[{"k":"A","t":"1.3"},{"k":"B","t":"1.6"},{"k":"C","t":"1.9"},{"k":"D","t":"2.2"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2025年11月······约是······的多少倍”，结合材料时间为2025年12月，可判定本题为基期倍数问题。定位文字材料第二段可得：2025年12月，我国动力电池出口量19GWh（A），环比减少10.4%（a）；储能电池出口量13.6GWh（B），环比增长23.9%（b）。根据公式：基期倍数<img src=\"assets/img/gongshi/formula-521802a0700de64f.png\" class=\"tex\">，则所求为<img src=\"assets/img/gongshi/formula-a9df4898766160b9.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-bf37831d4408255b.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-e6f6baf5424b09bd.png\" class=\"tex\">，与C项最接近。</p><p>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":117,"pid":"pc6b28bdffd"},{"qid":"16069870","no":14,"type":"平均数","module":"资料分析","stem":"<p>2025年12月国内平均每生产1辆新能源汽车安装的动力电池能量比上月：</p>","material":"<p>        2025年12月，我国新能源汽车产销量分别为171.8万辆和171万辆，同比分别增长12.3%和7.2%，环比分别下降8.6%和6.2%。其中，纯电动车销量110.8万辆，同比增长13.8%，环比下降5.3%；插电式混动销量59.9万辆，同比下降3.7%，环比下降8.1%。2025年新能源汽车产销量分别为1662.6万辆和1649万辆，同比分别增长29%和28.2%。其中，纯电动车销量1062.2万辆，同比增长37.6%；插电式混动销量586.1万辆，同比增长14%。2025年新能源汽车渗透率（新能源汽车销量占汽车销量比重）47.9%，同比上升7个百分点；12月新能源汽车渗透率52.3%，环比下降0.9个百分点。2025年新能源汽车出口261.5万辆，同比增长1倍；12月新能源汽车出口30万辆，同比增长1.2倍，环比下降0.1%。</p><p>        2025年12月，我国动力和储能电池产量201.7GWh（1GWh=100万千瓦时），环比增长14.4%，同比增长62.1%；销量199.3GWh，环比增长11.1%，同比增长57.5%。其中，动力电池销量143.8GWh，环比增长7.3%，同比增长49.2%。出口方面：12月我国动力和储能电池出口32.6GWh。其中，动力电池出口量19GWh，环比减少10.4%，同比增长47.1%，储能电池出口量13.6GWh，环比增长23.9%，同比增长52.2%。装车量方面：12月国内动力电池装车量（生产的新能源汽车上安装的所有动力电池的总能量）98.1GWh，环比增长4.9%，同比增长35.1%。</p>","materialNo":3,"options":[{"k":"A","t":"低不到10千瓦时"},{"k":"B","t":"低10千瓦时以上"},{"k":"C","t":"高不到10千瓦时"},{"k":"D","t":"高10千瓦时以上"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2025年12月······平均每······比上月”，结合选项高/低+具体单位，可判定本题为平均数的增长量问题。定位文字材料第一段可得：2025年12月，我国新能源汽车产量为171.8万辆（B），环比下降8.6%（b）；定位文字材料第二段可得：2025年12月，国内动力电池装车量（生产的新能源汽车上安装的所有动力电池的总能量）98.1GWh（A），环比增长4.9%（a）。根据公式：平均数的增长量<img src=\"assets/img/gongshi/formula-3c9d63de277eabdc.png\" class=\"tex\">，可得所求为<img src=\"assets/img/gongshi/formula-8b14d33f036c0c61.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-4782bdbb19045c36.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-6d1b970a7e6a8a88.png\" class=\"tex\">千瓦时/辆，即高不到10千瓦时/辆。</p><p>故正确答案为C。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":118,"pid":"pc6b28bdffd"},{"qid":"16069871","no":15,"type":"增长","module":"资料分析","stem":"<p>在上述资料信息中以下哪项可以推出？<br>①2024年12月新能源汽车出口量占汽车出口量比重<br>②2025年12月储能电池销量同比增长速度</p>","material":"<p>        2025年12月，我国新能源汽车产销量分别为171.8万辆和171万辆，同比分别增长12.3%和7.2%，环比分别下降8.6%和6.2%。其中，纯电动车销量110.8万辆，同比增长13.8%，环比下降5.3%；插电式混动销量59.9万辆，同比下降3.7%，环比下降8.1%。2025年新能源汽车产销量分别为1662.6万辆和1649万辆，同比分别增长29%和28.2%。其中，纯电动车销量1062.2万辆，同比增长37.6%；插电式混动销量586.1万辆，同比增长14%。2025年新能源汽车渗透率（新能源汽车销量占汽车销量比重）47.9%，同比上升7个百分点；12月新能源汽车渗透率52.3%，环比下降0.9个百分点。2025年新能源汽车出口261.5万辆，同比增长1倍；12月新能源汽车出口30万辆，同比增长1.2倍，环比下降0.1%。</p><p>        2025年12月，我国动力和储能电池产量201.7GWh（1GWh=100万千瓦时），环比增长14.4%，同比增长62.1%；销量199.3GWh，环比增长11.1%，同比增长57.5%。其中，动力电池销量143.8GWh，环比增长7.3%，同比增长49.2%。出口方面：12月我国动力和储能电池出口32.6GWh。其中，动力电池出口量19GWh，环比减少10.4%，同比增长47.1%，储能电池出口量13.6GWh，环比增长23.9%，同比增长52.2%。装车量方面：12月国内动力电池装车量（生产的新能源汽车上安装的所有动力电池的总能量）98.1GWh，环比增长4.9%，同比增长35.1%。</p>","materialNo":3,"options":[{"k":"A","t":"仅①能从上述资料推出"},{"k":"B","t":"仅②能从上述资料推出"},{"k":"C","t":"两者都能从上述资料推出"},{"k":"D","t":"都不能"}],"answer":"B","multi":false,"explanation":"<p>①定位文字材料第一段可得：2025年12月新能源汽车出口30万辆，同比增长1.2倍。材料并未给出汽车出口量相关数据，故无法计算2024年12月新能源汽车出口量占汽车出口量比重，则无法推出；</p><p>②定位文字材料第二段可得：2025年12月，我国动力和储能电池销量199.3GWh，同比增长57.5%。其中，动力电池销量143.8GWh，同比增长49.2%。则2025年12月我国储能电池销量为199.3-143.8=55.5GWh。设2025年12月储能电池销量同比增速为r，根据线段法：距离（增长率之差）与量（基期量）成反比，可列式：<img src=\"assets/img/gongshi/formula-56e91a15b7546448.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-b5c8b03264c86437.png\" class=\"tex\">，则可以推出。</p><p>综上可知，仅②能从上述资料推出。</p><p>故正确答案为B。</p>","from":{"file":"2026年福建省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":119,"pid":"pc6b28bdffd"}]};
